INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021175', 'AN1924', '宮村伊澄', '宮村は、そのひそやかな性格のせいで、よくオタクと間違えられる。彼が長い髪や服で身を隠しているのは、ピアスや数え切れないほどのタトゥーを隠すためなのだ。これは、堀と石川だけが知っている秘密だ。  泉はとても思いやりのある少年だ。見た目は弱そうだが、実はとても強い。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b66173-g8eU1LGWPB8O.png', '4月17日', NULL, '内山昂輝', 169, 66173, 'MAIN', 15841) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021176', 'AN1924', '堀京子', '堀京子は、宮村伊澄と並んで『ホリミヤ』の主要な主人公の一人です。彼女は片桐高校3年1組の生徒です。京子は概してとても元気で人気者であり、いつも周囲を明るい雰囲気に包んでいます。 彼女は生活のあらゆる面で努力家であり、宮村伊澄によると、テストの成績はすべて90％以上をキープしているという。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b66171-o2vk3689wWFK.png', '3月25日', NULL, '戸松遥', 163, 66171, 'MAIN', 12408) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021177', 'AN1924', '柳明音', '彼は片桐高校の3年生で、堀と宮村の常連の友人グループの一員である。3年6組に在籍している。視力が非常に悪く、眼鏡をかけないとまともに物が見えない。', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b72453-f9gRbQBUjKo6.png', '12月28日', NULL, '福山潤', 168, 72453, 'SUPPORTING', 1175) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021178', 'AN1924', '西貴子', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b203892-t0pUbFpAjheN.png', NULL, NULL, '高田憂希', NULL, 203892, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021179', 'AN1924', '奥山有菜', 'ユンナはソタの同級生だ。彼女はソタをいじめているが、実は彼のことがとても好きだ。堀京子は彼女の憧れの存在だ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b66971-yfKmxIsWKWyR.jpg', NULL, NULL, '古賀葵', NULL, 66971, 'SUPPORTING', 65) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021180', 'AN1924', '井浦基子', '彼女は井浦秀の妹である。自らを「無口で陰気なタイプ」と評する元子は、秀とは正反対の性格だ。一人でいることが多く、友達を作るのが苦手だ。 しかし、修とは異なり、この性格は学校生活にも表れており、他人に対しては控えめなものの、兄に対してははるかに強引で暴力的になる。また、彼女はかなり頭が良いが、その能力を十分に活かす自信に欠けている。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b72467-PpdDmPQFbaMC.png', '5月14日', NULL, '金元寿子', 150, 72467, 'SUPPORTING', 146) ON CONFLICT DO NOTHING;
