INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021184', 'AN1924', '谷原マキオ', '彼はカシ高校に通う高校3年生だ。宮村や新藤と同じ中学校に通っていた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b72465-IVbmlZUoptvt.jpg', '4月16日', NULL, '千葉翔也', 168, 72465, 'SUPPORTING', 61) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021185', 'AN1924', '安田真', '職業：英語教師　所属：片桐高校生徒会（役員）　『ホリミヤ』の脇役の一人である。安田は女子高生が大好きで、それを隠そうともしていない。 しかし、実際に女子生徒に触れることは決してなく、ただ彼女たちには過度に親しげに振る舞い、男子生徒たちには過度に冷たく接するだけだ。彼はよく、彼女がいる男子生徒（主に宮村や仙石）に対し、自分がその女子生徒を独り占めできるようにと、別れを迫ることがある。彼が一緒にいるときはいつでも', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b66975-1ENOxQZ7SJPm.png', NULL, NULL, '津田健次郎', NULL, 66975, 'SUPPORTING', 124) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021186', 'AN1924', '石川透', 'トオルは誰に対しても親しみやすく、穏やかな性格だ。彼は片桐高校に通っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b66961-VZV5IwKUwYfp.png', '10月1日', NULL, '山下誠一郎', 174, 66961, 'SUPPORTING', 1493) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021187', 'AN1924', '堀百合子', '彼女は京子とソータの母親です。', 36, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b78279-Vyv16wSznsYl.jpg', NULL, NULL, '茅野愛衣', NULL, 78279, 'SUPPORTING', 210) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021188', 'AN1924', '溝内大樹', '彼は堀と宮村の同級生の一人だ。同じ学校に通っており、同じ3年1組に在籍している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b72457-urLH3qxflfRj.png', '8月24日', NULL, '石谷春貴', 176, 72457, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021189', 'AN1924', '仙石翔', '彼は、片桐高校の生徒会会長であり、3年3組に在籍するカリスマ的な人物で、堀京子の幼なじみであり、綾崎レミの彼氏でもある。  仙石は、少し内気で恥ずかしがり屋な少年であり、些細なことで怯えてしまうほど臆病で、特にホラーや虫に関するものには恐怖で縮こまってしまう。仙石は非常に頭が良くて真面目な性格で、普段は学内で1位（体育の成績は2位）を維持している。 読書が好きで、信じられないほどの……', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b72447-SH9Hth8ZGJam.png', '5月9日', NULL, '岡本信彦', 170, 72447, 'SUPPORTING', 756) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021190', 'AN1924', '進藤晃一', '彼はこのシリーズの脇役だ。彼は泉や真生と同じ中学校に通っていた。', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b72461-4zzQ6cShYe8l.png', '4月2日', NULL, '八代拓', 173, 72461, 'SUPPORTING', 388) ON CONFLICT DO NOTHING;
