INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021192', 'AN1924', '河野桜', '彼女は学生自治会の副会長です。彼女はとても有能で、よくサポート業務を行っています。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b72449-wTynovkFnQpC.png', '1月20日', NULL, '近藤玲奈', 163, 72449, 'SUPPORTING', 942) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021193', 'AN1924', '沢田ほのか', '沢田は堀京子に対して非常にべったりしている。堀への執着から、堀が宮村伊澄と一緒にいるとよく怒り出し、彼を遠ざけようとする。彼女は宮村を恋のライバルであると同時に、兄弟のような存在とも見なしている。 彼女は数年前に亡くなった兄と非常に仲が良かった。また、軽度の男性恐怖症の傾向があり、男性に近づかれると、しばしば固まってしまったり、逃げ出したり、隠れたりしてしまう。しかし、宮村と知り合ってからは、代わりに彼の後ろに隠れるようになった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b72459-NbyXnBAjLxKT.png', '12月31日', NULL, '麻倉もも', 150, 72459, 'SUPPORTING', 762) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021194', 'AN1924', '寺島玲子', '彼女は片桐高校の化学教師であり、3年1組の担任です。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b66973-cRamsBQtjWmG.png', NULL, NULL, '佐藤はな', NULL, 66973, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021195', 'AN1924', '綾崎レミ', '生徒会のメンバーであり、片桐高校に通う仙石翔の彼女として知られている。同校の3年5組に在籍している。生徒会ではどちらかといえばマスコット的な存在で、仕事はほとんど、あるいは全くしていない様子が描かれている。   レミは、概してかなり子供っぽく未熟な少女として描かれており、非常に率直な性格で、感情を隠さず表に出すことが多い。また、他人の助けに頼りがちなところもある。頭もあまり良くなく、よく宮村と比べられる。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b66965-Kfqui6IitXaL.png', '6月6日', NULL, '市道真央', 158, 66965, 'SUPPORTING', 1703) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021196', 'AN1924', '堀創太', '京子の弟。両親の仕事の都合で、生まれてからずっと京子に世話になってきたため、彼は京子を母親のような存在として見ている。  物語の冒頭、彼は路上で転んでしまったところを和泉に助けられ、堀家へ連れ戻される。それ以来、彼は和泉に対して非常に親しみを示しており、血のつながりはないものの「兄弟」と呼ぶほどである。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b66969-w9HNa7igeTeF.png', '10月18日', NULL, '寺崎裕香', NULL, 66969, 'SUPPORTING', 573) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021197', 'AN1924', '宮村伊織', '職業：宮村家の店のオーナー兼経営者。宮村直純の妻であり、宮村伊澄の母である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b207325-wjqrISdImoOl.png', NULL, NULL, '大原さやか', NULL, 207325, 'SUPPORTING', 31) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021198', 'AN1924', '井浦秀', '彼は宮村伊澄や、scholのほぼ全員と親しい間柄だ。独自の考え方を持ち、いつも活気にあふれている。別のクラスの同僚である。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b66967-driczOA04cxe.png', '2月7日', NULL, '山下大輝', 172, 66967, 'SUPPORTING', 995) ON CONFLICT DO NOTHING;
