INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021214', 'AN1925', 'ジャリル', 'ルデウスが、迷子の猫を探している最中に魔大陸で出会った冒険者。彼はペットを盗み出す手口に関与しており、飼い主が冒険者ギルドに捜索依頼を出すと、そのペットを返却して報奨金を得ていた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b212908-GX0viWoz2yKV.png', NULL, NULL, '松重慎', NULL, 212908, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
