INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021218', 'AN1925', 'サウロス・ボレアス・グレイラット', 'サウロス・ボレアース・グレイラットは、アスラ王国フィトア地方の領主であり、エリスの祖父であった。    （出典：無職転生Wiki）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b207786-K3ND5XfwzHkc.png', NULL, NULL, '高岡瓶々', NULL, 207786, 'SUPPORTING', 48) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021219', 'AN1925', 'ノコパラ', 'ルデウスが魔大陸で出会った、欲深い冒険者。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b212901-geh29ndkBOHZ.png', NULL, NULL, '斎藤寛仁', NULL, 212901, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021220', 'AN1925', 'ヴェスケル', 'ルデウスが、迷子の猫を探している最中に魔大陸で出会った冒険者。彼女はペットを盗み出す企みに加担していたが、飼い主たちが冒険者ギルドに捜索依頼を出すと、ペットを返却して報奨金を得ていた。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b212907-E9Rad7KGuajw.png', NULL, NULL, '鳥越まあや', NULL, 212907, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021221', 'AN1926', 'なとり', '石神村の村人。カルボの父親であり、アルミの夫である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b255670-tBg10oKDGlU0.png', NULL, NULL, NULL, NULL, 255670, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021222', 'AN1926', 'コクヨウ', 'コハクとルリの父親。センクが目を覚ました当時、石神村の村長を務めていた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b150509-6LyHh2A6wVyc.jpg', '4月19日', 'B', '金尾哲夫', NULL, 150509, 'SUPPORTING', 32) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021223', 'AN1926', 'リリアン ・ ワインバーグ', 'その名は世界中に知れ渡っている、有名なアメリカの歌姫。冒険への情熱から、千空の父である石神白夜と共に国際宇宙ステーション（ISS）へと向かった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b149274-lYJFmrdqT7Hq.jpg', '10月1日', 'A', 'Lynn', NULL, 149274, 'SUPPORTING', 176) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021224', 'AN1927', 'エマ', '農場ID：63194　エマは他の子供たちにとって姉のような存在であり、家族を深く愛しています。彼女は優しく、勇敢で、思いやりがあり、心優しい子です。 一方で、無邪気で無鉄砲な一面もあり、グループの安全を守るためなら、ためらうことなく自ら危険に身をさらすこともあります。他の子供たちは、彼女を「怪物のような反射神経」と「驚異的な学習能力」の持ち主だと評しています。そのおかげで、困難な状況でも素早く判断を下すことができ、非常に優れた戦略家となっています。彼女はまさに希望の光と言えるでしょう。', 11, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b121725-LQciVJOjnMVh.png', '8月22日', NULL, '諸星すみれ', 145, 121725, 'MAIN', 6431) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021225', 'AN1927', 'レイ', '農場識別番号：81194　孤児院で「三人の優等生」の一人であるレイは、非常に論理的で、聡明かつ狡猾、そして並外れて忍耐強く、普段は一人で本を読んでいる姿がよく見られる。本からの知識は極めて豊富だが、彼は「勉強は好きではなかった」と語っている。 クローネ修道女が入手したデータによると、彼の弱点はすぐに諦めてしまうことだという。', 11, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b121724-SJTdODjeO7e6.jpg', '1月15日', NULL, '伊瀬茉莉也', 150, 121724, 'MAIN', 11411) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021226', 'AN1927', '祖母', '祖母は人間の中でも高位にあり、かつてはイザベラの「ママ」として働いていたが、彼女を人間というよりはむしろ駒のように扱っていた。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b136463-CHTYDFuQnr7Q.jpg', NULL, NULL, '小山茉美', NULL, 136463, 'SUPPORTING', 15) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021227', 'AN1927', 'マルク', '年齢（2045年）：5歳 農場識別番号：79294 生年月日：2040年1月8日', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b199117-hf0KR44q2XkP.png', '1月8日', NULL, '青山吉能', NULL, 199117, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021228', 'AN1927', 'シスロ', 'シスロは、かつてラムダ7214（別名Λ7214）の実験体だった。 趣味はウェイトトレーニングで、その見た目とは裏腹に涙もろく、ボス（ノーマン）を深く慕っている。12～13歳の頃、親友のバーバラと共にゴッドウィル・リッジからラムダへ送られた。ゴッドウィルは数あるプレミアムファームの一つである。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b192864-BHyTEeQZAu7o.jpg', '4月30日', NULL, '中島ヨシキ', NULL, 192864, 'SUPPORTING', 27) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021229', 'AN1927', 'トーマ', '農場ID：55294（グレース・フィールド・ホース）　トーマは機転が利き、いたずら好きな少年で、親友のラニと一緒に悪戯をするのが大好きだ。物言いは率直だが、時としてかなり臆病な一面もある。', 7, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b129784-fn5VoMYAqCsk.jpg', '8月30日', NULL, '日野まり', 123, 129784, 'SUPPORTING', 135) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021230', 'AN1927', 'ドミニク', '農場識別番号：07294（グレース・フィールド・ホース） ドミニクは、元気いっぱいで、かなり筋肉質な少年です。彼は非常に勇敢であるだけでなく、他人への思いやりも深く、皆の安全を守るためなら、どんな危険も厭わない覚悟を持っています。', 6, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b199118-FEIoj5A6GSxW.png', '2月28日', NULL, '日野まり', NULL, 199118, 'SUPPORTING', 40) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021231', 'AN1927', 'ヴィルク', '目が見えない悪魔。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b208450-QS7iG01kAHjk.jpg', NULL, NULL, '上田敏也', NULL, 208450, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021232', 'AN1927', 'ムジカ', 'ムジカ（またはムジカ）は、グレース・フィールド・ハウスの外の森を旅している悪魔の末裔である。     ムジカは、角の一部を覆うほど長い紫色の髪をツインテールに編み込み、縦に2つの穴が開いた仮面を身につけている。肌は青白く、青みがかった白いマントを羽織っている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b126498-w5eif6lqQLoC.jpg', NULL, NULL, '種﨑敦美', NULL, 126498, 'SUPPORTING', 760) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021233', 'AN1927', 'ジェミマ', '年齢（2045年）：5歳　農場識別番号：31394（グレース・フィールド・ホース）　ジェミマは陽気で行儀が良い。とはいえ、いたずらをすることもある。アリシアとは強い絆で結ばれているようだ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b199114-dyn7IeoolRi1.png', '7月20日', NULL, '久遠エリサ', NULL, 199114, 'SUPPORTING', 52) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021234', 'AN1927', 'ザジー', 'ザジーは、かつてのΛ7214実験体である。人間の中では最強の存在だ。紙袋をかぶっていないと怒り出す。上司のノーマンを慕っている。', 5, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b169006-wVXUuayBDq9q.jpg', NULL, NULL, '高橋英則', NULL, 169006, 'SUPPORTING', 62) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021235', 'AN1927', 'ドン', '年齢（2045年）：10歳 農場識別番号：16194 生年月日：2035年7月4日  ドンは肌が浅黒く、背が高くほっそりした体格をしている。短く乱れた黒髪にアンダーカットのスタイルで、瞳は茶色だ。標準的な白い制服を着ている。 エマと同様、ドンも兄弟姉妹のことを深く気にかけている。ドンは陽気で少しうっかりした少年として描かれているが、ギルダに次いで日常テストで5位前後に入るほど、かなり頭が良い。また、スリの才能もある。身体能力もかなり高い。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126454-TI3LXk2oN7WV.jpg', '7月4日', NULL, '植木慎英', NULL, 126454, 'SUPPORTING', 378) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021236', 'AN1927', 'ラニオン', '年齢（2045年）：7歳　農場識別番号：54294（グレース・フィールド・ホース）　生年月日：2038年4月28日　ラニは、いたずら好きで機転の利く少年で、親友のトーマと一緒におふざけをするのが大好きだ。 少し臆病なところもあるが、率直で正直な性格だ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b129783-6KAMdcOzkmCv.jpg', '4月28日', NULL, '森優子', NULL, 129783, 'SUPPORTING', 102) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021237', 'AN1927', 'ロッシー', '年齢（2045年）：5歳 農場識別番号：50394（グレース・フィールド・ホース） 生年月日：2040年4月14日  ロッシーは繊細で慎重な男の子ですが、時にはかなりいたずら好きな一面もあります。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b199116-njqloLk0EMXO.png', '4月14日', NULL, '林鼓子', NULL, 199116, 'SUPPORTING', 36) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021238', 'AN1927', 'ピーターラートリー', 'ピーター・ラートリーは、名門ラートリー一族の第36代当主であり、ジェイムズ・ラートリーの弟である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126495-rOG3lcE3GBfD.jpg', NULL, NULL, '細谷佳正', NULL, 126495, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021239', 'AN1927', 'ギルダ', '農場識別番号：65194　ギルダは、オリーブドラブ色の短い髪をチャイニーズボブにまとめており、丸いレンズの眼鏡をかけています。 ギルダは直感的な若い少女だ。また、思いやりのある性格でもある。内向的な性格のようだが、勇敢な一面も見せる。時にはかなり威圧的な一面も見せることもある。', 10, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126455-ki6wpr5Un4fF.png', '5月13日', NULL, 'Lynn', NULL, 126455, 'SUPPORTING', 421) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021240', 'AN1927', 'ノーマン', '農場識別番号：22194  ノーマンは、論理的で善意に満ち、献身的な性格だが、少し純真な一面もあるようだ。 彼は自分の行動を事前に容易に計画でき、他人の行動も先読みする。エマやレイと並び、孤児たちの中でトップ3に入る実力者だ。ノーマンはエマを深く愛しており、彼女に対して献身的で忠実である。', 11, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b121700-CRwKIlcBcjbv.jpg', '3月21日', NULL, '内田真礼', 145, 121700, 'SUPPORTING', 7913) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021241', 'AN1927', 'Sonju', '年齢：少なくとも1000歳　髪の色：赤　瞳の色：黒　ソンジュ（またはソン・ジョ）は、グレース・フィールド・ハウスの外に住む悪魔である。  ソンジュは冷静沈着な性格で、孤児たちとの関わりを控えることもあった。また、関わるときにはその風貌ゆえに孤児たちを威圧することが知られていた。とはいえ、ソンジュはある程度、孤児たちの安全を気にかけており、彼らが「約束」を破ることができると信じている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/126497-tzUtqWwy3Mkf.jpg', NULL, NULL, '神尾晋一郎', NULL, 126497, 'SUPPORTING', 352) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021242', 'AN1927', 'イベット', '農場ID：59294  イベットは、賢く観察力に富み、芸術的センスに溢れた女の子です。彼女はいつも鉛筆とスケッチブックを持ち歩いています。', 5, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b199112-xyVfJn8irWMX.png', '12月31日', NULL, '白城なお', NULL, 199112, 'SUPPORTING', 88) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021243', 'AN1927', 'イザベラ', '農場識別番号：73584  イザベラはグレース・フィールド・ハウスで「ママ」として働き、そこに暮らす孤児たちの世話をしていた。', 31, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b121701-hP5hanKRUH9u.png', '9月9日', 'A', '甲斐田裕子', 170, 121701, 'SUPPORTING', 1753) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021244', 'AN1927', 'アンナ', '年齢（2045年）：9歳　農場識別番号：48194（グレースフィールド・ハウス）　生年月日：2036年4月25日　グレースフィールドの他の孤児たちと同様、彼女もグレースフィールド孤児院の標準的な制服を着ている。 アンナは、驚くほど骨格がしっかりとした背の高い少女に成長した。金髪の髪はツインテールに結われている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n126504-xHMVYY9uEfkh.png', '4月25日', NULL, '茅野愛衣', NULL, 126504, 'SUPPORTING', 185) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021245', 'AN1927', 'クリスティ', '農場識別番号：70394（グレース・フィールド・ホース）　クリスは好奇心旺盛な少年で、とても陽気で率直な性格です。', 5, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b199113-o58sBqMb1m3h.png', '5月15日', NULL, '河野ひより', NULL, 199113, 'SUPPORTING', 40) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021246', 'AN1927', 'ヴィンセント', 'ヴィンセントは、かつてのラムダ7214（別名Λ7214）の実験体である。グローリー・ベルで生まれた。医学の知識に長けており、非常にファッションセンスが良いことで知られている。また、お菓子や衣服、武器を作ることができる。ボス（別名ノーマン）を深く慕っている。', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b192865-ZVapJOXSrXkv.jpg', '1月29日', NULL, '高橋英則', NULL, 192865, 'SUPPORTING', 15) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021247', 'AN1927', 'ナット', '年齢（2045年）：9歳　農場識別番号：48194（グレース・フィールド・ハウス）　生年月日：2036年12月18日　ナットは、茶色の瞳と高い鼻筋（彼はこれを大いに誇りにしている）を持つ、やや虚弱な少年だ。  彼は孤児院の標準的な制服を着ている。すぐに怯えてしまうこともあるが、勇敢な一面を見せることもある。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b129805-rUUS2wWGIAnH.png', NULL, NULL, '石上静香', NULL, 129805, 'SUPPORTING', 42) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021248', 'AN1927', 'アリシア', '農場ID：71394（グレース・フィールド・ホース）  アリシアは、明るく社交的で、おてんばな性格の若い女の子です。時にはずる賢い一面も見せますが、自分の意見をしっかりと主張することもできます。ジェミマとは強い絆で結ばれていることが描かれています。', 5, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b199115-IDyDlyokeLHw.png', '9月1日', NULL, '青山吉能', 109, 199115, 'SUPPORTING', 24) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021249', 'AN1927', 'バーバラ', 'バーバラは、かつてラムダ7214（別名Λ7214）の実験体だった。彼女は食欲が旺盛で、彼女に対して行われた実験の結果、超人的な力を身につけている。 12歳の時、彼女は親友のシスロと共に、ゴッドウィル・リッジからラムダへと移送された。ゴッドウィルは、数あるプレミアム農場の一つである。', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b192866-Cqo4XXcYT8cR.jpg', '6月18日', NULL, '安済知佳', NULL, 192866, 'SUPPORTING', 53) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021250', 'AN1928', 'コビー', '『犬の商人』', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213897-1jpxjywP0QtA.jpg', '5月13日', NULL, '坂泰斗', NULL, 213897, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021251', 'AN1928', 'カバル', 'カバルは、自身の冒険パーティのリーダーであり、「ファイター」の役割を担っている。  （出典：転生したらスライムだった件 ウィキア）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b129918-Srq5hldfOKBm.jpg', NULL, NULL, '高梨謙吾', NULL, 129918, 'SUPPORTING', 18) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021252', 'AN1928', 'キョウヤ・タチバナ', '橘京也は、ファルムスに仕えるために召喚された異世界人の一人だった。のんびりとした性格で、自分こそが最も強力なスキルを持つ一人だと信じていた。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b195021-UsKUJz6LziId.jpg', NULL, NULL, '野上翔', NULL, 195021, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021253', 'AN1928', 'ショウゴ・タグチ', 'ショウゴ・タグチは、ファルムスに仕えるために召喚された異世界人の一人だった。自分は現存する最強の一人であり、坂口日向にも匹敵すると信じている、非常に傲慢な人物だった。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b195020-JOAZqINZTJpj.jpg', NULL, NULL, '小林千晃', NULL, 195020, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021254', 'AN1928', 'イフリット', 'イフリットは高位の精霊であり、魔王レオン・クロムウェルによって伊沢静江の体内に封印された「炎の支配者」である。かつては「精霊の住処」に暮らしていたが、「金髪の魔王」レオン・クロムウェルに奪われてしまった。 その後、彼は伊沢静江の中に封印された。その結果、静江の寿命は延びることとなった。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b134583-cnaY5eEBxALn.png', NULL, NULL, '八代拓', NULL, 134583, 'SUPPORTING', 41) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021255', 'AN1928', 'キララ・ミズタニ', 'キララ・ミズタニは、ファルムスに仕えるために召喚された異世界人の一人だった。自分以外の誰かのせいにすることばかりする、自己中心的な人物である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b195047-155V8ZEIknn0.jpg', NULL, NULL, '河野ひより', NULL, 195047, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021256', 'AN1928', 'ガルム', 'ガルムは、ドルドとミルドの兄である。熟練の鍛冶職人だ。ガルムは普段着や下着の担当である。    （出典：転生したらスライムだった件 ウィキア）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b129923-h8OLZNRSz6oe.jpg', NULL, NULL, '相馬康一', NULL, 129923, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021257', 'AN1928', 'ミルド', 'ミルドは、ガルムとドルドの弟である。口数の少ないドワーフだったが、その道の達人だった。建築の知識を持ち、芸術にも精通しており、類まれな天才である。ミルドは建設チームの隊長に任命された。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n129914-30U7I3xGmL3q.jpg', NULL, NULL, '野川雅史', NULL, 129914, 'SUPPORTING', 42) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021258', 'AN1928', 'ギド', 'ギドはカバルのパーティのメンバーで、「盗賊」の役割を担っている。  （出典：『転生したらスライムだった件』ウィキア）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b129916-f5ZWUvmNY41G.jpg', NULL, NULL, '木島隆一', NULL, 129916, 'SUPPORTING', 22) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021259', 'AN1928', 'クレイマン', '魔王クレイマンは、十魔王の一人であり、', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b131052-hbVYgUsI5ahb.png', NULL, NULL, '子安武人', NULL, 131052, 'SUPPORTING', 31) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021260', 'AN1928', 'フォビオ', '種族：ヒョウ型ライカントロープ　彼は魔王カリオンの「ビーストキーター」の一人である。3人の「ビーストキーター」の中で最強の戦士であると称されている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b134594-XCsZzC7Jyfsz.jpg', NULL, NULL, '山下誠一郎', NULL, 134594, 'SUPPORTING', 21) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021261', 'AN1928', 'ドルド', 'ドルドは、ガルムとミルドの間の兄弟である。彼は一流の職人技で知られている。ドルドは、染料や高級な衣装の制作に特に力を入れている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n129917-3UC194PSkLFQ.jpg', NULL, NULL, '杉崎亮', NULL, 129917, 'SUPPORTING', 19) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021262', 'AN1928', '海道', '彼はドワゴン衛兵隊の隊長であり、カイジンの弟である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b134579-IcabUVenyIW0.jpg', NULL, NULL, '樫井笙人', NULL, 134579, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021263', 'AN1928', 'ゴンゾ', '『テンペスト』に登場する、ゴブタと友達のゴブリン', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b213898-6bER5Z5ZZ92Z.jpg', NULL, NULL, '梶原岳人', NULL, 213898, 'SUPPORTING', 31) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021264', 'AN1928', 'フォルゲン', 'フォルゲンは、ファルムス王国の元騎士団長である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b256439-tn73TLjHBtuO.jpg', NULL, NULL, '真木駿一', NULL, 256439, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021265', 'AN1929', 'エキドナ', 'エキドナは「罪の魔女」の一人であり、「貪欲の魔女」である。彼女は知識への強い渇望と未知への好奇心を持っており、それが彼女の行動を特徴づけている。エキドナは冷酷無情であると評されており、理解力の欠如から、他者やその感情に共感することができない。 彼女は知識を得るためなら、欺瞞や詭弁を用いることさえ厭わない。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b129330-ZUtYw4n7N0uH.png', '1月24日', NULL, '坂本真綾', NULL, 129330, 'MAIN', 6129) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021266', 'AN1929', 'アーチ', 'アーチは、エリオル森の次期守護者に指名されていた弟子であり、エルフの村の住人だった。また、フォルトナやエミリアの家族ぐるみの友人でもあった。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b183733-kfPnOrhiOoQF.jpg', NULL, NULL, '浪川大輔', NULL, 183733, 'SUPPORTING', 27) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021267', 'AN1929', 'リューズ・メイエル', 'リュウズは、400年前の「魔女の時代」にサンクチュアリに住んでいたハーフエルフだった。彼女は、サンクチュアリの結界を発動させるためにエキドナに利用された。エキドナは不老不死の実験を行う中で、リュウズの複製体を作り出し、サンクチュアリを守る任務を課した。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b174072-v8hZDRvLIlPA.png', NULL, NULL, '田中あいみ', NULL, 174072, 'SUPPORTING', 176) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021268', 'AN1929', 'ヘクトール', 'ヘクトールは「罪の魔女」の一人であり、「憂鬱の魔術師」である。彼は陰鬱な性格で、そのネガティブな感情を言葉にして表すことがよくある。ヘクトールはエキドナと何らかの関係がある。また、ロズワールと同様の服装をしている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b137525-p4bLdgqVoQ3J.png', NULL, NULL, '諏訪部順一', NULL, 137525, 'SUPPORTING', 33) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021269', 'AN1929', 'パック', 'パックは、かつてエミリアと契約を結んでいた人工精霊である。現在は「火の大精霊」を務めている。パックは「かわいい」や「愛らしい」といった印象を与える存在で、頬のあたりがピンク色をしている。毛並みは主に灰色だが、所々（例えば尻尾の先など）に銀色が混じっている。 眉毛はかなり小さく、ひし形をしている。また、左耳には金のピアスをしている。時には、紫色のバッグを提げていることもある。パックは概して優しい精霊だ。とても陽気で、エミリアのそばにいて彼女を守っている。', 420, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b90187-xJXlD84KXl3t.jpg', NULL, NULL, '内山夕実', 7, 90187, 'SUPPORTING', 1412) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021270', 'AN1929', 'ミネルヴァ', 'ミネルヴァは「罪の魔女」の一人であり、「怒りの魔女」である。ミネルヴァは争いを嫌い、すべての人々が幸せであることを願っている。また、彼女は目の前のことしか気にせず、見えないことについては気にしない。   ミネルヴァは、エミリアをはじめとする他のエルフたちを深く思いやっているため、エルフたちとはある縁がある。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b137521-kq5uFiHwC15V.png', '7月20日', NULL, '小松未可子', NULL, 137521, 'SUPPORTING', 305) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021271', 'AN1929', 'フォルトナ', 'フォルトナはエリオール森の守護者であり、エミリアの父方の叔母で、母親の代わりに彼女を育てた人物だった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b183732-ODeNNBil4916.png', NULL, NULL, '戸松遥', NULL, 183732, 'SUPPORTING', 99) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021272', 'AN1930', '川井リカ', '初めて会った人であっても、自分の本音をためらわずに口にする女の子。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b199890-9WY1MIjTsqkc.jpg', '10月18日', NULL, '斉藤朱夏', NULL, 199890, 'MAIN', 2856) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021273', 'AN1930', '大戸アイ', '両目の瞳の色が著しく異なる少女で、そのせいで学校でいじめられている。ある出来事のため、現在は一時的に学校を休んでいる。非常に内向的な性格で、一人で過ごす時間が長い。しかし、大切な人に対しては誰よりも守ろうとする。  特別な力や能力は持っていないが、武器に変形できる色とりどりのペンを操ることができる。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b199892-IUa7rBAT4j9H.png', '6月15日', NULL, '相川奏多', NULL, 199892, 'MAIN', 4085) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021274', 'AN1930', '青沼ねいる', '非常に際立った緑色の瞳とツインテールが特徴の少女。普段は極めて静かで物静かであり、自分自身を愛しているが、人との関係を築こうとする積極性は見せない。それどころか、人との接触を避けている。彼女は、姉の死に対して責任を感じていることから、姉を救うという自分の目標をアイに打ち明ける。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b199893-KpWnNBLyKHaw.png', '4月27日', NULL, '楠木ともり', NULL, 199893, 'MAIN', 1424) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021275', 'AN1930', '沢木桃恵', '非常に特徴的なほくろとスレンダーな体型を持つ少女。よく男性と間違えられるが、女子の間で人気がある。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b199891-YNqLCCE8VAHW.png', '3月30日', NULL, '矢野妃菜喜', NULL, 199891, 'MAIN', 1768) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021276', 'AN1930', '西城くるみ', 'くるみは共感力のある女の子だ。時には威圧的な口調で他人に話しかけることもあるが、人助けを惜しまない性格だ。真剣な場面では、皮肉な発言をすることが多い。  （出典：ワンダーエッグ・プライオリティ ファンダムWiki）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b204143-SKXKmOH3jNZA.jpg', NULL, NULL, '安済知佳', NULL, 204143, 'SUPPORTING', 90) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021277', 'AN1930', 'マンネン', 'アカとウラ・アカからリカに贈られたポマンダー・ペットは、エッグワールドでのパワーアップアイテムとして使われる。しかし、現実世界では、小さくておとなしい動物である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b214112-9WFibxCbo7vE.jpg', NULL, NULL, NULL, NULL, 214112, 'SUPPORTING', 28) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021278', 'AN1930', '鈴原南', 'ミナミはとても内気で臆病だ。自分自身にも自分の能力にも全く自信がなく、よく自分を「弱くて気力が足りない」と表現する。また、体操のコーチからの虐待を受けた影響で非常に従順であり、何の疑問も抱かずにコーチの言うことを聞き、文句一つ言わずに虐待を受け入れている。   （出典：ワンダーエッグ・プライオリティ Fandom Wiki）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b204893-rLGsvFhZkn96.png', NULL, NULL, '佐藤聡美', NULL, 204893, 'SUPPORTING', 28) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021279', 'AN1930', 'ピンキー', 'アカとウラ・アカから提供されたネイルのポマンダー・ペットは、エッグワールドでのパワーアップとして使用される。しかし、現実世界では、それは小さくておとなしい動物である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b214113-V6XQxa7rMhtI.jpg', NULL, NULL, NULL, NULL, 214113, 'SUPPORTING', 23) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021280', 'AN1930', '沢木修一郎', '沢木修一郎は、アイとコイトの担任教師だ。彼は美術部の顧問も務めており、よくアイの家を訪ねてくるが、アイの家は自分の家への通り道にあるから構わない、と言っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b204921-PEjb3Pp7lZjc.jpg', NULL, NULL, '中澤匡智 ', NULL, 204921, 'SUPPORTING', 31) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021281', 'AN1930', '美和', '背景：', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b206595-8mJHZxqH1cqM.png', NULL, NULL, '花守ゆみり', NULL, 206595, 'SUPPORTING', 47) ON CONFLICT DO NOTHING;
