INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021283', 'AN1930', '阿波野寿', '彼女は「ジャパン・プラティ」という企業に、ネイールとして生まれた。彼女の遺伝子構成は極めて稀なものとされ、異色症、アルビニズム、そして高い知能という特徴を併せ持っている。阿波野寿は科学者であり医師でもあり、意図せずしてドクター関のポストを引き継ぐことになった。 ネイールは、彼女にとってこの企業内で唯一の友人である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b211651-PjjkvrzNNbX0.jpg', NULL, NULL, '宮本侑芽', NULL, 211651, 'SUPPORTING', 79) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021284', 'AN1930', 'ハイフン', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b214872-QWtwoEdWxz8N.jpg', NULL, NULL, '大谷育江', NULL, 214872, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021285', 'AN1930', 'まこ', '親友のみこと共に、まこは「ゆうゆう」というアイドルの熱狂的なファンだった。生前、彼女とみこは一緒にコンサートやファンミーティングに参加していた。ゆうゆうの話をすると、彼女はとても陽気で熱意に満ち溢れ、夢の世界で親友に会えて大変喜んでいる。  現実の世界では、まこは親友のみこと一緒に、お気に入りのアイドル「ユウユウ」のコンサートやファンミーティングによく足を運んでいた。二人は、ユウユウのイベントに参加するための費用を賄うために、「パトロン」を見つけたことを認めている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b205833-oDVrdgOW2MNu.png', NULL, NULL, '田辺留依', NULL, 205833, 'SUPPORTING', 38) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021286', 'AN1930', '田辺美咲', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b206596-mIGsXzVYMY4x.png', NULL, NULL, '武田華', NULL, 206596, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021287', 'AN1930', 'フリル', 'フリルは、アカとウラ・アカによって生み出された人工人間である。フリルは、設計上、明るく賢く、平均的な14歳の子供よりもはるかに高い知性を備えている。また、ユーモアのセンスもあり、いたずらやふざけた行動に笑いをこらえきれない様子がよく見られる。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b214874-2yiyIiVPWNa2.jpg', NULL, NULL, '山口愛', NULL, 214874, 'SUPPORTING', 171) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021288', 'AN1930', '大戸多恵', '大戸アイの母親。とても物腰が柔らかく、アイのことを深く大切に思っている。誰と話すときも、常に落ち着いていて、礼儀正しく、とても親切だ。   (出典：ワンダーエッグ・プライオリティ ファンダムWiki)', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b204116-n1I99ZVHQzfB.png', NULL, NULL, '白石晴香', NULL, 204116, 'SUPPORTING', 39) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021289', 'AN1930', 'みこ', '親友のまこと共に、みこは「ゆうゆう」というアイドルの熱狂的なファンだった。生前、彼女とまこは一緒にコンサートやファンミーティングに参加していた。ゆうゆうの話をすると、彼女はとても陽気で熱狂的になり、夢の世界で親友に会えて大喜びしている。  現実の世界では、みこは親友のまこと一緒に、お気に入りのアイドル「ユウユウ」のコンサートやファンミーティングによく足を運んでいた。二人は、ユウユウのイベントに参加するための費用を賄うために、「パトロン」を見つけたことを認めている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b205834-OfNKimIauDcD.png', NULL, NULL, '井上麻里奈', NULL, 205834, 'SUPPORTING', 42) ON CONFLICT DO NOTHING;
