INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021293', 'AN1930', '長瀬小糸', 'コイトは、大戸アイの最初の友人です。アイとの友情が原因で、学校でいじめに遭いました。彼女は生まれつきとても穏やかな性格で、学校でのいじめに対する反応からもわかるように、どんな状況でも良い面を見つけ出すことができます。また、特に大切な人に対しては、優しく思いやりのある人でもあります。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b204115-QOsA8kKxnLLn.png', NULL, NULL, '田所あずさ', NULL, 204115, 'SUPPORTING', 158) ON CONFLICT DO NOTHING;
