INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021296', 'AN1930', 'アカ', 'アカは、黒いメガネをかけ、ごくわずかに微笑みを浮かべたマネキンである。 体格は平均的な男性のように見えるが、首まで覆われているため、正確には判断しがたい。現時点では真の動機は不明だが、その目的は、ウラ・アカと同様に、主要な主人公たちを「エッグワールド」での戦いに導くことにある。   能力：', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b204118-19o0SF8N3yRb.png', NULL, NULL, '内田夕夜', NULL, 204118, 'SUPPORTING', 111) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021297', 'AN1930', 'レオン', 'アイのポマンダー・ペットは、アカとウラ・アカから提供されたもので、エッグワールドでのパワーアップとして使用される。しかし、現実世界では、小さくておとなしい動物である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b214110-f31JfvajexFc.jpg', NULL, NULL, NULL, NULL, 214110, 'SUPPORTING', 23) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021298', 'AN1930', 'ひまり', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b214881-DeMoXDnKBZRM.jpg', NULL, NULL, '庄司宇芽香', NULL, 214881, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021299', 'AN1930', '裏アカ', 'ウラ・アカは、アカと共に、アイたちを「エッグワールド」へと導く役割を担っている。アカとは対照的に、ウラ・アカの話し方や外見は、より気さくでカジュアルだ。 時には、非常に鋭い意見を述べることもある。また、かなり正直な性格で、アカのように事実を隠したり話題を避けたりするよりも、真実を語ることを好む。   能力：', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b204117-mLPUJhFKi5IH.png', NULL, NULL, '高橋広樹', NULL, 204117, 'SUPPORTING', 209) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021300', 'AN1930', 'パニック', 'アカとウラ・アカからモモエに贈られたポマンダー・ペットは、エッグワールドでのパワーアップアイテムとして使われる。しかし、現実世界では、小さくておとなしい動物である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b214111-4L28Ve6k6wnO.jpg', NULL, NULL, NULL, NULL, 214111, 'SUPPORTING', 29) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021301', 'AN1930', 'キララロドリゲスマチュード18世宵の明星SSプラン', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b215986-vB5nWLtVq4ky.jpg', NULL, NULL, '大谷育江', NULL, 215986, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021302', 'AN1931', '馳河ランガ', '特技：スノーボード、スケートボード　一見すると、ランガは感情をほとんど表に出さない、非常に無表情な青年のように見えます。しかし、その内面はもっと複雑で、より自信に満ちているようです。  ランガは、耳より長く伸びた青い髪と青い瞳を持つ10代の少年だ。レキよりも背が高く、平均以上の身長がある。シリーズを通して、ランガは黒いズボン、黄色のジャケット、白いボタンダウンシャツという、ごく一般的な高校の制服を着ている。しかし、レキと行動を共にする時は、彼は', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b195116-C2Y5jRPiTSng.png', '2月8日', NULL, '小林千晃', 178, 195116, 'MAIN', 5672) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021303', 'AN1931', '比嘉広海', '花屋として働く普段の生活では、シャドウは顧客に対して親しみやすく親切な態度を見せている。しかし、真夜中になると、彼は態度を一変させ、傲慢で、意地悪で、無礼な人物へと変わる。これは、日中に不快な出来事に遭遇した際のストレス発散の手段であると考えられている。', 24, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b195117-inAXhLQV50N2.png', '9月14日', NULL, '三宅健太', NULL, 195117, 'MAIN', 358) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021304', 'AN1931', '桜屋敷薫', 'カオルは冷静で知性的であり、「S」の外でも、著名で成功を収めたAI書道家として知られている。 彼はクライアントや見知らぬ人に対しては礼儀正しく敬意を持って接するが、身近な人々、とりわけ「S」の仲間であり幼なじみの南城虎次郎に対しては、しばしば刺々しい態度を見せる。また、スケートボードをする際には並外れて競争心が強いが、友人だと認めた相手に対しては、心から信頼し、気遣っている。', 26, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b195118-Q2toyBV5TqOO.png', '3月27日', NULL, '緑川光', 182, 195118, 'MAIN', 3015) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021305', 'AN1931', '菊池忠', '彼は神道愛之介の秘書であり、もともと彼にスケートを教えた人物である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b195119-QK9QJO9DyeEa.png', '11月22日', NULL, '小野賢章', NULL, 195119, 'MAIN', 461) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021306', 'AN1931', '喜屋武暦', '特技：スケートボード、木工　レキはスケートボードが大好きな高校2年生だ。彼はアンダーグラウンドのスケートボードレース「S」に巻き込まれてしまう。レキは赤く逆立ったワイルドな髪型で、頭に3色のバンダナを巻いている。 また、琥珀色の瞳を持ち、肌は色白だ。身長は平均的で、しなやかな体つきをしている。スケーター風のスタイルで、だぶだぶの紺色のパンツとセーターを組み合わせ、その下に黄色のシャツを着ている。（出典：Sk8', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b195120-ndTbU0TpVLWw.png', '8月8日', NULL, '畠中祐', 176, 195120, 'MAIN', 6303) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021307', 'AN1931', '知念実也', '特技：スケートボード、猫と会話すること　知念実也は、アニメシリーズ『SK∞ エスケーエイト エスケーエイト』に登場するキャラクターで、エリート中学生であり、日本代表候補でもある。ミヤはのんきな少年として描かれている。 彼はスケートボードに興味はあるものの、廃坑で行われる地下の危険なスケートボードレース「S」に参加する他のライバルたちのように、それに夢中になっているようには描かれていない。子供の頃、ミヤはスケートボードが大好きで、それを楽しんでいた。成長するにつれて腕も上達し、賞も受賞するようになった。しかし、', 13, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b195121-FehldtuXxYXh.png', '2月22日', NULL, '永塚拓馬', 158, 195121, 'MAIN', 3242) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021308', 'AN1931', '神道愛之介', '星座：牡牛座　所属：ダイエット部　親族：名前のない叔母3人、神道愛一郎（父）　特技：スケートボード　「ラブハグ」という能力を使い、まるで上り坂を滑っているかのように見せることができる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b195122-sRbKtiUYxVWL.png', '5月1日', NULL, '子安武人', NULL, 195122, 'MAIN', 459) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021309', 'AN1931', '南城虎次郎', '特技：コーキング　所属：シアラルーチェ（レストラン）　熟練のスケーターであり、「S」の創設メンバーの一人。その独特な体格とステータスを活かし、アグレッシブで動きを重視したスケートスタイルを繰り広げる。   チェリーブロッサムに対して敵意を漂わせているように見えるが、実は二人は親友であり、互いの能力を最大限に信頼し合っている。彼はカオルに深い愛情を抱いており、カオルが怪我をした後、こっそりと病院を抜け出したのは彼のためであり、カオルが……の際、彼を抱きかかえて運んだのも彼だった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b195123-n5AYNVIBfg5Z.jpg', '7月7日', NULL, '松本保典', 189, 195123, 'MAIN', 1617) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021310', 'AN1931', '鎌田貴理子', '鎌田貴理子は、警察に勤務する警部補である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b208599-G7DXdg3TQfxa.png', NULL, NULL, '本田貴子', NULL, 208599, 'SUPPORTING', 36) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021311', 'AN1931', 'カズ', 'カズは『S』に登場するスケーターの一人だ。シャドウと対戦する予定だったが、レキが間違ったスケートボードを持ってきてしまったため、対戦には至らなかった。 彼は、シャドウとの対決で敗れたことをきっかけに、シャドウに対して恨みを抱いているようで、その後、シャドウの勝利がミキがカズのもとを去った原因となったことから、シャドウを襲撃しようと企てた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b265395-EZHJ4sLzxM1K.png', NULL, NULL, '福西勝也', NULL, 265395, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021312', 'AN1931', '知念の母', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b358551-HoqZcscHmRW6.png', NULL, NULL, '遠藤さき', NULL, 358551, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021313', 'AN1931', '馳河菜々子', 'ランガの母親。日本で育ち、夫のオリバーと共にカナダへ移住した。夫が亡くなった後、ランガと共に日本へ戻った。ランガの怪我を心配してパニックになる様子からもわかるように、息子をとても大切に思っている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b212448-aFo7OW7H0Tsu.jpg', NULL, NULL, '園崎未恵', NULL, 212448, 'SUPPORTING', 168) ON CONFLICT DO NOTHING;
