INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021315', 'AN1931', '知念の父', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b358552-ZQ6PQvaapdVe.png', NULL, NULL, '田邊幸輔', NULL, 358552, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021316', 'AN1931', '岡翔吉', 'オカは「ドープ・スケッチ」のマネージャーで、従業員の、とりわけレキの安否を心から気にかけているようだ。  彼は、大げさな振る舞いや冗談を言うことを恐れない一面を見せている。例えば、レキとランガに対し、荷物を届けられなかった理由を、「ドープ・スケッチの借金を返済するために働かなければならなかったから」だと信じ込ませた時などがそうだ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b213236-iNnVLgnQ0DYE.png', NULL, NULL, '大隈健太', NULL, 213236, 'SUPPORTING', 53) ON CONFLICT DO NOTHING;
