INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021329', 'AN1931', 'ハリー', '予選トーナメントを勝ち抜いた「S」クラスのスケーターで、その後シャドウと対戦して敗れた。ハリーのトーナメントカードは「ダイヤの6」だ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b358589-K09eBZSQN1D0.png', NULL, NULL, NULL, NULL, 358589, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
