INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021333', 'AN1931', 'エマ', 'エマは、ランガをストーカーしているのを見かけた少女だ。彼がスケートをしているのを見たとき、彼女は「本物のランガにしては下手すぎる」と思い、その場を立ち去った。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b265394-KLH7sEYYA6UK.png', NULL, NULL, '早見沙織', NULL, 265394, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021334', 'AN1931', '花屋店長', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b358558-BOCc86Pb1ks4.png', NULL, NULL, '関根有咲', NULL, 358558, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021335', 'AN1932', '中野四葉', '彼女は中野五つ子の四女であり、『クインテッセンシャル・クインテット』シリーズの主人公の一人です。明るく元気な性格で、人を助けたいという気持ちが非常に強いです。ヨツバは活動的で気さくな女の子です。 助けを必要としている人に対して「いいえ」と言えないタイプの人物だ。また、体力にも非常に優れており、姉妹たちにはできないような仕事もこなせる。持久力に優れ、スポーツも得意だ。姉妹の中で唯一、優れた', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126374-Aal36iSQ5nKz.png', '5月5日', 'A', '佐倉綾音', 159, 126374, 'MAIN', 5578) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021336', 'AN1932', '中野一花', '中野五つ子の長女。姉妹間の年齢差はほとんどないものの、彼女はしっかりと長女としての役割を果たしている。また、姉妹たちの相談相手であり、リーダーとして信頼されている。一花は女優になることを夢見ている。二郎をからかうのが好きだ。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126371-0KQpl80s8kXQ.png', '5月5日', 'A', '花澤香菜', 159, 126371, 'MAIN', 3563) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021337', 'AN1932', '中野二乃', '中野五つ子の次女。普段は一家の母のような役割を果たしており、食事の支度や家族の健康管理を担当している。五姉妹の中で、フタロに対して最も敵意を抱いており、しばしば彼に反抗する。  ニノは口が鋭く、相手が姉妹であっても、対峙する際には遠慮なく率直に物を言う。社交的で人付き合いがうまく、そのおかげで多くの友人がいる。彼女は策略家であり、決して……', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126372-DtorHRgQaYUJ.png', '5月5日', 'A', '竹達彩奈', 159, 126372, 'MAIN', 11252) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021338', 'AN1932', '中野三玖', '中野五つ子の三女。物静かで内気な少女だ。ミクは悲観的な傾向があり、自分自身に対する自信があまりない。フタロウの影響もあって、姉妹の中で真っ先に彼に心を開いた。  ミクは日本の歴史（特に戦国時代の武将）が好きで、彼らの思想に深く感化されており、その影響は実生活での振る舞いにも表れている。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126373-CWeyXb822uDN.png', '5月5日', 'A', '伊藤美来', 159, 126373, 'MAIN', 12329) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021339', 'AN1932', '中野五月', '中野五つ子の五女。イツキは真面目で誠実な少女だ。話し方は丁寧で礼儀正しい。また、自分自身に正直になれず、もっと率直になることに苦労している。  姉妹の中で、イツキは上杉家の家族や事情について最も詳しい。 <i>注：第14巻のキャラクターファイルによると、イツキの実際の誕生日は5月6日（真夜中に生まれたため）である。彼女は5月5日に誕生日を祝い、他人がその日を見るのを防いでいる。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126375-dEe9IyQ9By09.png', '5月6日', 'A', '水瀬いのり', 159, 126375, 'MAIN', 16211) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021340', 'AN1932', '上杉風太郎', 'フタロウは『5人組の花嫁』シリーズの主人公である。彼は旭山高校の生徒で、父親の上杉勇也と妹の上杉らいはと共に、小さなアパートで暮らしている。 真面目で勤勉な高校生であり、学年でトップの成績を誇る秀才だ。家庭が常に貧しい状況にあるため、中野家の五つ子の家庭教師をするという申し出を受けた。二郎は、自尊心が強く自信に満ちていることで知られている。彼は率直で、空気が読めず、無鉄砲なところがある。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b128063-0h9piZcxa2zt.png', '4月15日', NULL, '松岡禎丞', 178, 128063, 'MAIN', 1420) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021341', 'AN1932', '下田', '彼女は高校2年生の頃、中野玲奈（中野五つ子の母）の教え子であり、現在は塾の講師を務めている。物語の冒頭で、中野家の墓参りに訪れた際に中野五月と出会う場面が登場する。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b157106-xhl6A5ymcZ71.png', NULL, NULL, '矢作紗友里', NULL, 157106, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021342', 'AN1932', '江場', '彼女は高校3年生で、陸上部のキャプテンを務めている。江場は四葉の運動神経の高さを称賛し、四葉が断ろうとしたにもかかわらず、そののんびりした性格をうまく利用して、陸上部に入るよう強く勧めた。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b157114-nor8ubz9NS59.png', NULL, NULL, '安齋由香里', NULL, 157114, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021343', 'AN1932', '五つ子の祖父', '彼は中野五つ子の母方の祖父であり、中野玲奈の父親である。また、虎岩温泉旅館の支配人を務めている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b157107-3LaunQHpBjkJ.jpg', NULL, NULL, '仲野裕', NULL, 157107, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021344', 'AN1932', '江端', '彼は中野マルオの秘書であり、時折、中野五つ子の運転手も務めている。江場taは、かつて学校教師として働いていた経歴があると言われている。彼は五つ子を深く気遣っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b157111-ZoTYFC9wUyuo.png', NULL, NULL, '三瓶雄樹', NULL, 157111, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021345', 'AN1932', '復活の店長', '洋菓子店「リバイバル」の店主。彼の店は、パン屋「コムギヤ」と肩を並べるほどだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b157189-3usaBJodo4hs.jpg', NULL, NULL, '鳥海浩輔', NULL, 157189, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021346', 'AN1932', '竹林', 'フタロの幼なじみ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154885-LGd2FnCAVHeQ.png', NULL, NULL, '京花優希', NULL, 154885, 'SUPPORTING', 22) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021347', 'AN1932', '前田', '旭山高校の生徒。学校のキャンプ旅行の前に、前田は中野一花に、ある授業の時間に会ってほしいと頼み、そこでキャンプファイヤーのダンスで一緒に踊ってほしいと頼むつもりだった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b157144-eeqJzAn8dbgA.png', NULL, NULL, '伊東隼人', NULL, 157144, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021348', 'AN1932', '真田', '彼は、上杉風太郎の京都旅行の回想シーンに登場した少年だ。風太郎と同様、勉強に熱心で、修学旅行中さえも数学の問題を解いていた。彼と竹林は幼なじみだった。二人とも学級委員だったため、クラスメートたちはこの二人がお似合いのカップルだと考えていた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b157198-qkN0ZBb7CYyz.png', NULL, NULL, '真野あゆみ', NULL, 157198, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021349', 'AN1932', 'こむぎやの店長', 'パン屋「コムギヤ」の店主。彼女の店は、パティスリー「リバイバル」と肩を並べる存在だ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b157192-iGen1VVa0aJN.png', NULL, NULL, '咲々木瞳', NULL, 157192, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021350', 'AN1932', '葵', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b255410-9KVmsZPL3Ejd.jpg', NULL, NULL, '咲々木瞳', NULL, 255410, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021351', 'AN1932', '上杉らいは', 'フタロの陽気な妹。家族の中で唯一の女性であり、最も家族思いなため、事実上この小さな家庭の中心的存在となっている。その愛らしい表情は、しばしば周囲の心を和ませる。フタロが家族のために尽くしていることを感謝し、彼が遅く帰宅する時には、彼の好物を作るために夕食の準備を遅らせることもある。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n130111-1yzV9Z9X7xwe.png', NULL, NULL, '高森奈津美', NULL, 130111, 'SUPPORTING', 347) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021352', 'AN1932', '武田祐輔', '彼は3年1組の生徒である。外見、性格、人気という点において、上杉風太郎の対極に位置する人物として紹介されている。風太郎は常に学年でトップの成績を収めており、そのせいでユウスケは哀れな2位にとどまっているため、ユウスケは風太郎を羨ましく思っている。 ユウスケは風太郎をライバルと見なしているが、風太郎本人はそのことに全く気づいていない。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b157112-NdhuTe2zXyhM.png', NULL, NULL, '斉藤壮馬', NULL, 157112, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021353', 'AN1932', '中野マルオ', '物語が始まる数年前、中野五つ子の母親が再婚した際に、彼らの継父となった人物。大規模な病院を経営しており、医師でもある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b135383-lOnQOjuLpWrr.jpg', NULL, NULL, '黒田崇矢', NULL, 135383, 'SUPPORTING', 44) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021354', 'AN1932', '上杉勇也', 'フタロとライハの父親。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n130110-GG3wMoAToHYF.png', NULL, NULL, '日野聡', NULL, 130110, 'SUPPORTING', 82) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021355', 'AN1932', '椿', '椿は旭山高校3年1組の生徒です。放送部の部員です。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b214405-7y35ObvxIrP9.jpg', NULL, NULL, '佐伯伊織', NULL, 214405, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021356', 'AN1933', '蜘蛛子', '自らを「身分の低い」と称する女子高生が、クモとして転生した。   前世では引きこもりとしてゲームに没頭していたが、今やその並外れた精神力を駆使して生き残りをかけて戦っている。彼女は、敏捷性、クモの糸、毒牙を駆使した戦闘術で、低いステータスを補っている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b122124-6ymNNXYfvyXO.png', NULL, NULL, '悠木碧', NULL, 122124, 'MAIN', 2311) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021357', 'AN1933', 'シュレイン・ザガン・アナレイト', 'アナレイト王国の第四王子。前世での名は山田俊介。彼は典型的な平均的な高校生そのものであり、転生後もその性質は変わっていない。 しかし、彼は英雄である兄のジュリアスを深く尊敬しており、兄に追いつくために日々懸命に努力している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130487-zAL7NaUpGWI7.png', NULL, NULL, '堀江瞬', NULL, 130487, 'MAIN', 42) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021358', 'AN1933', 'ユーリーン・ウレン', 'アレイウス聖王国の聖人候補者。前世での名は長谷部ユイカ。非常に真面目で礼儀正しいが、周囲の状況を見失いがちである。 転生後、彼女は両親に見捨てられ、教会に育てられた少女の人生を引き継ぎ、現在は「神の声を聞くために自らの技を磨く」という信条を掲げる「神の言葉」教の熱心な信者となっている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130494-BnqKAbgkh3si.jpg', NULL, NULL, '田中あいみ', NULL, 130494, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021359', 'AN1933', 'D', 'Dは神だ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b130493-xJmMFM5ywmSh.jpg', NULL, NULL, '早見沙織', NULL, 130493, 'SUPPORTING', 73) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021360', 'AN1933', 'Meiges Derra Analeit', 'メイゲス・デラ・アナレイトは、アナレイト王国の王である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b212896-SqKrn8xq68sY.png', NULL, NULL, '家中宏', NULL, 212896, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021361', 'AN1933', 'ホーキン', 'かつて「紳士泥棒」と呼ばれた人物であり、ジュリアスの仲間の一人。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b217329-3zCJEASnD7Sf.png', NULL, NULL, '石井隆之', NULL, 217329, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021362', 'AN1933', 'アサカ', 'アサカは冒険者であり、転生前も転生後もクニヒコの幼なじみである。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b210659-hTmVEhvHnhDx.png', NULL, NULL, '佐倉綾音', NULL, 210659, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021363', 'AN1933', 'フィリメス・ハァイフェナス', '前世では、転生した子供たちの担任教師だった岡崎かなみであり、子供たちからは親しみを込めて「オカちゃん」と呼ばれている。 転生後、彼女はシュンたちと同じクラスとして学校に通い始めた。エルフとして転生したため、実年齢よりも若く見える。転生後も生徒たちを見守り続ける思いやりのある教師だが、彼女には多くの秘密がある。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130481-hAxal3tTCk03.png', NULL, NULL, '奥野香耶', NULL, 130481, 'SUPPORTING', 193) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021364', 'AN1933', 'ユリウス・ザガン・アナレイト', 'アナレイト王国の第二王子。ユリウスはシュンの兄であり、全人類の中で最強の英雄である。剣術と魔法の両方を極め、戦場でも数々の功績を残しているにもかかわらず、彼は謙虚で、決して傲慢ではない。世界平和のために戦うことに身を捧げる、真の英雄である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b196477-CtuAdOYMCICR.jpg', NULL, NULL, '榎木淳弥', NULL, 196477, 'SUPPORTING', 25) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021365', 'AN1933', 'ギュリエディストディエス', 'ギュリエディスト・ディエス（通称：ギュリエ、クロ、またはブラック）は、システムの管理者の一人である。蜘蛛子によれば、彼は「非常に陰鬱な男」であるとされている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130488-1dcb39lVTAIc.png', NULL, NULL, '浪川大輔', NULL, 130488, 'SUPPORTING', 48) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021366', 'AN1933', 'Kogou', 'コゴは、魔王アリエル率いる第三魔軍の司令官である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b212897-oZ8QIQfyime6.jpg', NULL, NULL, '藤井隼', NULL, 212897, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021367', 'AN1933', 'ジスカン', 'ジスカンは、かつての冒険者で、ジュリアスのパーティーに加わった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b217328-b2QyNiuRAjL8.png', NULL, NULL, '沖野晃司', NULL, 217328, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021368', 'AN1933', 'ユーゴー・バン・レングザンド', 'レンザント帝国の皇太子。前世では夏目健吾という名で、クラスのリーダー的存在と見なされていた。 その実力は本物だが、自分の能力を誇張する癖があるため、その実力の真価が十分に伝わらない。前世と同様に好戦的であり、シュンをライバル視している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n130491-VV3AQMTbLHoo.png', NULL, NULL, '石川界人', NULL, 130491, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021369', 'AN1933', 'バルト・フィサロ', '魔王の側近。かつては魔界社会の指導的立場にあったが、魔王が台頭して以来、彼女に忠誠を誓っている。実弟は、第七魔軍団の司令官であるブロエである。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b211284-WznCqlOCQaGA.png', NULL, NULL, '梅原裕一郎', NULL, 211284, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021370', 'AN1933', 'ブロウ・フィサロ', 'ブロウ・フィサロはバルトの兄弟であり、第七魔軍司令官である。大剣を振るう戦士であり、性格も外見も少々荒々しいところがある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b212898-Y3RyWkF5QWEo.jpg', NULL, NULL, '木村昴', NULL, 212898, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021371', 'AN1933', 'ダスティン', 'ダスティン LXI は、「神の言葉」教の第57代教皇である。世界最大の宗教の頂点に立つ高齢の男性であり、信者たちは彼を神に最も近い存在として崇めている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b217318-hwl1sNFMsjD5.png', NULL, NULL, '松山鷹志', NULL, 217318, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021372', 'AN1933', 'アリエル', '現魔王。  （出典：『雲ですが、何か？』Wiki）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130477-Szp3TMGbCCab.png', NULL, NULL, '上坂すみれ', NULL, 130477, 'SUPPORTING', 521) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021373', 'AN1933', 'ラース', 'かつて「笹島京也」として知られていたラースは、転生した生徒の一人である。転生後、彼はゴブリンの村でゴブリンとして生まれ変わり、武器を作り出す特殊スキルを持っていた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130478-AwSSj9UXo7ht.png', NULL, NULL, '逢坂良太', NULL, 130478, 'SUPPORTING', 95) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021374', 'AN1933', 'ロナント・オロゾイ', 'ロナントは帝国宮廷魔術師団の長である。彼は世界で最も著名な魔術師であり、空間魔法さえも極めた驚異的な人物と見なされている。おそらく、現存する人間の中で最強の存在だろう。ユリウスの師匠として、彼はユリウスのことを多少気にかけていた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130489-6Xwzl5K7VNId.png', NULL, NULL, '飛田展男', NULL, 130489, 'SUPPORTING', 23) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021375', 'AN1933', 'サーナトリア・ピレヴィ', 'サナトリアは、アリエル配下の指揮官の一人である。彼女は第二魔軍を率いている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b212899-GfLhv2NnUOCH.png', NULL, NULL, '大原さやか', NULL, 212899, 'SUPPORTING', 15) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021376', 'AN1933', 'バスガス', 'ゴイエフの父親で、元迷宮ガイド。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b226466-nzN4r263bFhM.png', NULL, NULL, '斧アツシ', NULL, 226466, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021377', 'AN1933', 'ソフィア・ケレン', 'ソフィア・ケレンは、前世では根岸翔子として知られていた、転生した生徒の一人である。彼女は、人間の貴族であるケレン家に「真の吸血鬼」として転生した。親族は普通の人間であるため、彼女は自分が吸血鬼であることを隠している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130482-ot2Zp8BKIUOy.png', NULL, NULL, '竹達彩奈', NULL, 130482, 'SUPPORTING', 234) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021378', 'AN1933', 'サイリス', 'シュンは、アナレイトの第一王子であり、女王の長男として王位継承順位第一位にある、責任感の強い兄である。父のメイゲスは、サイリスが王になればアナレイトは安泰だと考えていた。シュンは、その真剣な態度に戸惑いを覚えている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b212892-Pwkom8YTWEIc.png', NULL, NULL, '近藤隆', NULL, 212892, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021379', 'AN1933', 'ダラド', 'ダラドは第5魔軍団の司令官である。彼は、じんばおりを身にまとった、厳格な風貌の長髪の男性として登場する。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b212900-UzMcC5W7o1Aj.jpg', NULL, NULL, '橘龍丸', NULL, 212900, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021380', 'AN1933', 'ゴイエフ', 'バスガスの息子。グレート・エルロー迷宮でガイドとして働いている。過去にジュリアスのパーティーのガイドを務めたこともある。ガイドとしての才能は相当なものだが、指名手配されていたシュンのパーティーのガイドを務めることは断った。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b226467-vQkUwBbGttHx.png', NULL, NULL, '近藤浩徳', NULL, 226467, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021381', 'AN1933', '地龍ガキア', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b244204-6CGyrLo5JdMZ.jpg', NULL, NULL, '松山鷹志', NULL, 244204, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021382', 'AN1933', 'スーレシア・アナレイト', 'アナレイト王国の第二王女。シュンの異母妹であり、彼の誕生から間もなくして別の母親の間に生まれたが、その才能は兄に引けを取らない。兄のシュンに対する執着は、周囲を不快にさせるほど極端であり、シュンと親しくなる少女たちすべてに対して、明らかに敵意を抱いている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130486-yfrr3oQv4a3I.jpg', NULL, NULL, '小倉唯', NULL, 130486, 'SUPPORTING', 31) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021383', 'AN1933', 'ヤーナ', 'ヤーナは、「神の言葉」という宗教の前の聖人で、英雄としての任務を遂行するジュリアスを支援するために派遣された。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b208069-IFSFqsPkEjRJ.png', NULL, NULL, '小坂井祐莉絵', NULL, 208069, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021384', 'AN1933', 'ブイリムス', 'ブイリムスは、レンクサンド帝国軍の召喚師であり、偵察部隊の一員でもある。召喚師としての優れた能力を持つだけでなく、有能な指揮官であり、一流の戦士でもある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b212893-6DpayhyOjzwY.png', NULL, NULL, '平川大輔', NULL, 212893, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021385', 'AN1933', 'ポティマス・ハァイフェナス', 'ポティマス・ハイフェナスは、エルフの村の長であり、同村の特使である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b130480-9v6tt3G4Jpiy.png', NULL, NULL, '森川智之', NULL, 130480, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021386', 'AN1933', 'カルナティア・セリ・アナバルド', 'アナバルド公爵の娘。前世では「大島カナタ」という名の少年だったが、美しい少女として転生した。シュンに匹敵する天才であり、前世からの親友でもある。 普段は優雅で上品な話し方をするが、同じく転生した者たちと話すときは、男の子のような口調になる。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130479-Dh5O2TiZ1WPA.png', NULL, NULL, '東山奈央', NULL, 130479, 'SUPPORTING', 186) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021387', 'AN1933', 'ハイリンス・クォート', 'ハイリンス・クォートは、ジュリアスの幼なじみであり、ヒーローパーティのタンクを務める。アナレイト王国のクアルト公爵の次男として、友人や故郷を守ることに身を捧げてきた気骨ある貴族である。シュンにとっては、まるで叔父のような存在だ。  第13巻 ネタバレ', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b208070-NTrcUTocRCt7.png', NULL, NULL, '興津和幸', NULL, 208070, 'SUPPORTING', 14) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021388', 'AN1933', 'メラゾフィス', 'メラゾフィスは、ソフィアによって人間から吸血鬼へと変えられた人物である。彼はソフィアの執事でもあり、彼女が幼少の頃には世話役を務めていた。現在は第四魔軍団の司令官を務めているが、依然としてソフィアの執事であり、故郷に残る唯一の家族でもある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130492-mAAhuydjJLjv.png', NULL, NULL, '津田健次郎', NULL, 130492, 'SUPPORTING', 34) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021389', 'AN1933', 'フェイルーン', 'シュンのペットであるアース・ワーム。前世では篠原美玲という少女だったが、人間ではなくモンスターとして転生した。 モンスターとして、彼女のステータスは非常に速いペースで成長し、状況判断力にも優れている。明るくオープンな性格だが、前世ではいじめっ子だったため、その傾向が現在の振る舞いにも表れている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n130483-MmVjcd4YXPGZ.png', NULL, NULL, '喜多村英梨', NULL, 130483, 'SUPPORTING', 524) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021390', 'AN1933', 'アーグナー・ライセップ', 'アーグナー・ライセップは、悪魔の指揮官の一人である。彼は魔王の第一悪魔軍の指揮官である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b212895-bgOdk5CrSu64.png', NULL, NULL, '桐本拓哉', NULL, 212895, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021391', 'AN1933', 'アナ', 'アナは、代々の王に仕えてきたハーフエルフの侍女である。彼女はシュレインとスーの養親のような存在であり、同僚のクレアヴァと共に、二人のメイド兼護衛を務めている。一級の魔法使いでもある彼女は、いざという時には王族を守るために戦う侍女である。  （出典：『蜘蛛ですが、何か？』Wiki）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b217696-I23BJge8gfFI.png', NULL, NULL, '武田羅梨沙多胡', NULL, 217696, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021392', 'AN1933', 'クニヒコ', 'クニヒコは冒険者であり、転生前も転生後も、アサカの幼なじみである。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b217330-3KAD9NAmTfW6.png', NULL, NULL, '斉藤壮馬', NULL, 217330, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021393', 'AN1934', 'フレア・アールグランデ・ジオラル', '彼女は「マジック・ヒーロー」であり、本作のヒロインである。彼女はジオラル王国の王女である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b139397-uH8oOdszIlAE.png', NULL, NULL, '渋谷彩乃', NULL, 139397, 'MAIN', 543) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021394', 'AN1934', 'セツナ', 'セツナはアイスウルフ一族に属する女性で、半人半獣である。騎士団に捕らえられ、奴隷として売られた。その後、ケヤルに買い取られ、より強くなるため、そしてジオラル王国への復讐を果たすために、彼のパーティーに加わった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b139402-huCQ43yYQABC.png', NULL, NULL, '石上静香', NULL, 139402, 'MAIN', 763) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021395', 'AN1934', 'ケヤル', '幼い頃のケヤルは、素朴で心優しい少年だった。自分が英雄であることを知った彼は、世界を救うために旅立ち、フレアと出会うが、彼女の真の意図には気づかなかった。 監禁され、殴打され、薬物を投与され、レイプされた後、彼の行動は一変し、復讐心に燃えるサディスティックな人物へと変貌した。魔女王を倒した後、彼は彼女の賢者の石を使って4年前にタイムスリップし、フレアへの復讐を誓う。タイムリセット後、彼は記憶を取り戻し、ある存在と契約を結ぶことで新たな能力を手に入れる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b139400-yNnS77psdh6a.jpg', NULL, NULL, '保住有哉', NULL, 139400, 'MAIN', 942) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021396', 'AN1934', 'クレハ・クライレット', 'クレハ・クライレットは、ジオラル王国の元騎士である。 彼女は「ブレイドの女神」や「剣の聖人」として広く知られている。当初はケヤルのパーティーに敵対していたが、やがて彼らと手を組み、自国による残虐行為や誤った先入観を知り、自分が彼らにとって単なる駒に過ぎないことに気づいたことで、ジオラル王国を裏切った。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b139401-zDY9FkZPrdWh.png', NULL, NULL, '相川奈都姫', NULL, 139401, 'MAIN', 364) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021397', 'AN1934', 'ノルン・クラタリッサ・ジオラル', '彼女はジオラル王国の第二王女であり、フレアの妹である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b139398-Hana6il5w6fi.png', NULL, NULL, '津田美波', NULL, 139398, 'MAIN', 290) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021398', 'AN1934', 'イヴ・リース', 'イヴ・リースは、黒翼族出身の悪魔であり、同族の魔王候補である。彼女の目的は、同胞を根絶やしにしようとした現魔王・白王を殺すことである。', 51, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b174594-60gt3sr87JdC.png', NULL, NULL, '高森奈津美', NULL, 174594, 'MAIN', 399) ON CONFLICT DO NOTHING;
