INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021418', 'AN1936', 'レゴシ', '主人公は、物静かで繊細な灰色のオオカミ、レゴシだ。その恐ろしい外見と風変わりな習性ゆえ、彼はよく「恐ろしい、血に飢えた肉食獣」と誤解されている。レゴシはこれを十分に自覚しており、自分の存在感を最小限に抑え、威圧的な側面を目立たせないよう全力を尽くしている。 このシリーズは、主に彼がオオカミとしての自分の居場所を受け入れていく過程を描いている。レゴシは、ウサギのハルに対して複雑な感情を抱くようになる。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125168-cOydxRHEbAYb.png', '4月9日', 'O', '小林親弘', 185, 125168, 'MAIN', 6975) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021419', 'AN1936', 'ハル', '品種：オランダ・ドワーフ・ラビット　ハルは、チェリートン・スクールの園芸部の唯一の部員である。彼女は真面目で率直な性格だが、その性的に奔放な面も相まって、下品な評判を招いてしまっている。ハルは概して自信に満ちているが、その表向きの姿の背後から、時折、敗北主義的な一面が垣間見える。 思いやりのある性格であるにもかかわらず、彼女は人に対して感情的な距離を置きがちだ。', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125169-zxyLpg1BOnU5.jpg', '10月19日', NULL, '千本木彩花', NULL, 125169, 'MAIN', 1218) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021420', 'AN1936', 'ルイ', '種：アカシカ　チェリートンの演劇部の目立ちたがり屋。とてつもない自尊心を持っているが、彼ほどの演技力ならそれも不思議ではない。 伝統的に肉食動物の餌と見なされてきた鹿という立場ゆえに、彼は数多くの性格上のコンプレックスを抱えている。時折、純粋な優しさを見せることもあるが、感情を巧みに操る面も強い。ルイの最大の野望は、ビーストアーの地位に就くことである。（出典：TV Tropes）', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125170-TIHSOgfQbkbU.png', '3月29日', NULL, '小野友樹', NULL, 125170, 'MAIN', 2197) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021421', 'AN1936', 'ジュノ', '種族：ハイイロオオカミ　ジュノは『ビーストスターズ』の5人の主人公の一人で、演劇部の「俳優チーム」に所属している。女性的で人当たりの良いオオカミであり、ルイと競い合いながら、次期ビーストスターになることを目指している。', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b132946-H4bYx7gFT0Ki.png', '2月12日', NULL, '種﨑敦美', NULL, 132946, 'SUPPORTING', 588) ON CONFLICT DO NOTHING;
