INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021423', 'AN1936', 'ドーム', '種：クジャク　ドームはチェリートン・アカデミーに通っており、レゴシと共に演劇部のメンバーである。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b160358-M7Issc6OQeBp.jpg', '11月5日', NULL, '室元気', NULL, 160358, 'SUPPORTING', 29) ON CONFLICT DO NOTHING;
