INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021428', 'AN1936', 'ゴウヒン', '肉を渇望する肉食動物たちの更生を試みる、裏通りの精神科医。彼の顔の傷は、暴力的だった患者たちによってつけられたものだ。 荒々しい外見と荒っぽい性格とは裏腹に、彼は優しく思いやりのある人物である。', 39, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b132948-HzBozI7pzdte.png', '6月9日', 'O', '大塚明夫', NULL, 132948, 'SUPPORTING', 974) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021429', 'AN1936', 'イブキ', '職業：獅子組のメンバー　イブキは30代半ばのマサイライオンで、アスリートのような体格をしている。毛色は淡い黄金色で、たてがみは薄茶色、鋭くつり上がった目には小さな黒い瞳孔がある。 イブキは、幼少期にハイパードラッグの製造に利用されそうになった際に、体の左側にタトゥーを刻まれている。', 35, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b132985-hb60Fj8P43er.png', '11月3日', NULL, '楠大典', NULL, 132985, 'SUPPORTING', 207) ON CONFLICT DO NOTHING;
