INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021433', 'AN1936', 'ジャック', '犬種：ラブラドール・レトリバー　レゴシのルームメイトの一人であり、長年にわたり親友でもあるジャックは、ごく普通の男だ。彼は、特にハルに関わるレゴシの行動にしばしば戸惑うこともあるが、親友のためならいつでも力になってくれる。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b132982-hy5W6uQCvVYW.png', '12月22日', NULL, '榎木淳弥', NULL, 132982, 'SUPPORTING', 659) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021434', 'AN1936', 'フリー', '「シシグミ」の現役メンバーであるインディアン・ライオン。', 30, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b194483-GslsNZuC3eZN.png', '9月13日', 'A', '木村昴', NULL, 194483, 'SUPPORTING', 25) ON CONFLICT DO NOTHING;
