INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021436', 'AN1936', 'シイラ', '彼女は『ビーストスターズ』の脇役です。チェリートン・アカデミーの演劇部で、振付主任を務めています。漫画版ではシェリアはチーターですが、アニメ版ではヒョウとなっています。', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b160350-7dtrCieQXsyt.png', '6月21日', NULL, '原優子', 160, 160350, 'SUPPORTING', 28) ON CONFLICT DO NOTHING;
