INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021438', 'AN1936', 'ボス', 'ほっそりとした体つきで、体がとても小さいフェネックキツネ。レゴシと同じ「犬族701」の一員だ。体が小さいため、寮の同室であるコロに背中に乗せてもらっている姿をよく見かける。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b160353-ce7ze5gYPlOu.png', '2月14日', 'A', '下妻由幸', 40, 160353, 'SUPPORTING', 23) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021439', 'AN1936', 'ロクメ', 'ロクメは『ビーストスターズ』に登場する脇役の一人です。彼女はチェリートン・アカデミーの唯一の警備員です。ロクメはとても臆病な性格で、いつも人目につかない場所に隠れているため、普段は誰ともほとんど交流しません。 また、ロクメは（特にレゴシの行動に対して）すぐに興奮してしまう傾向がある。彼女自身、手足がないという「恥」を生まれつき背負っており、隠れてこそそれを耐え忍ぶことができるため、レゴシを羨ましく思っているとも語っている。（出典：Beastars Fandom Wiki）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b204637-Bw76iZjWSjJC.png', NULL, NULL, 'くじら', NULL, 204637, 'SUPPORTING', 36) ON CONFLICT DO NOTHING;
