INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021442', 'AN1936', 'カイ', 'カイは、小柄で茶色の毛並みを持ち、体格も顔立ちもほっそりとしたマングースだ。顔立ちは小さいが、表情豊かである。カイは意欲的で、大胆不敵であり、自分の実力を証明することに必死だ。 度を越して野心的であるため、やや自己中心的な一面も見せる。テムの死後、彼はほとんど悲しみを表さず、その役職が自分に回ってくるだろうと予想し、むしろ自身のキャリアアップの好機と捉えていた。（出典：Beastars Wikia）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b159863-lBL35G6CRuRZ.png', NULL, NULL, '岡本信彦', NULL, 159863, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021443', 'AN1936', 'ダラム', 'コヨーテは、レゴシと同じ「犬族701」の一員だ。彼はレゴシやコロと相撲や腕相撲をするのが好きだが、どちらにも勝てたことはない。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b160348-NNKVUO8l7vn0.png', '7月7日', 'B', '小林直人', NULL, 160348, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
