INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021446', 'AN1936', 'リズ', 'リズは、演劇部所属の心優しく物静かなクマで、クラスメートから愛され、尊敬されています。彼は、たいてい後ろの方で目立たないようにしているのが好きです。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b132983-hOgSO3VJ9Bmx.png', '12月11日', NULL, '白熊寛嗣', NULL, 132983, 'SUPPORTING', 97) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021447', 'AN1936', 'ミグノ', 'レゴシと同じイヌ科の群れ「701」に所属する斑ハイエナ。「ザ・レフトオーバーズ」というバンドで、ハゲワシと一緒にエレキギターを弾いている。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b160356-HnwooJgdxPlW.png', '8月2日', 'A', '内田雄馬', NULL, 160356, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021448', 'AN1936', 'ビル', 'チェリートン・アカデミーの生徒であり、演劇部の部員であるベンガル・タイガー。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n132945-G5NJQ9JMtF0X.jpg', '8月16日', NULL, '虎島貴明', NULL, 132945, 'SUPPORTING', 76) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021449', 'AN1936', 'ピーチ', 'ピーチは、小柄でほっそりした体つきの若い羊です。他の羊と同じように、顔を除いて全身が羊毛で覆われています。小さな黒い目と長いまつげが特徴です。  ほとんどの草食動物と同様、ピーチも肉食動物を恐れているようだったが、彼らと一緒に写真を撮ったり、見せかけの親密さを保ったりする時には、その恐怖心を脇に置くことができた。 シイラと買い物に行った後、ピーチはシイラと共通点が多いことに気づき、以前ほど批判的ではなくなった。（出典：Beastars Fandom Wiki）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b210163-BDb7gvN1YkHP.png', NULL, NULL, '本渡楓', NULL, 210163, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021450', 'AN1936', 'コロ', 'レゴシと共に「犬団701」の一員であるイングリッシュ・シープドッグ。穏やかで人懐っこい性格で、グループの中で一番小さなメンバーであるボスをよく背中に乗せてあげている姿が見られる。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b160347-0W6WASWlsUap.png', '10月30日', 'AB', '大塚剛央', NULL, 160347, 'SUPPORTING', 64) ON CONFLICT DO NOTHING;
