INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021452', 'AN1936', 'オリックス', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b175781-hIMPJ9Gv3jjQ.jpg', NULL, NULL, '大塚剛央', NULL, 175781, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021453', 'AN1937', 'ゴウセル', '彼は全く世渡りの術を知らず、他人の気持ちにも無頓着で、友情の意味も理解していない。自分の発言が人を不快にさせる可能性があることに気づかず、しばしば事実だけを淡々と述べる。彼がエリザベスの旅に同行することを決めたのは、正義感からではなく、「七つの大罪」の一員としての義務感からだった。  ゴウセルは感情を理解できないため、それを理解しようと多大な努力を払っている。例えば、メリオダスとバンの友情を観察することなどだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b88823-Oppzl2h6OhO8.png', '6月2日', NULL, '高木裕平', 175, 88823, 'MAIN', 1787) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021454', 'AN1937', 'マーリン', '彼女は「七つの大罪」の一員である。彼女は「大食」という罪の印を背負っている。かつてブリタニアで最高の魔導士と称され、ヴィヴィアンの師匠であると同時に、キャメロットのアーサー王の師でもあった。 彼女はヘンドリクソンとの戦いで「七つの大罪」を援護したが、王の世話をするためにその場を離れざるを得なかった。正式には「七つの大罪」に復帰してはいないが、他の用事が済んだら復帰したいと語っている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89180-rN6OVPki8h3V.png', '12月3日', 'AB', '坂本真綾', NULL, 89180, 'MAIN', 1990) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021455', 'AN1937', 'ディアンヌ', 'ディアンヌは『七つの大罪』の一員であり、「嫉妬」の罪を司り、そのシンボルは「蛇」である。また、巨人族の一員でもある。彼女は、ピンク色の瞳と、ミディアムレングスの茶色の髪を「メガツインテール」に結った、美しい乙女である。 美しい外見の乙女だが、実は巨人族の巨人であり、普通の人間よりも数倍も大きい。彼女はオレンジ色のワンピーススーツに、膝近くまで届くブーツ、そして金属製の腕輪を身につけており、その腕輪には', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b74653-XpMcsLVZBnkZ.jpg', '12月24日', NULL, '悠木碧', NULL, 74653, 'MAIN', 2257) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021456', 'AN1937', 'ホーク', 'ホークは、話すことができるブタで、メリオダスの相棒である。彼は「ボア・ハット」というバーの掃除係として登場し、不潔な食べ残しの片付けを手伝っている。 彼は比較的大きなピンクの豚で、左耳には「スター・ボア」と書かれたピアスを付けている。体は丸みを帯びており、足は比較的短い。四つ葉のクローバーのような形をした黒い斑点が特徴的だ。その体つきや外見は、典型的なグロスターシャー・オールド・スポット種の豚によく似ている。', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n86683-ZXPoLZnKqNtx.png', '8月6日', 'B', '久野美咲', NULL, 86683, 'MAIN', 1461) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021457', 'AN1937', 'キング', 'キングは「七つの大罪」の一員であり、グリズリーをシンボルとする「怠惰」の罪を担う。また、オスロの主人でもある。キングの正体は、妖精族の王であるフェアリー・キング・ハーレクインである。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b83801-52RnDXQDZ1I7.png', '4月1日', NULL, '福山潤', 165, 83801, 'MAIN', 2376) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021458', 'AN1937', 'エスカノール', '種族：人間　「七つの大罪」の一員であり、「ライオン」として知られる「高慢の罪」を担う。日中は絶大な力を発揮するが、日が沈むにつれて徐々に力が衰え、夜になると虚弱で従順な姿になることで知られている。 彼の聖宝は「神斧リッタ」である。彼の固有の力は「サンシャイン」と呼ばれる。', 41, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b90202-1H7FIX2hDmYd.png', '7月1日', 'AB', '杉田智和', NULL, 90202, 'MAIN', 4198) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021459', 'AN1937', 'バン', 'バンは『七つの大罪』の一員であり、キツネをシンボルとする「貪欲の罪」である。彼はバステの地下牢に投獄されていた。', 43, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b77605-NrjhQwZwgJ3l.png', '2月14日', NULL, '鈴木達央', 210, 77605, 'MAIN', 8527) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021460', 'AN1937', '魔神王', '「魔王」は魔族の支配者である。彼は「十戒」を自ら選び出し、彼らに「戒律」を授けた人物でもある。また、魔族の中でも最も強力な3人であるメリオダス、エスタロッサ、ゼルドリスの父でもある。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b131847-VxEP7hxpRBQf.jpg', NULL, NULL, '玄田哲章', NULL, 131847, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021461', 'AN1937', 'スレイダー', 'スレイダーは幼い頃、人間としての価値を全く顧みない野蛮人たちに誘拐され、育てられた。リオネスの王に救い出された後、彼は忠誠を誓い、王国に害をなした者たちをすべて追い詰めることを決意した。彼は「ドーン・ロア」の一員であり、「七つの大罪」のゴウセルとライバル関係にある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n131889-hA4qiH1hg8oL.jpg', '4月4日', NULL, '三木眞一郎', NULL, 131889, 'SUPPORTING', 69) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021462', 'AN1937', 'ワイルド', '種族：イノシシのような煉獄の生物　ワイルドは、煉獄に住み、弟を探しているイノシシのような生物である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b202725-ZGs8coLubtdf.jpg', '2月9日', NULL, '宮野真守', NULL, 202725, 'SUPPORTING', 64) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021463', 'AN1937', 'ゲラード', 'ゲラードは、前代フェアリー王の元顧問である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n131897-SR5n42q9eRG1.jpg', '5月4日', NULL, '諸星すみれ', NULL, 131897, 'SUPPORTING', 26) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021464', 'AN1937', 'デルドレー', 'デルドレーは、大聖騎士デンゼルの補佐官に仕える「紺碧の空のプレアデス」の一員である聖騎士だ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n131899-ptB4qp8h2mTs.jpg', '5月23日', NULL, '加藤英美里', NULL, 131899, 'SUPPORTING', 21) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021465', 'AN1937', 'アーデン', 'アーデンは、リオンズの聖騎士であり、「紺碧の空のプレアデス」の一員としてデンゼルの配下で仕えている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n131892-KRUDC2KNzAl3.jpg', NULL, NULL, '豊永利行', NULL, 131892, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021466', 'AN1937', 'エレイン', 'エレインはキングの妹であり、ヨスの泉の守護聖人である。彼女は長くて細いまつ毛を持ち、首元まで届くショートヘアをしている。背中で蝶結びにした白いワンピースを1枚着ている。エレインは、親切で思いやりがあり、寛容な少女として描かれている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/86681-6kx3mfwNhraK.png', '3月14日', NULL, '小岩井ことり', NULL, 86681, 'SUPPORTING', 636) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021467', 'AN1937', 'リュドシエル', 'リュドシエルは、「女神一族の大天使たち」のリーダーである。また、スティグマのリーダーでもある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b132237-ZEOkunHCyEJa.jpg', NULL, NULL, '石田彰', NULL, 132237, 'SUPPORTING', 24) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021468', 'AN1937', 'デスピアス', 'デスピアス は、大聖騎士デンゼルの補佐官に仕える「紺碧の空のプレアデス」の一員である聖騎士だ。', 35, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n131890-160cpseFxUgw.jpg', '1月8日', NULL, '阿座上洋平', NULL, 131890, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021469', 'AN1937', 'キャス', 'キャスは、小さな猫の頭と尾だけがあるように見える、謎めいた猫のような生き物だ。その毛並みは白く、赤い模様が入っている。キャスはまた、アーサー・ペンドラゴンがイスターでの修行を終えた後に手に入れた、謎めいたペットでもある。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b161847-x0jbAbyAGL4k.jpg', NULL, NULL, '悠木碧', NULL, 161847, 'SUPPORTING', 26) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021470', 'AN1937', 'デリエリ', 'デリエリは、悪魔一族のエリート戦士であり、「十戒の純潔」として悪魔王の直属の配下として仕えている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b131566-2v1OVoEuhaiA.jpg', NULL, NULL, '高垣彩陽', NULL, 131566, 'SUPPORTING', 481) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021471', 'AN1937', '原初の魔神', '「原初の大魔王」は、魔王によって生み出された古代の大魔王である。魔王の王位を巡り反乱を起こしたが失敗に終わり、罰としてその体は二つに分割され、チャンドラーとキューザックという二つの下級の大魔王へと変えられた。（出典：七つの大罪 Wiki）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b214027-7aEaWbmw7Oaj.png', NULL, NULL, '関俊彦', NULL, 214027, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021472', 'AN1937', 'プオーラ', 'プオーラは、フェアリーキングの森に住む妖精です。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n131844-VbHnwMYbd4XF.jpg', NULL, NULL, '矢野奨吾', NULL, 131844, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021473', 'AN1937', 'ローザ', 'ローザは、弟のデイモンドを襲ったとして追われていたエスカノールが、家族から逃れるのを助けた謎めいた女性である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b131846-i9oInJTgQeQY.png', '4月10日', NULL, '坂本真綾', NULL, 131846, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021474', 'AN1937', 'ハウザー', 'ハウザーは聖騎士であり、ギルサンダーの同僚兼パートナーであり、大聖騎士ドレファスの部下である。聖騎士の鎧を身にまとい、明るい色の短い巻き毛をしている。 ハウザーは強い自信に満ちており、非常に楽観的である。これはギルサンダーの性格とは正反対であり、また、やや世間知らずで間抜けな一面も見せている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/86685-EVUJUHwElo95.png', '9月19日', 'B', '木村良平', NULL, 86685, 'SUPPORTING', 222) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021475', 'AN1937', 'キューザック', 'キューザックは、悪魔一族の高位悪魔であり、ゼルドリスの元師匠でもある。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b199211-rUbCSKdkm2pj.jpg', NULL, NULL, '中田譲治', NULL, 199211, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021476', 'AN1937', 'マトローナ', 'マトローナは、ジャイアント一族の戦士長であり、ディアンヌとドロレスの師匠でもある。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n131569-LriSEGMRzsVG.jpg', NULL, NULL, '佐藤利奈', NULL, 131569, 'SUPPORTING', 52) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021477', 'AN1937', 'サイモン', 'はホーリーナイトであり、「ドーン・ロア」のメンバーである', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n131916-lcMq8Y6YHdBe.jpg', '3月5日', NULL, '金本涼輔', NULL, 131916, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021478', 'AN1937', 'ミード', 'ミードは孤児で、旅人だった両親がベルニアに立ち寄った際、疫病の犠牲となった後、ベルニアの村人たちに引き取られた。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n131904-20VtZ6sP26YA.jpg', NULL, NULL, '小林由美子', NULL, 131904, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021479', 'AN1937', 'エスタロッサ', 'エスタロッサは「十戒」の一員であり、魔王の次男である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126851-m1Vyj4V0IHNo.jpg', '1月14日', NULL, '東地宏樹', NULL, 126851, 'SUPPORTING', 364) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021480', 'AN1937', 'サリエル', 'Sariel「サリエル」 is one of the Four Archangels of the Goddess Clan. He is also one of the commanders of Stigma alongside Ludociel and Tarmiel.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b132239-vfPWFWViaV3T.jpg', NULL, NULL, '堀江瞬', NULL, 132239, 'SUPPORTING', 43) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021481', 'AN1937', 'ジェリコ', 'ジェリコは、「ウィアード・ファングス」に仕えていた見習い聖騎士である。彼女は、七つの大罪の一つである「バン」が投獄されていたバステ・ダンジョンに駐屯していた。彼女はほっそりとした体型の若い女性で、明るい色の髪を顔の左側に流し、後ろでポニーテールに結んでいる。 鎧の上には黒いコートを羽織っており、左側には十字架の装飾が施され、背中を覆う大きな十字架が特徴だ。鎧の下には、同様のデザインの黒い服を着ている。腕は金属製のガントレットで覆われており、また', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/86699-oRLKbh6x7ijB.jpg', '9月6日', 'AB', '井上麻里奈', NULL, 86699, 'SUPPORTING', 497) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021482', 'AN1937', 'ジール', 'ギーラの弟', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n131574-c4qny7oco8L3.jpg', '2月27日', NULL, '中島唯', NULL, 131574, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021483', 'AN1937', 'チャンドラー', 'チャンドラーは、デーモン一族の中で最も位の高い悪魔であり、メリオダスの元師匠でもある。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b199213-aTYBMryXXTlv.jpg', NULL, NULL, '藤真秀', NULL, 199213, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021484', 'AN1937', 'グリアモール', 'グリアモールは、何世代にもわたりリヨネッセ王国に仕えてきた聖騎士の家系に生まれた聖騎士である。彼はヴェロニカの護衛であり、彼女に対して絶対的な忠誠を尽くしている。  グリアモールは、一般市民の少なくとも2倍の身長を持つ、非常に背が高く筋肉質な人物で、肩までの長さの灰色の髪をしている。その装いは、単一の尖ったヘルメットと全身を覆う脚部鎧で構成されており、上半身は裸だが、胸には2本のストラップで固定された謎めいた金属板が巻かれている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n86703-wzusHoQ4ZFQN.jpg', '11月10日', 'A', '櫻井孝宏', NULL, 86703, 'SUPPORTING', 69) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021485', 'AN1937', 'バルトラ・リオネス', 'リオネスの第11代王であり、エリザベスの父。七つの大罪が偉大なる聖騎士ザラトラスの殺害の罪を着せられた後、彼は捕らえられた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n131565-U0CcO6YR8w3T.jpg', '11月11日', NULL, '西凜太朗', NULL, 131565, 'SUPPORTING', 25) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021486', 'AN1937', 'ナージャ・リオネス', 'ナージャ・リオネスは、リオネス王国の王女であり、第10代国王の娘で、バルトラとデンゼル・リオネスの姉であった。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b199218-YMDeJKDVSkOB.jpg', NULL, NULL, '麻倉もも', NULL, 199218, 'SUPPORTING', 16) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021487', 'AN1937', 'タルミエル', 'Tarmiel「タルミエル」 is one of the Four Archangels of the Goddess Clan. He is also one of the commanders of Stigma alongside Ludociel and Sariel.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b132240-UZdgZ7uqga1M.jpg', NULL, NULL, '鶴岡聡', NULL, 132240, 'SUPPORTING', 17) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021488', 'AN1937', 'ゴウセル', 'ゴウセルは、強力な魔法使いであり、悪魔族のエリートの一員として、悪魔王の直属の配下で「十戒の無私」を務めている。', 460, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b199217-4JC4Nkryvql3.jpg', '4月15日', 'B', '多田野曜平 ', NULL, 199217, 'SUPPORTING', 32) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021489', 'AN1937', 'ギーラ', 'ギーラは、死者の都へ入り、そこに潜んでいた「七つの大罪」を討つために、自らを死の淵に追い込んだ聖騎士である。彼女はスリムな体型の若い女性で、長い黒髪を持ち、目は閉じているかのように描かれている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n86665-ZbYVIjmbyfl9.jpg', '12月6日', 'A', '伊瀬茉莉也', NULL, 86665, 'SUPPORTING', 246) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021490', 'AN1937', 'ベロニカ・リオネス', 'ヴェロニカはブリタニア王国の第二王女である。第一王女マーガレットの妹であり、養妹である第三王女エリザベスの姉にあたる。ボーイッシュな外見で、短めの明るい色の髪とほっそりとした体つきをしている。おしゃれな毛皮のコート、騎士風の衣装、ベルト、そしてロングブーツを身につけている。   彼女は「おてんば娘」と評されており、子供の頃は男の子たちと剣で遊ぶのが好きでよくそうしていたため、そのたびに父親に叱られていたという。ホル', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/86691-juwtWAV3MumS.png', '5月22日', NULL, '金元寿子', NULL, 86691, 'SUPPORTING', 73) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021491', 'AN1937', 'オルロンディ', 'オルロンディは吸血鬼であり、吸血鬼一族の王族の一員である。彼は12年前、一族がエディンバラ王国を支配していた時期に、吸血鬼の王に仕えていた。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b199219-zkk9DQPjqyLa.jpg', NULL, NULL, '小牧未侑', NULL, 199219, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021492', 'AN1938', 'ローラ・メトラーゼ', '種族：人間　オーディンギルドの受付係。ローラは、契約によりノワールが専属で頼りにしている人物であり、ルナの親友でもある。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b187863-z0yfx3usR0U4.png', NULL, NULL, '大久保瑠美', NULL, 187863, 'MAIN', 272) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021493', 'AN1938', 'ノル・スタルジア', '種族：人間　本作の主人公。貴族の中でも最下位の階級であるバロネットの息子であり、エマの幼なじみである。職を失ったものの、冒険者となり、ヒーローアカデミーへの入学試験に合格することを目指している。 彼は、「終わりのないダンジョン」に閉じ込められた師匠であるオリヴィア・サーヴァントから、多くの新しいスキルや能力を習得した。ノワールは、普段は真面目だが、時折毒舌になることもある神々しい青年である。神々しい外見とバロネットという身分ゆえに、ノワールは……', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b187865-i9mgeXbg2Z3C.png', NULL, NULL, '逢坂良太', NULL, 187865, 'MAIN', 138) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021494', 'AN1938', 'オリヴィア・サーヴァント', '種族：人間＋　オリビアはSクラスの冒険者で、200年前に「果てなきダンジョン」の第2フロアでモンスターを倒した後、罠にかかり逮捕された。 その後、200年を経てノワールに発見され、彼女を後継者に選び、指導や助言を始めるようになった。オリビアはエネルギッシュで、強力な力を持つ。', 200, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b187862-Fy2i8gnXpjoz.png', NULL, NULL, '堀江由衣', NULL, 187862, 'MAIN', 391) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021495', 'AN1938', 'エマ・ブライトネス', '種族：人間　男爵家の令嬢であり、ノワールの幼なじみ。短剣を使った近接戦闘の達人である。誰に対しても平等に接する優しい心を持ち、異性から絶大な人気を博している。ノワールを慕っており、彼と共にヒーローアカデミーに入学した。', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b187864-LVrU7FAi3UBi.png', NULL, NULL, '富田美憂', NULL, 187864, 'MAIN', 462) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021496', 'AN1938', 'ルナ・ヒーラー', '種族：ハーフエルフ　ある教会の聖職者であるルナは、人々の悩みを聞きながら治癒の術を施すことから聖人として崇められているが、その能力を使い続けることが、母親のように早すぎる死を招くのではないかと恐れている。 ルナはローラの親友であり、ソロの冒険者だ。ルナは、人々を救い、笑顔にすることこそが自分の使命だと確信している。普段は極めて威厳のある人物だが、意識を失った際に本音を呟くとき、奇妙な表情を浮かべることがある。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b201421-fqhzbL4M4bPi.png', NULL, NULL, '鬼頭明里', NULL, 201421, 'MAIN', 339) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021497', 'AN1938', 'マリア・フィアナ・アルバート', '種族：人間　マリアはホセ・アルバート公爵の次女である。マリアは、自分より身分の低い貴族たちを軽んじることのない、非常に気品のある人物だ。かつて、彼女の先祖が強力な魔法使いを打ち負かした際、その魔法使いがかけられた呪いにより、彼女は「16歳の死の呪い」を背負って生まれた。 この「呪われたスキル」は、決まった周期で激しい痛みの波が体を襲い、16歳の誕生日に使用者を死に至らしめる。マリアは幼い頃からその症状が現れていた。', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b205362-1vjnnHbSA7vL.png', NULL, NULL, '工藤夕希', NULL, 205362, 'SUPPORTING', 73) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021498', 'AN1938', 'ギルドマスター', '背が高く、威圧感のある男。ノワールは初めてオーディンギルドを訪れた際、彼と出会った。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b208529-bpm3BqLXXkh2.png', NULL, NULL, '中島卓也', NULL, 208529, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021499', 'AN1938', 'レイラの党首', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b224919-oXzpqoRKAZnW.jpg', NULL, NULL, '中島卓也', NULL, 224919, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021500', 'AN1938', 'アマネ', '彼女はマリアのボディーガードだ。マリアがヒーローアカデミーの入学試験を受けることを決めた際、アマネも自ら志願して受験した。マリアと同様、彼女もヒーローアカデミーのSクラスの生徒である。マリアに対して非常に忠実だ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b205363-emrrljuq5rrZ.png', NULL, NULL, '内村史子', NULL, 205363, 'SUPPORTING', 28) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021501', 'AN1938', 'ドリアード', 'ドーリーは、第7フロアの偉大な木です。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b209662-xtneblG4maVG.png', NULL, NULL, '春村奈々', NULL, 209662, 'SUPPORTING', 41) ON CONFLICT DO NOTHING;
