INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021505', 'AN1938', 'レイラ・オバーロック', '種族：人間　レベル：148　スキル：ボクシング（A級）、キックボクシング（B級）、白兵戦（B級）、ストーンスキン、ステルスステップ、デーモンフィスト　王国最大のギルド「ラーム」に所属する冒険者。', 16, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b210877-MKGRBSLlzqhs.png', NULL, NULL, '船戸ゆり絵', NULL, 210877, 'SUPPORTING', 55) ON CONFLICT DO NOTHING;
