INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021509', 'AN1938', 'アリス・スタルジア', '種族：人間　ノワールの妹であるにもかかわらず、彼に対して非常に独占欲が強く、彼を守ろうとする。アリスは異性から大人気だが、興味があるのはノワールだけであり、兄コンプレックスを抱いている。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b201420-zunmk2vh5qnQ.png', NULL, NULL, '長野佑紀', NULL, 201420, 'SUPPORTING', 201) ON CONFLICT DO NOTHING;
