INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021513', 'AN1938', 'マイク・ケントール', 'マイクはケントール子爵家の次男である。彼は何度もエマにアプローチしたが、彼女はいつも断っていた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b223112-etkVZhmJPlml.png', NULL, NULL, '山本龍二', NULL, 223112, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021514', 'AN1938', 'レノア・ブルードン', '種族：人間　彼女はブラドン伯爵の娘であり、その貴族の位は「コンテ」という称号である。ノワールは「ヒーロー・スクール」のオーディションでレノアと出会い、仲間になった。レノアは高慢な性格で、ノワールが男爵級の貴族の出身であるという理由だけで、彼に対して冷たく振る舞う。 しかし、ノワールの卓越した実力を知ると、彼女は彼を尊敬するようになる。', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b203671-vtEd3QX3YoMm.png', NULL, NULL, '北守さいか', NULL, 203671, 'SUPPORTING', 25) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021515', 'AN1938', 'バシェル', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b207991-AyOKn1V0WwsK.png', NULL, NULL, '田丸篤志', NULL, 207991, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021516', 'AN1938', 'ファン・ベルトルタ', 'ファンと彼女の兄は、「ファントム」として知られる泥棒コンビだ。', 28, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b223113-4mESNqhL3BBP.png', NULL, NULL, NULL, NULL, 223113, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021517', 'AN1938', 'エルナ・ストーングス', '種族：人間　エルナは7歳から24歳まで傭兵として活動していたが、ある事情により、昨年からヒーローアカデミーの教師となった。彼女はSクラスの生徒たちを指導しており、ノワールの担任でもある。 エルナは生徒に対して非常に厳しいが、男子生徒のやる気を引き出すために自身の色気を活用することも厭わず、生徒の顔の上に座ってご褒美を与えることさえある。', 24, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b205361-m0pOvPglq8Zo.png', NULL, NULL, '雨宮天', NULL, 205361, 'SUPPORTING', 152) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021518', 'AN1938', 'サラ・ロングローン', 'オーディンギルドの受付嬢であるサラは、その色気を使ってローラのギルドから冒険者を引き抜く癖があり、自分のランクを上げるためだけに、本来なら自分のギルドの冒険者への報酬として渡すべき贈り物で彼らを買収し、その冒険者の功績を横取りしている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b208528-LDF7be5N6DWK.png', NULL, NULL, '上田麗奈', NULL, 208528, 'SUPPORTING', 34) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021519', 'AN1938', 'トム・ベルトルタ', 'トムと彼の妹は、「ファントム」として知られる泥棒コンビだ。', 28, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b223115-fYYQZw8ss5aT.png', NULL, NULL, '大泊貴揮', NULL, 223115, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021520', 'AN1939', '晶', '種族：雪ケモノ　晶は、モン・イワキの雪の村に住むシロナの56番目の子供である。現在はケモノ事務所の職員として働いている。 晶は、とても元気で親しみやすい性格だが、時折不器用な面もあり、仕事をきちんとやり遂げられないこともある。また、かわいいものが好きで、自分の気持ちやその時の様子を記念して、絶えず自撮りをしている姿が見られる。晶は体が非常に弱く、虫やその他の汚いものを見ると、すぐに嫌悪感を抱いたり怖がったりしてしまう。', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154750-mTYO7aACEOV4.jpg', '2月24日', NULL, '村瀬歩', 159, 154750, 'MAIN', 432) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021521', 'AN1939', '隠神鼓八千', '種族：ベカデヌキ　オカルト専門の探偵。イヌガミは東京で「ケモノ探偵事務所」を経営している。カバネと出会った後、彼が両親を探すのを手伝うために、彼を連れて行くことにした。 犬神は争いを好まず、穏やかな性格で、カバネたちを気さくに付き添うほど親切だ。子供たちの世話も得意で、それぞれの事情に応じて手助けも惜しまない。探偵事務所の所長として、事件の解決や仕事を確実にやり遂げるのが得意である。', 36, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154747-onCg5tNXWVkS.png', '9月1日', NULL, '諏訪部順一', 180, 154747, 'MAIN', 275) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021522', 'AN1939', '日下夏羽', '種族：半人間・半ゴーレム　能力：　カバネは幼い頃から、姉であるカバネの母親への恩返しの意味で、叔母に育てられてきた。 それ以来、カバネは「ディア・ビレッジ」で叔母の日下夫人と従兄弟の弥太郎と共に暮らし、自身の体臭のせいで人混みには近づけない仕事を与えられていた。 カバネは、放任的な育て方のせいで感情表現が乏しい。返答はぶっきらぼうで冷淡であり、物事に対して鈍感で無知だと見なされることもある。', 13, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154749-SmkAurcWuzLI.png', '6月15日', NULL, '藤原夏海', 151, 154749, 'MAIN', 906) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021523', 'AN1939', '蓼丸織', '種族：半人半アラクネ　犬神探偵事務所に来るまで、そして叔父に引き取られる前は、群馬県金石郷で母親と暮らしていた。 志紀は当初、いじめっ子のような印象を与える。カバネより1歳年上であることを権威として振りかざし、二人ともハーフだから友達ではないと告げる。しかし、これは単なる見せかけに過ぎないことが明らかになる。カバネがピザを食べたことがないことに驚きを見せたり、カバネが初めてピザを食べようとして苦労した様子を見て笑ったりするからだ。', 14, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154751-2KiPCiI7G431.png', '11月10日', NULL, '花江夏樹', 163, 154751, 'MAIN', 394) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021524', 'AN1939', 'ミハイ フロレスク', '種族：ヴァンパイア　犬神探偵事務所の所属。ミハイはルーマニア出身の、数百年生きているヴァンパイアのケモノである。その長い生涯を通じて、彼は数多くの分野でプロ並みの専門知識と技能を身につけたようで、もはややるべきことが尽きてしまったほどだった。 かつて、彼は隠神鼓八千と知り合った。ミハイが人生に幻滅し始めていた頃、隠神は彼に日本へ来て自分の探偵事務所で働くよう依頼し、そこで彼は', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154759-xQlDWr0RXBev.png', '10月17日', NULL, '小野大輔', 176, 154759, 'SUPPORTING', 375) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021525', 'AN1939', '山蜘蛛之仔組', '「山蜘蛛の仔組」は、シキと蓼丸綾の母親である。（出典：怪物事変 Fandom）', 34, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b235181-Zs8PKv2yObDG.png', '1月18日', NULL, '久川綾', 168, 235181, 'SUPPORTING', 17) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021526', 'AN1939', '紺', '種族：キツネ　紺はかつて飯生妖子の配下として働いていた。紺は稲荷を崇拝しており、彼女の注目と承認を切望している。一見無感情に見えるが、紺は母親のように慕う稲荷を喜ばせようと最善を尽くしている。稲荷を侮辱する者に対しては激しく怒りを露わにする。 紺は任務に失敗した後、イナリに無視され、見捨てられた。紺はそれほど頭が良いわけでもなく、感情の起伏も激しい。何よりも「神娘」になりたいという願いが強いため、その役割を果たすためなら何でもする。もし何かあれば', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154755-ffZEEdfYjOgv.png', '11月1日', NULL, '花守ゆみり', 162, 154755, 'SUPPORTING', 675) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021527', 'AN1939', '蓼丸昭夫', '蓼丸昭夫は、ケモノを専門とする人間の学者であり、蓼丸織の叔父である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b235183-cEmlPp2MTsVN.jpg', NULL, NULL, '石田彰', NULL, 235183, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021528', 'AN1939', '蚊賀レイカ', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b208696-MF1hhSc5SVnD.png', NULL, NULL, '南條愛乃', NULL, 208696, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021529', 'AN1939', '日下', 'カバネの母親が彼をカバネの叔母に預けて去った後、叔母は自分の息子・弥太郎と共にカバネを育てていた。カバネの正体を知り、動物の死が増加する中、恐怖に駆られた叔母は、カバネを殺すために隠神鼓八千を雇った。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b243784-ha4eSZjfMTwr.png', NULL, NULL, 'のがみ あいこ', NULL, 243784, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021530', 'AN1939', '結', '種族：スノーケモノ　結は晶の双子の兄である。', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154756-kk6r5JsISRXg.png', '2月24日', NULL, '石川界人', 171, 154756, 'SUPPORTING', 129) ON CONFLICT DO NOTHING;
