INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021532', 'AN1939', '弥太郎', '日下夏羽のコサインと、日下夫人の息子。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b243785-ZOHKMLSWlNUZ.png', NULL, NULL, '金元寿子', NULL, 243785, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021533', 'AN1939', '蚊賀モモカ', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b221438-B9jZCEpErF9U.png', NULL, NULL, '楠木ともり', NULL, 221438, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021534', 'AN1939', '飯生妖子', '種族：キツネ　警視庁のトップ。物語の序盤で登場した際、彼女とイヌガミは互いに特に好意を抱いてはいなかったものの、同盟関係にあった。 彼女がカバネの「生命計算式」を何度も盗もうとしたことや、犬神の一味が彼女の人間肉会社を襲撃したことをきっかけに、二人は敵対関係となり、互いに憎み合うようになった。イナリは利己的で残酷であり、幻術を使って警視庁を操り、自分の思惑に合わなくなった者は誰であれ切り捨てる。オツィにて', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154758-rQVJUS2TI3fy.png', NULL, NULL, '花澤香菜', NULL, 154758, 'SUPPORTING', 54) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021535', 'AN1939', 'まお', '人間を魅了して猫に変え、餌を持ってこさせる猫又。  まおはわがままで、その力を使って人間を魅了し、猫に変えて餌を運ばせている。ある人間が自分を愛していると知ったとき、彼女は彼のペットとして暮らし、彼に世話をしてもらうことに決めた。そうすれば、のんびりとした生活を送れるからだ。（出典：怪物事変 Fandom）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b232796-JNk1HwEm1z07.png', NULL, NULL, '伊瀬茉莉也', NULL, 232796, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021536', 'AN1939', '野分火丸', '種族：キツネ　能力：複製：ノビマルは自身の分身を多数生み出し、敵を混乱させることができる。変身：ノビマルは子供の姿から大人の姿へと姿を変えることができる。飯生妖子の配下であり、特別捜査班のリーダーでもある。 礼儀正しく、謎めいた性格の持ち主である。イナリの命令には常にためらうことなく従う。一方で、時に冷酷で残忍な一面を見せ、自らのpで敵を殲滅することもある。', 13, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154753-eXa6KwdXMsYo.png', '5月30日', NULL, '下野紘', 179, 154753, 'SUPPORTING', 219) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021537', 'AN1939', '夜野', '「まお」という名の猫またに恋をした人間。まおに恋をした彼は、彼女と一緒にいられるなら、人間としての生活を捨てて猫になる覚悟さえしていた。 そして、まおが猫であることを知っても、彼女への想いは変わらなかった。   (出典：怪物事変 Fandom)', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b232797-m21dqpWDE5WY.png', NULL, NULL, '岸尾だいすけ', NULL, 232797, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021538', 'AN1939', '蓼丸綾', '種族：ハーフ・アラクネ　蓼丸織の年下の異母妹であり、「黄金の糸」であることが明らかになった。初登場時、綾は周囲の人々に対して内気で無邪気な印象を与えていた。しかし、すぐに彼女は、特に志紀に対しては、かなり自信家であり、わがままで、生意気な一面を持っていることが明らかになる。 周囲からは「うっとうしい」と評されることもあるが、アヤは心優しく、自分の能力を必要とする人々を助けようとよく努める。アヤは、蓼丸昭夫が「黄金の糸」を作り出すために繰り返した数々の実験の産物である。彼女は……', 8, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154757-wyLxS58ze1Hl.png', '11月22日', NULL, '本渡楓', 121, 154757, 'SUPPORTING', 87) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021539', 'AN1939', '御花', '御花は、隠神鼓八千の友人であり、スペシャリストである。彼女は東京で「御花病院」を経営している。  （出典：怪物事変 Fandom）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b235180-r9oYAvkw5IJn.png', NULL, NULL, '谷育子', NULL, 235180, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021540', 'AN1940', 'ロイド・ベラドンナ', 'ロイドは、伝説の町クンルン出身の10代の少年で、王国の軍隊の兵士になるために故郷を離れた。彼の村では、一般的な仕事を「普通」と期待される水準でこなせない「弱虫」として知られている。 しかし、世界で最も危険な地域にあるこの町の基準は、信じられないほど歪んでおり、実のところ、外部の基準からすれば彼は恐ろしいほど強いのだ。彼は親切で寛大、人を助けようと熱心で、とても謙虚な性格だ。料理や掃除は得意だが、どうしても納得できないのは……', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b149052-THCNy80qHzTS.png', NULL, NULL, '花守ゆみり', NULL, 149052, 'MAIN', 192) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021541', 'AN1940', 'アルカ', 'クンルン村の村長。彼女は密かにロイドに想いを寄せており、彼の様子を確かめるために頻繁に首都へテレポートしている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b149048-VcqDMS9unYHK.png', NULL, NULL, '日岡なつみ', NULL, 149048, 'MAIN', 93) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021542', 'AN1940', 'マリー', 'アザミの首都、イーストサイドのスラム街に住む10代の魔女。住民たちにポーションを売っているが、イーストサイドの貧困のため、通常は金銭よりも情報を対価として受け取っている。彼女はアルカの元教え子である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b149050-ykJSZM1D3UjI.jpg', NULL, NULL, '茅野愛衣', NULL, 149050, 'MAIN', 119) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021543', 'AN1940', 'リホ・フラビン', '片腕の傭兵。左腕は強力な機械義肢に置き換えられている。彼女は、軍事教官メルトファン・デクストロとの取り決めの一環として、前科を抹消してもらう見返りに軍に入隊した。常に他人を自分の利益のために利用する機会を虎視眈々と狙っている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b149051-6QWDomAIXd3j.png', NULL, NULL, '津田美波', NULL, 149051, 'MAIN', 98) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021544', 'AN1940', 'セレン・ヘムアエン', '「呪われたベルトの王女」としても知られる。貴族の娘であるセレンは、幼い頃、頭部にきつく巻きつき、いかなる既知の魔法でも外すことができない魔法のベルトによって呪われてしまった。 この出来事は貴族社会にスキャンダルと恥をもたらした。彼女は、「ベルトよりも強い力があればそれを打ち破れる」という説を信じ、必死に力を磨き、さらにその力を高めるために首都へ赴き、軍に入隊した。ロイドとの初対面で彼が呪いを解いたとき、彼女は強力な', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b149053-1obbpsNHjPac.png', NULL, NULL, '朝日奈丸佳', NULL, 149053, 'MAIN', 125) ON CONFLICT DO NOTHING;
