INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021555', 'AN1940', 'ユーグ', 'ユーグは、クンルンと「最後のダンジョン」を守る使命を帯びたドワーフ王族の一員である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b260279-6BepCktMcxw3.png', NULL, NULL, '三瓶由布子', NULL, 260279, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
