INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021564', 'AN1941', '白血球 U-1146番', '彼は白血球の一種、具体的には好中球であり、好中球部隊に所属している。他の好中球の仲間たちと共に、血管内をパトロールし、細菌やウイルスといった侵入してきた異物を排除する任務を担っている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b126981-K1cB7bUIm6Mj.png', NULL, NULL, '前野智昭', NULL, 126981, 'MAIN', 1596) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021565', 'AN1941', '赤血球', '方向音痴な、新米赤血球。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b126975-Lqj6mlIEBaSA.png', NULL, NULL, '花澤香菜', NULL, 126975, 'MAIN', 885) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021566', 'AN1941', '一般細胞', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b206178-RYz8uugHHXqq.png', NULL, NULL, '小林裕介', NULL, 206178, 'MAIN', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021567', 'AN1941', '樹状細胞', '樹状細胞の役割は、体内に侵入した細菌や、ウイルスに感染した細胞の断片を抗原として提示し、他の免疫細胞にその情報を伝えることです。その名の通り、樹状細胞には突起があります。樹状細胞はナイーブT細胞を活性化させることができます。<br><br>(出典：Cells at Work Wiki)', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n132621-gbUdEusdLC7v.jpg', NULL, NULL, '岡本信彦', NULL, 132621, 'SUPPORTING', 131) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021568', 'AN1941', '乳酸菌（アカ）', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b203899-TejibIDDBLZn.png', NULL, NULL, '高橋李依', NULL, 203899, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021569', 'AN1941', '好塩基球', '正体不明で詩的な雰囲気を持つキャラクター。本業は不明だが、寄生感染が発生した際に現れ、展開される出来事について謎めいたコメントを述べる。<br><br>(出典：『細胞大作戦』ウィキ)', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n132622-mpB83dOqnbNv.jpg', NULL, NULL, '杉田智和', NULL, 132622, 'SUPPORTING', 31) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021570', 'AN1941', 'M細胞', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b206854-NEeX2J1kCUHh.png', NULL, NULL, '速水奨', NULL, 206854, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021571', 'AN1941', 'ヘルパーT細胞', '外来の侵入者に対処するための戦略や行動方針を決定するT細胞の一種。キラーT細胞の最高司令官であり、知的な性格の持ち主である。キラーT細胞とは、共にT細胞の訓練を受けてきたにもかかわらず、あまり仲が良くない<br><br>(出典：『細胞大作戦』ウィキ)', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n132618-wcKdTgNhATos.jpg', NULL, NULL, '櫻井孝宏', NULL, 132618, 'SUPPORTING', 44) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021572', 'AN1941', '乳酸菌（パンダ）', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b203900-bB2UfFtFEUNx.png', NULL, NULL, '藤原夏海', NULL, 203900, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
