INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021575', 'AN1941', 'キラーT細胞', '病原体を殲滅するために、自身の分隊を率いるT細胞。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/127071-nBPvVFLiJ0N0.jpg', NULL, NULL, '小野大輔', NULL, 127071, 'SUPPORTING', 162) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021576', 'AN1941', '記憶細胞', '記憶細胞とは、病原体の記憶を保持するリンパ球のことです。これらは、同じ細菌やウイルスによる二次感染に備えています。<br><br>(出典：『セルズ・アット・ワーク』ウィキ)', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n132617-U1sBIet9OFj1.jpg', NULL, NULL, '中村悠一', NULL, 132617, 'SUPPORTING', 28) ON CONFLICT DO NOTHING;
