INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021579', 'AN1941', 'きょろちゃん', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b207869-XHDdQwf0YuCX.png', NULL, NULL, '森永千才', NULL, 207869, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021580', 'AN1941', '血小板', '血小板は、血小板課に所属する細胞の一種です。彼女と同僚たちは、人体の傷を修復し、血栓を形成する役割を担っています。血小板の実際の細胞サイズを考慮し、彼らは子供として描かれています。 血小板は、腰までの長さのキャラメル色のブロンドの髪と茶色の目をした、小さくて愛らしい細胞です。彼女は血小板の制服を着ており、いつも同僚たちと一緒に働いている姿が見られます。血小板は、体の治癒において重要な役割を果たしています。しかし、それらは……に対しては無力です。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/127417-mK2MxesD0nrb.jpg', NULL, NULL, '長縄まりあ', NULL, 127417, 'SUPPORTING', 660) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021581', 'AN1941', '制御性T細胞', '制御性T細胞は白血球の一種であり、具体的にはTリンパ球です。制御性T細胞は、すべてのT細胞の活動を調節し、それらが自身の体の細胞を攻撃しないようにします。<br><br>(出典：Cells at Work Wiki)', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n132624-jUMeHfc3PDwM.jpg', NULL, NULL, '早見沙織', NULL, 132624, 'SUPPORTING', 31) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021582', 'AN1941', '赤血球 NT4201', '彼女は新米の赤血球で、AE3803の後輩である。AA5100によってAE3803に紹介された。実務経験は乏しいものの、細胞や人体に関する知識は豊富だ。性格の違いから、当初はAE3803とあまりうまくやっていけなかった。 当初、先輩をあまり高く評価していなかったものの、NT4201は彼女に対して礼儀正しく、丁寧な態度を保ち続けていた。しかし、体が大出血を起こし、その生存自体が危ぶまれる事態となったとき、状況は一変した。NT4201はパニックに陥り、すべてが終わったと思い込んで諦めてしまった。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n132619-Wl3KGURlTVv3.jpg', NULL, NULL, '石川由依', NULL, 132619, 'SUPPORTING', 27) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021583', 'AN1941', '毛母細胞・長老', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b205238-1d4hgXgObjlI.png', NULL, NULL, '麦人', NULL, 205238, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021584', 'AN1941', 'そとはねちゃん', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b207870-lZKb28gTS7jk.png', NULL, NULL, '立花芽恵夢', NULL, 207870, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021585', 'AN1941', 'マクロファ―ジ', '彼女の種族は、体内で保育園の先生からプロの殺し屋まで、さまざまな役割を担っている。 そのため、彼女が担っている役割に応じて、さまざまな顔や性格を見せます。本来、マクロファージは謙虚で気さくな細胞であり、丁寧な口調で話す母のような存在として現れます。しかし、侵入者に対しては、共感や慈悲を示すことなく、容赦なく殺すこともできます。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/127070-CKX6o5OFrf3R.jpg', NULL, NULL, '井上喜久子', NULL, 127070, 'SUPPORTING', 292) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021586', 'AN1941', 'がん細胞', '彼が生来変異体として生まれたのは、彼を形成した正常な細胞がDNAの複製過程でエラーを起こしたためである。この変異により、彼は正常な細胞とは異なる外観を呈し、制御不能に増殖し、命に関わる可能性のあるがんを引き起こす。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n132615-sTziS26CL1Z8.jpg', NULL, NULL, '石田彰', NULL, 132615, 'SUPPORTING', 195) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021587', 'AN1941', 'カンピロバクター', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b204439-j07hVPbGgKvO.png', NULL, NULL, '小林大紀', NULL, 204439, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021588', 'AN1941', 'ナチュラルキラー細胞', '彼女は白血球の一種で、具体的にはリンパ球（ナチュラルキラー細胞）です。組織から組織へと自由に移動しながら、ウイルスや感染した細胞を特定し、追跡し、破壊する役割を担っています。<br><br>(出典：Cells at Work Wiki)', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n132623-HVqCG0RzQGYj.jpg', NULL, NULL, '行成とあ', NULL, 132623, 'SUPPORTING', 111) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021589', 'AN1941', '赤血球 AA5100', '彼女は、血管内でかなりの実務経験を持つ年配の赤血球です。AE3803が戸惑ったり迷ったりしたときは、時々彼女に仕事のやり方を指導したり教えたりします。<br><br>(出典：『細胞大作戦』ウィキ)', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n132625-94PwntRqPU6C.jpg', NULL, NULL, '遠藤綾', NULL, 132625, 'SUPPORTING', 38) ON CONFLICT DO NOTHING;
