INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021595', 'AN1941', 'ピロリ菌', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b206179-b3jPccXzSZ5O.png', NULL, NULL, '福島潤', NULL, 206179, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021596', 'AN1941', 'マスト細胞', '彼女は白血球の一種で、具体的にはマスト細胞（マストサイトまたはラボサイト）です。 免疫系の一員として、彼女はヒスタミンやロイコトリエンなどの化学物質を放出し、それによってIgE（免疫グロブリンE、B細胞によって産生される抗体）の過剰産生を刺激する。<br><br>(出典：Cells at Work Wiki)', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n132613-hGzZMccvotLh.jpg', NULL, NULL, '川澄綾子', NULL, 132613, 'SUPPORTING', 28) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021597', 'AN1941', '乳酸菌（クロ）', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b203897-WCGYdgwIKWGg.png', NULL, NULL, '吉田有里', NULL, 203897, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021598', 'AN1941', '好酸球', '白血球の一種。全白血球のうちごくわずかな割合しか占めていないとされる。アレルギー反応や寄生虫感染症の際にその数が増加する。好酸球は能力は弱いものの、他の白血球と同様に貪食作用を持つ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/127041-ty1sUS3FPuh8.png', NULL, NULL, '市道真央', NULL, 127041, 'SUPPORTING', 107) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021599', 'AN1941', '白血球 U-4989', '彼は好中球部隊に所属する好中球であり、U-1146の親友であるほか、U-2001、U-2626、U-2048とも親しい間柄だ。 好中球として、彼の使命は体内に侵入した細菌を破壊することである。<br><br>(出典：『セルズ・アット・ワーク』ウィキ)', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n132614-40i6AcHl2dmS.jpg', NULL, NULL, '熊谷健太郎', NULL, 132614, 'SUPPORTING', 43) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021600', 'AN1942', '各務原修一朗', 'なでしこと各務原桜の父親。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n131525-I66SF96huXuX.png', NULL, NULL, '大畑伸太郎', NULL, 131525, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021601', 'AN1942', '鳥羽涼子', 'ミナミの姉。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b210875-lGJAHYgfn7kS.png', NULL, NULL, '國立幸', NULL, 210875, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021602', 'AN1942', '各務原静花', 'なでしこと各務原桜の母親。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n131522-QF6Fq6UV3VLn.png', NULL, NULL, '山本希望', NULL, 131522, 'SUPPORTING', 23) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021603', 'AN1942', '志摩渉', 'リンの父親。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b169005-wk7MTHsfb0hU.png', NULL, NULL, '櫻井孝宏', NULL, 169005, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021604', 'AN1942', '菊川昴', 'おしゃべりな登山家', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b321241-QqziR2e8wXIC.png', NULL, NULL, '川澄綾子', NULL, 321241, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021605', 'AN1943', 'シロエ', '種族：ハーフアルフ　クラス：エンチャンター　シリーズの主人公であるシロエは、黙示録が起こる前は工学の大学院生だった。中学生の頃から『エルダー・テイル』をプレイしていたため、ゲーム内でも最も経験豊富で腕の立つ冒険者の一人である。 また、卓越した戦術家としても悪名高い。彼は「デバウチェリー・ティー・パーティー」の戦略家として知られており、この非公式なグループはゲーム内で最も難易度の高いレイドのいくつかを攻略することに成功した。彼は直継とはあの頃から知り合いである。', 23, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b81367-nE2CB4jLVPeu.png', '11月23日', NULL, '寺島拓篤', 177, 81367, 'MAIN', 1366) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021606', 'AN1943', 'アカツキ', '種族：人間　クラス：アサシン　サブクラス：トラッカー　黙示録の直後にシロエと直継に出会った、熟練のレベル90の冒険者。シロエから外見変化のポーション（これにより、キャラクターが実在の自分に近い姿になった）を授かった。それ以前は、男性キャラクターとしてプレイしていた。 シロエの寛大さに深く感謝しており、彼を「師匠」と呼んでいる。アカツキは自分の身長にかなりコンプレックスを抱いており、子供と間違えられることを嫌っている（実際には……', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n81369-0vKZMoOH3NZT.jpg', '7月7日', NULL, '加藤英美里', NULL, 81369, 'MAIN', 1358) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021607', 'AN1943', '直継', '種族：人間　クラス：ガーディアン　サブクラス：国境警備隊　直継はシロエの友人である。彼は、すべての男は公然とであれ密かにであれ、変態だと信じている。そのため、彼は自らを「公然の変態」だと自負しており、女性に対する変態的な考えを誰にでも気兼ねなく語っている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/81371-03gxHpwaBbVL.jpg', NULL, NULL, '前野智昭', NULL, 81371, 'MAIN', 165) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021608', 'AN1943', 'にゃん太', '種族：猫人　クラス：スワッシュバックラー　サブクラス：シェフ　にゃん太は、かつて「デバウチェリー・ティー・パーティー」のメンバーでもあったため、シロエの古くからの友人である。 セララがすすきのの街に閉じ込められていた際、彼女を守ったのが彼だ。自らを「紳士」と称し、武器は両手に1本ずつ持つラピエを好んで使う。サブクラスのおかげで、本格的な味の料理を作ることができる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/81373-oG4Bngt03jKk.jpg', '2月22日', NULL, '中田譲治', NULL, 81373, 'MAIN', 388) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021609', 'AN1943', 'セララ', '種族：人間　クラス：ドルイド　サブクラス：メイド　ギルド：クレセント・モン・アライアンス　彼女は窮地に陥った際、にゃん太に助けられ、ギルドに救援を要請した。しかし、ギルドが現場に到着するまでには時間がかかりすぎるため、代わりにシロエとその仲間たちが向かうことになった。 彼女は気を紛らわせるために掃除をする習慣がつき、その結果、メイドレベルが無駄に上がってしまう。『エルダー・テイル』において彼女のクラスは回復職の一つだが、レベルが低いため、高レベルプレイヤーほど素早く回復させることはできない。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/88378.jpg', '3月1日', NULL, '久野美咲', NULL, 88378, 'SUPPORTING', 68) ON CONFLICT DO NOTHING;
