INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021611', 'AN1943', 'リ=ガン', '種族：エルフ、大地の民　クラス：魔法学者　リ＝ガンはミラーレイクの賢者であり、魔法、とりわけ「ワールドクラス・マジック」の研究に情熱を注いでいる。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b194021-alJjSyEFRuGN.jpg', NULL, NULL, '多田野曜平 ', NULL, 194021, 'SUPPORTING', 17) ON CONFLICT DO NOTHING;
