INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021613', 'AN1943', 'トウヤ', '種族：人間
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021614', 'AN1943', 'ウィリアム＝マサチューセッツ', '種族：エルフ　クラス：アサシン　レベル：90　サブクラス：ハンター　HP：8303　MP：12088　所属：シルバーソード　 ウィリアム＝マサチューセッツ（別名「ミステリー・アイズ・ウィリアム」）は、ギルド「シルバーソード」のギルドマスターである。 彼は「円卓同盟」への加盟を打診されたが、その目的は自身や自身のギルドとは無関係であるとして、これを断った。   (出典：Log Horizon Wikia)', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b88397-xBp3RKNnaHmn.png', NULL, NULL, '中村悠一', NULL, 88397, 'SUPPORTING', 26) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021615', 'AN1943', '斎宮トウリ', 'トリは、ウェステランド帝国王朝の血筋を引くサイグ家の後継者であり、クニエの古代技術の一部を伝承している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b198850-eC0DkxogFD62.png', NULL, NULL, '河西健吾', NULL, 198850, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021616', 'AN1943', 'ウモト＝アルテ＝マルヴェス', '彼は聖帝国ウェステランドのエルフ貴族である「ハイロード」であり、同領土の商船隊の総帥と見なされている。彼は「スピリットシップ・イーグル」を指揮している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b257825-9D99yLa0Z9Y5.png', NULL, NULL, '青山穣', NULL, 257825, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
