INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021621', 'AN1943', 'マリエール', '種族：エルフ　クラス：クレリック　サブクラス：ウッドクラフター　ギルド：「クレセント・モン・アライアンス」　「クレセント・モン・アライアンス」のギルドマスター。出会う人すべてに、とりわけ直継に対しては、やけに親しげに接する。', 28, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/88376-OlBiSAYIY27B.jpg', NULL, NULL, '原由実', NULL, 88376, 'SUPPORTING', 133) ON CONFLICT DO NOTHING;
