INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021625', 'AN1943', 'ミノリ', '種族：人間　クラス：カンナギ　サブクラス：仕立て屋（元）；見習い', 14, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/88447.jpg', '9月18日', NULL, '田村奈央', NULL, 88447, 'SUPPORTING', 66) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021626', 'AN1943', 'エリッサ', 'エリッサは、コーウェン一族出身のレイネシアの侍女である。レイネシアの不興を買うこともしばしばだが、エリッサは、とりわけクラスティが関わっている場合、よく彼女のことに首を突っ込んでくる。（出典：Log Horizon Wiki）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b158247-Io1oFman6B7B.png', NULL, NULL, '葉山いくみ', NULL, 158247, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021627', 'AN1943', 'レリア=モフール', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200717-fyxwsnx0J6JE.png', NULL, NULL, '石見舞菜香', NULL, 200717, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021628', 'AN1943', 'ヘンリエッタ', '種族：人間　クラス：バード　サブクラス：会計士　ギルド：クレセント・モン・アライアンス　彼女はマリエールの直属の部下であり、かわいいものなら何でも大好きだ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/88377.jpg', '3月25日', NULL, '高垣彩陽', NULL, 88377, 'SUPPORTING', 84) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021629', 'AN1943', 'てとら', 'テトラは、MMORPG『エルダー・テイル』に閉じ込められたプレイヤーの一人である。実生活では男性だが、大災害発生時に女性の人間クレリック兼アイドルというキャラクターを使用していたため、ゲーム内に閉じ込められてしまった。とはいえ、彼女は新しい体に順応したようで、男性の体に戻りたいという意向は一切示していない。 彼女は自称「ギャラクシー・アイドル」であり、その肩書きにふさわしい装備も持っているが、歌そのものはあまり得意ではない。かつては「アビサル・シャフト」レイドパーティの一員として、ライト・インディグのメンバーとして活動していた。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/88628-H4GepPjX3NWy.jpg', NULL, NULL, '藤井ゆきよ', NULL, 88628, 'SUPPORTING', 108) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021630', 'AN1943', 'リーゼ', 'リーゼは、『エルダー・テイル』に登場するハーフ・アルヴのソーサラー兼ストラテジストであり、D.D.D.のメンバーである。彼女は、クラスティの副官を務める女性たち「ドライ・クラウエン」の一人である。 「オペレーション・キャプチャー」では、ヘンリエッタと共に「秋葉レイドパーティー」のリーダーの一人を務める。彼女のオーバースキルは「カイロン・タブレット」である。本名は相沢セリカ。（出典：Log Horizon Wiki）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158246-bgeyH67Of8TZ.png', '4月2日', NULL, '村川梨衣', NULL, 158246, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021631', 'AN1943', '濡羽', '濡羽は、プラント・ハイアデンのギルドマスターであり、エンチャンターでもある。シロエの同世代の人物だ。黙示録後の数ヶ月の間に、彼女は市内の主要な建造物、とりわけミナミの大聖堂を数棟購入し、事実上ミナミの支配者となった。 これらの重要な施設を掌握することで、彼女は冒険者たちを統制すると同時に、それらを利用してランダーの貴族たちへの影響力を拡大し、他では見られない独自の手段として、市の警備体制をも掌握している。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/88393.jpg', NULL, NULL, '斎藤千和', NULL, 88393, 'SUPPORTING', 37) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021632', 'AN1943', 'クラスティ', '種族：人間
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021633', 'AN1943', 'カナミ', 'カナミは、ヨーロッパに移住してヨーロッパサーバーで新しいアカウントを作成する前は、現在は解散した「Debauchery Tea Party」の元リーダーでした。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/88389.jpg', '8月20日', NULL, '井上麻里奈', NULL, 88389, 'SUPPORTING', 76) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021634', 'AN1943', 'カラシン', 'チャラシン（別名：ヨン・ボス・チャラシン）は、秋葉原の三大生産ギルドの一つである「ショッピング地区8」のギルドマスターである。彼は人間の召喚士兼商人であり、円卓同盟のメンバーでもある。彼のオーバースキルは「マルチライン」である。  チャラシンの本名は三上陽介で、広告代理店に勤務している。（出典：ログ・ホライズン Wiki）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158245-USHjjtc6nIDh.png', '2月14日', NULL, '岡本信彦', NULL, 158245, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
