INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021638', 'AN1943', 'ミチタカ', 'ミチタカは、MMORPG『エルダー・テイル』に閉じ込められたプレイヤーの一人である。彼のキャラクターは「人間・モンク兼鍛冶屋」で、秋葉原最大の生産ギルド「マリン・オーガニゼーション」（会員数2,500名）のリーダーを務めている。  現実世界では、彼は「ミチタカ・オイカワ」という名の課長級の会社員である。（出典：ログ・ホライズン Wiki）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158244-jPEkt3xLZfvV.png', '4月7日', NULL, '後藤ヒロキ', NULL, 158244, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021639', 'AN1943', 'ウッドストック＝Ｗ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b257823-gAFoLcTPPEW6.png', NULL, NULL, '白熊寛嗣', NULL, 257823, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021640', 'AN1944', '白血球 U-1196番 ', '彼女は任務に対して非常に強い決意を持っており、劣悪な労働環境や不当な扱いといった困難についても決して不満を口にしないが、それでも支援には感謝し、他の細胞たちに対して敬意を示している。彼女は、任務のために懸命に働く「英雄的なお姉さん」と評されている。 全体的に穏やかで思いやりのあるセルではあるが、自分自身を厳しく評価しすぎて過労になりがちな傾向がある。彼女は、遊び好きだが名前のない2人の好中球兵士や、AA2153と仲が良い。（出典：cel', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b156658-YWdJ91dceN5b.jpg', NULL, NULL, '日笠陽子', NULL, 156658, 'MAIN', 289) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021641', 'AN1944', '赤血球 AA2153', '新人として、彼は当初、肺へ向かう任務に胸を躍らせていたが、その途中でLDL、一酸化炭素、肺炎球菌に出くわしてしまった。彼は体を助けるために自分の役割を果たすことに尽力しているが、ひどい労働環境と、体の状態が改善されないことに深く落胆している。   (出典: cellsatwork.fandom.com)', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b156657-f0MI0VcYE6XC.jpg', NULL, NULL, '榎木淳弥', NULL, 156657, 'MAIN', 88) ON CONFLICT DO NOTHING;
