INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021654', 'AN1944', '赤血球 AC1677', 'AA2153の親しい友人である彼は、二人が活動するこの恐ろしい状況下で、新人として共にいくつかの困難に立ち向かってきた。友人とは異なり、彼は心を落ち着かせるためにこうした状況から逃げ出してしまうことがよくあるが、AA2153に励まされ、共に働き、前進し続けている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b202982-HQFJGzGR4NXt.png', NULL, NULL, 'KENN', NULL, 202982, 'SUPPORTING', 58) ON CONFLICT DO NOTHING;
