INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021662', 'AN1945', '紙越空魚', 'ソラウォは内気で内向的な性格で、普段は一人でいることを好み、人に煩わされたくないため、他の人とは距離を置くことが多い。 大学入学当初、友達を作ろうと数回のパーティーに参加した時期もあったが、結局そのペースについていけず、疲れ果ててしまったため、それ以降は一人でいることを選んだ。 無理に会話を強いられたり、初めて人と会ったりすると、彼女は動揺してしまったり、必要以上に話しすぎてしまったりしがちです。', 20, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b156050-TMfNnqr8WX9e.png', '5月5日', NULL, '花守ゆみり', NULL, 156050, 'MAIN', 250) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021663', 'AN1945', '仁科鳥子', '最初は謎めいた印象を与えていたものの、トリコはたいていの場合、明るく元気な性格として知られており、特に紙越空魚や小桜と一緒にいるときはその傾向が顕著で（小桜が「うっとうしい」と感じるほどだ）。 ソラウォと出会った際も親しみやすく、自己紹介を終えるとすぐに敬語をやめた。それ以来、ソラウォとは気楽に接しており、二人はきっと仲良くやっていけるだろうと確信していた。彼女は気楽な性格で、ソラウォと一緒に「オザサイド」を探索したり、お祝いをしたりする際も、遠慮することなく振る舞う。', 20, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b156049-0ZDmKK1PvF0W.png', '6月6日', NULL, '茅野愛衣', NULL, 156049, 'MAIN', 232) ON CONFLICT DO NOTHING;
