INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021666', 'AN1945', '瀬戸茜理', '瀬戸茜理は、紙越空魚が通う同じ大学の1年生で、空手を習っている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b194304-IxQr0B3GmjNq.png', NULL, NULL, '富田美憂', NULL, 194304, 'SUPPORTING', 15) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021667', 'AN1945', '姦姦蛇螺', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b252292-xnMrCuwjn4R4.png', NULL, NULL, '伊藤静', NULL, 252292, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021668', 'AN1945', '小桜', '小桜は、作谷公園の近くに住む隠遁生活を送る研究者であり、閏間冴月の大学時代の友人である。小桜はまた、ソラオとトリコが「あの世」から入手した品々を買い取り、後にDSラボに売り渡している。さらに、「あの世」に関するあらゆる事柄について、彼らのコンサルタントも務めている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b194305-Togywenx9ZwC.png', '11月11日', NULL, '日高里菜', NULL, 194305, 'SUPPORTING', 220) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021669', 'AN1945', '時空のおっさん', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b252290-drELNPBHHo2Z.png', NULL, NULL, '村瀬歩', NULL, 252290, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021670', 'AN1945', 'ウィル ドレイク', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b212305-oQaiMrAaBjyw.png', NULL, NULL, '諏訪部順一', NULL, 212305, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021671', 'AN1945', '閏間冴月', 'さつきはもともと小桜の友人であり、二人は同じ大学に通っていた。小桜に「共同研究」プロジェクトへの参加を誘う前から、彼女はすでに「オザサイド」の存在を知っていた。 さつきは数年前、DSラボに接触し、異世界への往復やUBLの遺物を持ち帰るための、より安全な方法があると主張していた。異世界に関する彼女の経験と知識を評価し、DSラボは彼女を研究員として迎え入れた。また、彼女は有望な人材の募集も行っていた。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b285957-au27vHUN1eSk.png', NULL, NULL, NULL, NULL, 285957, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021672', 'AN1945', '肋戸', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b212415-GiJrVjAtNUBr.png', NULL, NULL, '寺島拓篤', NULL, 212415, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021673', 'AN1945', '市川夏妃', '市川夏妃は、瀬戸茜理の幼なじみであり親友である。高校卒業後、夏妃は進学を断念し、実家の自動車整備工場で働くことを選んだ。ソラオとトリコに助けられたことをきっかけに、彼女はAP-1の改造に着手した。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b212416-oMn4UGYcTmpt.png', NULL, NULL, '島袋美由利', NULL, 212416, 'SUPPORTING', 70) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021674', 'AN1945', 'レイ バルカー', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b245651-2NLEchJJmSJg.png', NULL, NULL, '増元拓也', NULL, 245651, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021675', 'AN1946', '灰島公誓', '清音高校の1年生。男子バレーボール部のセッターを務めており、その卓越した技術から「天才セッター」と呼ばれている。 木吉は冷たく、感情を表に出さない印象を与えがちだが、黒羽祐仁など、大切に思う人に対しては優しい一面を見せることもある。バレーボールへの愛情が深く、所属するチームを勝利に導くために、並外れた意欲と集中力、そして強い決意を持っている。しかし、チームメイトを批評する際に示す容赦ない正直さは', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b175150-aJgge2CgW4iG.png', '1月7日', NULL, '小野賢章', NULL, 175150, 'MAIN', 112) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021676', 'AN1946', '黒羽祐仁', '黒羽祐仁は、清英高校の1年生で、男子バレーボール部のメンバーであり、アウトサイドヒッター兼エースを務めている。ユニは、ある程度明るい性格の少年だ。彼はバレーボールに情熱を注ぎ、チームのエースになりたいと願っている。 いとこの話によると、褒められると少し調子に乗ってしまうそうだ。ユニとハジマは、ハジマが東京へ引っ越す前は幼なじみだった。中学時代、ハジマが戻ってきて、ユニと再会する。', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b175149-lx0pEzWCdq6e.jpg', '9月30日', NULL, '榎木淳弥', 175, 175149, 'MAIN', 83) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021677', 'AN1946', '大隈優介', '大隈優介は、清英高校の2年生である。男子バレーボール部でミドルブロッカーを務めている。元ラグビー部員で、副主将の青木操に誘われてバレーボール部に入部した。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b175153-4rd0CNrBDMJ4.png', NULL, NULL, '木村昴', NULL, 175153, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
