INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021679', 'AN1946', '高杉潤五', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b203132-jTSrUxp9ygl6.png', NULL, NULL, '安部川賢治郎', NULL, 203132, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021680', 'AN1946', '棺野秋人', 'カンプ・アキトは、清英高校の2年生だ。男子バレーボール部でオポジットを務めており、日光に弱いことから、いつも長袖を着ている。物静かで、内気な性格のようで、どこか陰気なところがあり、いつもうつむいているように見える。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b175154-q3H12KZokSQM.png', '2月12日', NULL, '蒼井翔太', NULL, 175154, 'SUPPORTING', 49) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021681', 'AN1946', '戸倉工兵', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b203125-VEV1gjk9h3qM.png', NULL, NULL, '大河元気', NULL, 203125, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021682', 'AN1946', '黒羽頼道', 'ヨリミチは、ユニが赤ちゃんの頃から一緒に遊んでいました。幼い頃、彼は将棋の神になりたいと願い、よく祖父の家に遊びに行って指導を受けていました。また、灰島公誓やユニが幼い頃は、彼らの面倒を見たり一緒に遊んだりすることもありました。 年を重ねるにつれ、彼は不良となり、やがて親戚たちからは「救いようのない子」として見放されてしまったが、ユニは彼に「神の素質」があることを知っていたため、ヨリミチが金をかすめ取っていることを知りながらも、彼と付き合い続けた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b206206-N2M5CqgdYeyo.jpg', NULL, NULL, '濱野大輝', NULL, 206206, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021683', 'AN1946', '青木操', '誕生日：12月5日　青木操は清陰高校の3年生である。男子バレーボール部の副キャプテンを務めるほか、同校の生徒会の副会長も務めている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b175151-83z9l9Yf2DGx.png', '12月6日', NULL, '梅原裕一郎', 193, 175151, 'SUPPORTING', 31) ON CONFLICT DO NOTHING;
