INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021685', 'AN1946', '黒羽絃子', '黒羽絃子は、黒羽祐仁のいとこです。彼女はかつてモンシロ中学校に通っていました。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b206258-S3wwUAVWl0jp.jpg', NULL, NULL, '戸田めぐみ', NULL, 206258, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
