INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021688', 'AN1946', '一条ダニ', '一条ダニは清陰高校の監督である。福穂の監督によれば、彼は「神の監督」として知られている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b314045-DVx1jdUYTEHm.png', NULL, NULL, NULL, NULL, 314045, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
