INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021695', 'AN1946', '猿渡勇飛', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b203131-tEAPKxVTDoDp.png', NULL, NULL, '白石兼斗', NULL, 203131, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021696', 'AN1947', 'トウカイテイオー', '無敵で愛らしい！ 陽気で跳ね回るレーサー。 明るく元気いっぱいの「うま娘」で、レースの才能に恵まれている。彼女は長い間、生徒会長のシンボリルドルフに憧れており、その憧れこそが、ナンバーワンのレーサーになるための最大の原動力となっている。 ファンたちは、テイオの揺るぎない自信に魅了され、彼女の陽気な歩き方を「テイオ・ステップ」と親しみを込めて呼んでいる。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125300-mb168DIpLbWC.png', '4月20日', NULL, NULL, 150, 125300, 'MAIN', 2067) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021697', 'AN1947', 'メジロマックイーン', '名門メジロ一族の至宝。気品と落ち着きを兼ね備えた若き牝馬。競馬界の伝説的な一族に生まれたメジロマックイーンは、同世代の馬たちが羨む長距離のスペシャリストである。 その名門にふさわしい気品と品格を備え、先人である多くのメジロの競走馬たちと同様に、天皇賞での優勝を固く決意している。休日は、メジロ邸に住む多くの住人たちとアフタヌーンティーを楽しむのが好きだ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125309-nhewmUEllCnU.png', '4月3日', NULL, '大西沙織', 159, 125309, 'MAIN', 912) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021698', 'AN1947', '東条ハナ', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b200349-H9F8fl4kDnIq.png', NULL, NULL, '豊口めぐみ', NULL, 200349, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021699', 'AN1947', 'ナリタブライアン', '行動は言葉よりも雄弁だ！ 頑固で一匹狼な性格の持ち主。チーム・リギルのメンバー。口数は少ないが圧倒的な強さを誇る一匹狼、ナリタ・ブライアンは、その性格とレースでの活躍から、アカデミー全体で恐れられている。 彼女は走ることにしか興味がなく、それもただ自身の尽きることのない渇きを癒やすためだけに走っている。レース場以外では、ビワハヤヒデの妹であり、なぜか生徒会の副会長も務めている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b140843-VfJQpCEI7uAa.png', '5月3日', NULL, '衣川里佳', 160, 140843, 'SUPPORTING', 107) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021700', 'AN1947', '主治医', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b207526-vudep5Gwt10z.png', NULL, NULL, '古川慎', NULL, 207526, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021701', 'AN1947', 'グラスワンダー', '清楚で愛らしい。心の底から日本を愛する彼女は、アメリカから帰国したばかりだ。アメリカ生まれだが、日本文化を愛する両親の影響を受け、彼女もまた日本に関するあらゆるものを愛するようになった。そのあまりの似せぶりに、「理想的な日本の美女そのもの」と称されるほどだ。 話し方は親しみやすく、誰とでもすぐに打ち解けるが、意志は強い。勝つという決意は誰にも負けない。親友のエルコンドルパサーと部屋をシェアしている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b140848-pYoMXeoZ8Pve.jpg', '2月18日', NULL, '前田玲奈', NULL, 140848, 'SUPPORTING', 110) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021702', 'AN1947', 'ダイサンゲン', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b301434-nP1vSgFTW8I4.png', NULL, NULL, '原優子', NULL, 301434, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021703', 'AN1947', 'スペシャルウィーク', 'さあ、行くぞ！ 夢に向かってまっすぐ進む、純粋な少女。 北海道生まれの「スペシャルウィーク」は、明るく陽気で、努力家のウマ娘だ。生みの母親を亡くした後、スペシャルウィークは母親の友人に育てられた。 今、彼女は「日本一の競走馬になる」という約束を果たし、二人のママを誇りに思わせたいと願っている。道中でつまずくこともあるかもしれないが、その不屈の精神が、彼女を常に前へと突き動かしている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125299-25UtXyMMdoyQ.png', '5月2日', NULL, '和氣あず未', 158, 125299, 'SUPPORTING', 637) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021704', 'AN1947', 'トレーナー', 'チーム・スピカのトレーナー。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/125308-zi5QLqjXLBAF.jpg', NULL, NULL, '沖野晃司', NULL, 125308, 'SUPPORTING', 85) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021705', 'AN1947', '細江純子', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b203215-50LRbPheWmbH.png', NULL, NULL, '細江純子', NULL, 203215, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021706', 'AN1947', '黒沼', 'ミホノ・ブルボンのトレーナー。彼女は彼を「マスター」と呼んでいる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b211186-inQk4owAVX5D.png', NULL, NULL, '黒田崇矢', NULL, 211186, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021707', 'AN1947', '南坂', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258017-VunbOa9tdmjb.png', NULL, NULL, '古川慎', NULL, 258017, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021708', 'AN1947', 'ヒシアケボノ', 'ボリュームたっぷりで気前のいい…盛り付け？　人生にもっと「ブオーノ」を取り入れよう！ ♪　食べるのと同じくらい、人に料理を振る舞うのが大好きな寛大なシェフ。 彼女は、周りの人たちの笑顔を見ることを何より願う優しい人です。海外で生まれ、ある意味では相撲マニアにもなりましたが、最終的には土俵の上ではなく、料理の道を選ぶことにしました。どうやら、子供の頃の夢は「ちゃんこ鍋」のようになりたいことだったようです。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b301436-o5YiKaPBAywP.png', '4月25日', NULL, '松嵜麗', 180, 301436, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021709', 'AN1947', 'ウオッカ', 'わがままで元気いっぱい！心優しいロードスター。 一番「クール」であることを目指し、このウマムスメは不良ぶることに全力を尽くしている。バイク好きの父親に似て、その趣味や物腰を忠実に真似している。 目立ちたがり屋な性格ゆえ、どんな挑戦にも果敢に立ち向かい、目の前の困難を恐れることは決してない。ルームメイトのダイワスカーレットとは、少しばかり猫と犬のような関係にある。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125304-XAdxEdkeSJh7.png', '4月4日', NULL, '大橋彩香', 165, 125304, 'SUPPORTING', 207) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021710', 'AN1947', 'ナイスネイチャ', '彼女にはあまり期待しないほうがいい。このウマ娘は超シニカルなんだ。 貧しい家庭出身で、悲観的になりがちなウマ娘だ。 自分を脇役だと思い込みがちで、そのせいで高い期待を背負うことを避けてしまう。そのため、時折、完璧とは言えないパフォーマンスになってしまうこともある。労働者階級の家庭で育ったため、料理や掃除にはかなりの手際があり、時間があるときはいつでもそれらを行っている。町の年配者たちにとっては、お馴染みの顔と言える存在だ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200350-NCKuSh9jnxFm.png', '4月16日', NULL, '前田佳織里', 157, 200350, 'SUPPORTING', 380) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021711', 'AN1947', 'ビワハヤヒデ', '情熱的な知性派。論理こそが彼女の武器だ！ 生粋の理論家である彼女は、あらゆる問題を体系的に分析する。 理論重視である一方で、実践的な応用も重視しているため、彼女の手法は決して空論に終わらない。姉であるナリタ・ブライアンの圧倒的な才能に引けを取らないよう、その能力を磨き上げてきた。同級生のナリタ・タイシンやウイニングチケットとは大の仲良しだ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b174851-NYbXUXOqACOs.png', '3月10日', NULL, '近藤唯', 171, 174851, 'SUPPORTING', 92) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021712', 'AN1947', 'マヤノトップガン', 'まるであなたの愛らしい妹のような子。早く大人になりたいと待ちきれない様子！　出会う人すべてに愛情を求めてくる、やんちゃで天才的なウマ娘だ。 パイロットの父親を持つマヤノトップガンは、よく航空用語を会話に織り交ぜる。目の前にある新しくて刺激的なものに夢中になってしまうその傾向は、彼女が夢見る「成熟した洗練された女性」になるにはまだ程遠いことを物語っている。しかし、彼女は驚くべき直感力と、正しいことを見極めるほぼ超自然的な感覚を確かに備えている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b286912-j3t0GcvKPHM3.png', '3月24日', NULL, '星谷美緒', 143, 286912, 'SUPPORTING', 101) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021713', 'AN1947', 'レリックアース', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b301437-JnvMh1IJdHtI.png', NULL, NULL, '河上明日香', NULL, 301437, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021714', 'AN1947', 'ツインターボ', 'ターボブースト！このワイルドなチャージャーには限界なんてない！ 若々しいエネルギーに満ち溢れ、ただひたすらに、狂ったように走り続けたいと願う学生だ！ まだ自分の限界をあまり理解していないため、つい全速力で突き進んでしまう傾向があるが、そのワイルドな生き方を楽しんでいるようだ。 同年代の他のランナーたちに比べると少し未熟で、自己中心的なところもあるけれど、その率直で自由奔放な性格を責めることは難しい。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200351-7PNcjunPxKY9.png', '4月13日', NULL, '花井美春', 146, 200351, 'SUPPORTING', 296) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021715', 'AN1947', 'ダイタクへリオス', '最高の雰囲気だけ！マジで、マジで！冗談じゃない！ ☆ パーティーの準備はできてる？このランナーだよ！「私、超盛り上がり中？！そりゃあ当然でしょ、何かやるなら、絶対に楽しくしなきゃ！もしそれを『気まずい』って言うなら、もっと盛り上げてやるわ！ ♪」これが、明るくおしゃべりなこのランナーの心構えだ。笑顔が爆発するほど楽しく、パーティー三昧の準備をしておいてね。だって彼女は楽しむためにここにいるんだから。ヘリオスは招待を断るようなタイプじゃないし、どんな場面も最高に盛り上げるのが得意なんだ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b205733-V2qapUVxBERM.png', '4月10日', NULL, '山根綺', 156, 205733, 'SUPPORTING', 219) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021716', 'AN1947', 'ナリタタイシン', '気丈で、物事をありのままに受け止める！その小柄な体格が、意外な強みとなっている。  鋭い頭脳を持つ反骨精神あふれるソル。小柄な体格をからかわれることが多かったため、今では自分の真の実力を証明しようと奔走している。その荒っぽい性格は、見下されることを嫌う気持ちから来ている。同級生の「ウイニングチケット」や「ビワハヤヒデ」とは大の仲良しだ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b174850-a3FIi4hAEJmx.png', '6月10日', NULL, '渡部恵子', 145, 174850, 'SUPPORTING', 65) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021717', 'AN1947', 'サクラバクシンオー', 'この学級委員、暴走中！　フルスピード・バクシーン！　どんな状況にも無謀に突っ込んでいく学級委員。一度心に決めたことは、目標に向かってバクシーンと一直線に突き進む――その結果、問題を解決するどころか、かえって大混乱を招いてしまうことも多い。 しかし、決して独善的に振る舞うことはなく、誰も助けを求めてくれないと落ち込んでしまう傾向がある。その短距離走の才能は圧倒的で、比類なきスピードで誰よりも速く走れると自信を持っている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b265079-aZoxXDigj7Pm.png', '4月14日', NULL, '三澤紗千香', 158, 265079, 'SUPPORTING', 93) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021718', 'AN1947', 'リオナタール', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b301438-onnKU3rKyQsa.png', NULL, NULL, '青山吉能', NULL, 301438, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021719', 'AN1947', 'サイレンススズカ', '音速の壁を破ることを目指す、物静かなランナー。比喩的にも文字通りにも常に先頭を走る、天才と目されるウマ娘だ。走ることに没頭しすぎて、少しよそよそしく見えることもあるが、彼女が献身的な人物であることは周囲の多くが知っている。スペシャルウィークと同室で、その飾らない人柄に惹かれる人も多い。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125298-MyaIqv1U5mcg.jpg', '5月1日', NULL, '高野麻里佳', 161, 125298, 'SUPPORTING', 753) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021720', 'AN1947', 'イクノディクタス', 'コントロールフリーク。どんな状況にも柔軟に対応できる有能なウマ娘。  秘書並みの組織力を備えた、堅実なウマ娘。冷静沈着な判断力で自身のコンディションを巧みに管理しているが、その厳格さとは裏腹に、意外にも親しみやすい性格だ。かつて走ることができなかった過去を糧に、可能な限り長く走り続けることを固く決意している――', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200352-ciQm7Yb5QeVn.png', '4月16日', NULL, '田澤茉純', 163, 200352, 'SUPPORTING', 34) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021721', 'AN1947', 'メジロパーマー', 'さあ、最高に楽しい時間を過ごそう！この「うま娘」は陽気で、いつも友達のそばにいてくれる。名門・目白家の令嬢だが、その気さくで親しみやすい態度からは、そうは思えないかもしれない。 彼女は社交的で、周囲の人々の些細な変化にも気づくほどですが、才能あふれる親戚たちに囲まれているため、少し劣等感を抱いていました。しかし、やがてその感情と向き合う方法を見つけました。それは、走り、走り、そしてさらに走り続けること。その間ずっと笑顔を絶やさないのです。走り続ける限り、', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b205734-6P1BUT7U7jYT.png', '3月21日', NULL, 'のぐちゆり', 160, 205734, 'SUPPORTING', 67) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021722', 'AN1947', 'ウイニングチケット', '自分の気持ちを隠してはいけない！この子は感情を隠さず、ありのままの自分をさらけ出している。  率直で、誰とでもすぐに打ち解ける性格だ。あらゆるスポーツが大好きだが、とりわけ日本のダービーに特別な憧れを抱いており、どんな犠牲を払ってもいつかこのレースで優勝することを夢見ている。彼女と「ナリタタイシン」、そして「ビワハヤヒデ」は、切っても切れない仲だ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b174852-lfncTjSNRYAp.jpg', '3月21日', NULL, '渡部優衣', 145, 174852, 'SUPPORTING', 49) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021723', 'AN1947', 'メジロライアン', '星座：牡羊座　「ゴッドワークアウト」に勝るものはない！　額に滲む汗さえも、真摯で純粋だ。　「ゴッドワークアウト」を愛するスポーティな少女。名門・目白家に生まれたが、その生き生きとした性格は、その事実をどこか裏切っている。 幼なじみのメジロマックイーンに対して多少の劣等感を抱いており、彼女のように速くて美しくなりたいと願っている。体は丈夫だが、心はかなり繊細だ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b211554-klDWJrjnk4wi.png', '4月11日', NULL, '土師亜文', 163, 211554, 'SUPPORTING', 23) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021724', 'AN1947', 'ダイワスカーレット', '傲慢というレベルを超えている！この短気な彼女は、負けることを何よりも嫌う。 屈服を知らず、意志が強く、生意気な彼女は、何事においてもナンバーワンになりたいと願っている。普段は完璧で物静かな優等生のふりをしているが、実のところ、彼女は何よりも負けることを嫌っているのだ。 ナンバーワンになれるなら、どんなに過酷なトレーニングでも厭わない。彼女は、派手なルームメイトのウォッカを、自分のモチベーションであり、ライバルでもあると見なしている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125301-lWAxeTdvjUsS.png', '5月13日', NULL, '木村千咲', 163, 125301, 'SUPPORTING', 364) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021725', 'AN1947', 'マチカネタンホイザ', '率直で前向きなこの模範生は、常に110％の力を出し切っています！しかし、その努力にもかかわらず、彼女の中にあるおっちょこちょいな一面が、肝心な場面でつまずかせてしまうことがよくあります。 こうした浮き沈みが相まって、彼女自身の言葉によれば「ごく平均的」な結果に落ち着く。時には、周囲の個性豊かな人たちのようにありたいと願うこともあるが、彼女は自分のやり方で突き進み、成功を掴み取ることを決意している！', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200353-DrAJpWOYyHxn.png', '5月7日', NULL, '遠野ひかる', 155, 200353, 'SUPPORTING', 254) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021726', 'AN1947', 'ミホノブルボン', '常に命令に従う！サイボーグのウマ娘。「サイボーグ」の異名を持つウマ娘。彼女はプログラミングやデータベースというレンズを通して世界を見つめ、無表情でロボットのような振る舞いで目標を達成していく。 とはいえ、彼女は感情のない機械というわけではない。幼い頃から絶え間なく訓練を受けてきた結果、人との関わりが少なくなり、それが現在の性格につながっただけなのだ。そのロボットのような外見の下には、確かに感情が宿っている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b205735-SmbhSGTIgmv8.png', '4月25日', NULL, '長谷川育美', 160, 205735, 'SUPPORTING', 162) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021727', 'AN1947', 'エルコンドルパサー', 'The North American Phantom Bird! A vivacious and quirky lucha libre.  A masked luchadora, she''s always hyped up and ready to wrestle. She has ultimate confidence that she''s the world''s strongest Umamusume, and loves to proclaim that fact to anyone who''ll lend her an ear. Her mask is a present from her pro wrestler father and she insists on keeping it on all the timeーno matter what. Her best friend and roommate, Grass Wonder, constantly scolds her for being too reckless.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125303-xDG9kY8Wa7rC.png', '3月17日', NULL, '髙橋ミナミ', NULL, 125303, 'SUPPORTING', 230) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021728', 'AN1947', 'メジロドーベル', '彼女は変わりたいと願っている！このウマムスメは、過去の傷を抱えている。無愛想で無口な上、特に男性が同席しているような社交の場では、常に緊張した様子を見せている。来客が絶えない名門・目白家で育ったにもかかわらず、彼女は極めて保護された生活を送ってきたのだ。 おそらくそのせいか、見知らぬ人に対しては冷たく映ってしまうこともあるが、時間をかけて彼女と話をしてみると、一見したほど堅苦しくはないことがわかるだろう。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b211555-xo31yGg8bGst.png', '5月6日', NULL, '久保田ひかり', 157, 211555, 'SUPPORTING', 26) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021729', 'AN1947', 'みなみ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b388048-cdOw0cQzAm2G.jpg', NULL, NULL, '上西哲平', NULL, 388048, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021730', 'AN1947', 'ゴールドシップ', 'ワイルドで予測不能、この黄金のランナーは他の誰とも違う！　生まれつき自由奔放な気質をたっぷり備えた、予測不能な熱血漢だ。彼女の気分ややる気は劇的に変動しがちで、ある瞬間は手の込んだオチを仕込んでいるかと思えば、次の瞬間には彼女を動かすことさえ困難になるほどだ。 誰とでも仲良くしているように見えますが、他者との絆を彼女がどう捉えているのかは定かではありません。まさに、彼女こそがトレーセン随一のいたずらっ子だと言えるでしょう。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125305-EH7Kf1WPFY5x.jpg', '3月6日', NULL, '上田瞳', 170, 125305, 'SUPPORTING', 887) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021731', 'AN1947', 'サトノダイヤモンド', 'チーム：カペラ　ダイヤモンドよりも強靭な意志の持ち主！どんな呪いにも立ち向かえる！  裕福な家庭に生まれ、幼い頃から愛情をたっぷり注がれて育った。この過保護な育ち方のせいで、彼女は少々世間知らずな面もあるが、その穏やかで誠実な物腰の奥には、ダイヤモンドのように固い決意が隠されている。彼女は、里野家の不運の連鎖を断ち切り、一族の名誉を取り戻すことを固く決意し、毅然として歩み続けている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200354-eCorGNUFRn0E.png', '1月30日', NULL, '立花日菜', 135, 200354, 'SUPPORTING', 279) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021732', 'AN1947', 'ライスシャワー', '不運の使者？　このレーサーは、陰鬱な運命にもかかわらず、夢を追い続けている。内気なウマムスメである彼女は、周囲に降りかかる不運はすべて自分のせいだと思い込んでいるが、実際には単なるタイミングの悪さなだけなのだ。 それでも、彼女は自分についたというこの「不運」を断ち切ろうと決意している。暇なときは絵本を読むのが大好きで、特に『幸運の神の青いバラ』を好んで読んでいる。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b205736-czNHCYh48fIc.png', '3月5日', NULL, '石見舞菜香', 145, 205736, 'SUPPORTING', 1012) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021733', 'AN1947', 'セイウンスカイ', '自分のやりたいことを、やりたい時にやる。漂う土塊のように自由気まま…… 出会う中で最も気楽な女の子の一人として、彼女は自分のペースで人生を生きている。 しかし、その内面はかなり策士で、彼女の怠けぶりは、他人の警戒心を解かせるための演技に過ぎない……こともある。趣味は午後の昼寝と釣り。猫も大好きで、よく外で芝生の上で猫たちと一緒に丸くなって寝ている姿が見られる。スペシャルウィークとは同級生だ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125310-mPJI1mQjoEpj.png', '4月26日', NULL, '鬼頭明里', 155, 125310, 'SUPPORTING', 180) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021734', 'AN1947', 'ますお', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b388049-4XInc9XbkRTT.jpg', NULL, NULL, '有隅融', NULL, 388049, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021735', 'AN1947', 'キタサンブラック', 'チーム：スピカ　彼女の笑顔は部屋を明るく照らす。お祭りが大好きな、まるで太陽のような存在。　いつも明るく陽気で、誰よりもお祭りが大好きだ。生まれつきの利他的な性格から、困っている人を放っておくことができず、いつでも誰かの話に耳を傾ける準備ができている。 その底知れぬ優しさは周囲の人々から称賛を集めているが、興奮しすぎると、彼女の言葉にはどこか祭りらしい賑やかさが混じってしまう。太陽のように輝く笑顔を浮かべ、彼女はまばゆい地平線へと走り続け、願っているのは――', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200355-30WAdFX7GUOZ.png', '3月10日', NULL, '矢野妃菜喜', 140, 200355, 'SUPPORTING', 690) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021736', 'AN1947', 'じいや', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b207525-63vMbPq8Mz9W.png', NULL, NULL, '梅津秀行', NULL, 207525, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021737', 'AN1947', 'エアグルーヴ', '冷徹で計算高い「女帝」。卓越した才能と野心を兼ね備えている。トレーセン・アカデミー生徒会の副会長であり、他の生徒たちからは「女帝」として知られている。 名だたる競走馬の娘として、彼女は常に母のレースでの実力や、他者を導く手腕に追いつこうと努力している。そのために、親友であり心許せる相棒であるシンボリルドルフと共に生徒会に入会した。多忙なスケジュールの中でも、庭の花の手入れをする時間を必ず作っている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b140846-gsLxIFWO23fg.jpg', '4月6日', NULL, '青木瑠璃子', NULL, 140846, 'SUPPORTING', 64) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021738', 'AN1947', 'メイショウドトウ', '自分のオトルクと自分自身を変えるために、この悲観主義者は全力を尽くしている。彼女の自尊心は、耳と同じくらいまで下がってしまう。 この不器用な少女にとって、物事はいつもうまくいかないようだ。それでも、彼女はより良い自分になることを決意し、明るい未来を手に入れるチャンスのために、決して諦めようとはしない。彼女はT.M.オペラ・Oの堂々とした自信に憧れている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b211557-8Oxh2lU1wk7k.png', '3月25日', NULL, '和多田美咲', 164, 211557, 'SUPPORTING', 270) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021739', 'AN1947', 'マチカネフクキタル', '幸運が私と共にありますように！この魅力あふれる「ウマ娘」は、占い adores が大好き。占いに夢中な上、超常現象にも興味津々で、レースの結果をはじめ、あらゆることを運任せにすることに何の不満も感じていない。 自分のために占いをしていない時は、誰かのために占いをしている。彼女は、走り続ける限り、進むべき道が目の前に開かれるという、ある神からの啓示を深く信じている。彼女が持ち歩いている猫型のバッグの名前は「ミス・ニャ」だ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b211561-BkDHJdLFeGhN.png', '5月22日', NULL, '新田ひより', 163, 211561, 'SUPPORTING', 102) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021740', 'AN1948', '三雲修', '三雲修は『ワールドトリガー』の主要な主人公の一人であり、トリオン値の低いボーダーのメンバーである。ジンに助けられたことをきっかけにボーダーに加入した。三雲班以外のメンバーからは、通常「フォー・アイズ」と呼ばれている。', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/81237-pMalpmM5qBbR.jpg', '5月25日', NULL, '梶裕貴', NULL, 81237, 'MAIN', 290) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021741', 'AN1948', 'ヒュース', 'ヒュースは、漫画およびアニメシリーズ『ワールドトリガー』に登場するキャラクターである。彼はアフトクラトール出身のネイバーであり、ジンとの戦いに巻き込まれた後、地球に取り残された／置き去りにされた。', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b140699-LyYGLHX2cf2m.png', '6月12日', NULL, '島﨑信長', NULL, 140699, 'MAIN', 366) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021742', 'AN1948', '空閑遊真', 'ユマはのんびりした性格で、別の世界から来たため（父親が日本人であるにもかかわらず）、日本の習慣にあまり詳しくない。そのため、悪党たちとトラブルに巻き込まれることもある。   彼は論理的な思考の持ち主で、生徒たちを救おうとするとミクモが命を落とす可能性があるとして、トリオン・バトル・ソルジャーには近づかないようミクモに忠告した。彼はボーダーの理念に賛同しているようで、ネイバーの勢力と戦っている。', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b81239-n1aMD2Jig1WP.png', '7月18日', NULL, '村中知', 141, 81239, 'MAIN', 1058) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021743', 'AN1948', '雨取千佳', '雨取千佳は『ワールドトリガー』の主要な主人公の一人です。千佳はとても内気で、めったに多くを語りません。自ら他人と距離を置いているため、友達はほとんどいません。親しくなった相手が「ネイバー」に誘拐されてしまうと、自分が傷つくだけだと信じているからです。 彼女は非常に忍耐強く、真面目で、集中力も高いが、自信が乏しく、自分の可能性に気づくことができない。しかし、ユマと出会い、タマコマ支部に加入してからは、徐々に他人に心を開き始めている。', 13, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89227-TU2ouIZnTQAx.png', '2月11日', NULL, '田村奈央', 140, 89227, 'MAIN', 208) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021744', 'AN1948', '迅悠一', '迅悠一はSランクのエージェントであり、タマコマ支部の所属でもある。彼はボーダーでも屈指の強さを誇るメンバーの一人だ。また、「風神」という名のブラック・トリガーを所持している。ジンのサイドエフェクトは「予知」であり、これにより未来の出来事を予測することができる。 彼の師匠である最上聡一は、ジンの「風神」を作り出す過程で命を落とした。ボーダーのエンジニアたちの協力を得て、ジンは新型トリガー「スコーピオン」を開発し、多くのボーダーエージェントに採用された。', 19, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89014-tHgKpnHQSnbV.png', '4月9日', NULL, '中村悠一', 179, 89014, 'MAIN', 582) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021745', 'AN1948', '忍田真史', '彼はボーダーのゼネラルマネージャーであり、自衛部隊の指揮官でもある。彼は本部において、通常のトリガーを持つ者の中では最も権力のある人物である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155807-awKG7rYYjinW.png', '10月16日', NULL, '草尾毅', NULL, 155807, 'SUPPORTING', 21) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021746', 'AN1948', '風間蒼也', '彼は風間ユニットのAクラスリーダーであり、アタッカーランキング第2位である。その行動から、「ブラック・トリガー回収編」では敵役として登場するが、後に味方となる。また、迅悠一の「風神」の候補者11人のうちの1人でもある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155811-GgUQb0vpuZtr.png', '9月24日', NULL, '緑川光', NULL, 155811, 'SUPPORTING', 79) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021747', 'AN1948', 'ウェン・ソー', 'トリガー：セルヴィトーラ', 24, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213240-VZl2riTAw7eo.jpg', '7月11日', NULL, '園崎未恵', NULL, 213240, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021748', 'AN1948', '王子 一彰', 'オジはアタッカーであり、「オジ・スクワッド」（Bランク第5位）のリーダーである。彼は洞察力に優れ、策略家でもある。 また、他人に奇妙なあだ名をつける癖もある。彼は王子のような振る舞いをしており、これは彼の姓への意図的な言及であるように見える。というのも、説明の際に使用するアイコン――王子冠をかぶったハンサムな男性を描いたもの――の作成をキッタカに依頼したのは彼自身だったからだ。 これは彼の趣味にも表れており、オムレツ、クロワッサン、馬、そしてcなどが彼の好きなものの一部となっている。', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b222933-HI2HGnHorDYl.png', '1月11日', NULL, '石田彰', NULL, 222933, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021749', 'AN1948', '天羽月彦', 'Sクラスのエージェントであり、「ブラック・トリガー」の使用者。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b179731-nSoVsC0cx7ET.jpg', NULL, NULL, '代永翼', NULL, 179731, 'SUPPORTING', 22) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021750', 'AN1948', '米屋陽介', '米屋陽介は「Miwa Unit」のメンバーです。陽介はのんきなタイプで、楽しむことが好きです。物事を深刻に受け止めません。また、ネイバーズに対しても恨みなど一切抱いていません。陽介はある日、ユマに「ただ楽しむために、一度戦ってみよう」と提案しました。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b179798-lB9WtHNpOnnL.jpg', '11月29日', NULL, '岸尾だいすけ', NULL, 179798, 'SUPPORTING', 30) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021751', 'AN1948', '太刀川慶', '太刀川慶は、太刀川小隊（Aランク#01）のAクラスリーダーであり、アタッカー部門ランキング1位である。ジンのライバルであり、友人でもある。  立川は傲慢な性格だ。彼はジンのような振る舞いをし、二人とも考え方が似ているため、彼がからかうのが好きな三輪からは嫌われている。 それにもかかわらず、戦場以外ではかなり親しみやすい人物だ。立川はボーダーの戦闘員としては間違いなく最も腕が立ち、有能なリーダーではあるが、戦闘以外の能力はかなり乏しい。彼は特に頭が良いわけではなく、その', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b179786-3UU4WliZqCFF.png', '8月29日', NULL, '浪川大輔', NULL, 179786, 'SUPPORTING', 51) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021752', 'AN1948', 'レギンデッツ', 'トリガー：トゥガター（トゥガターは、両側に刃が付いた長方形のワイヤーが伸び、まるで尾のような外観をしたリュックサックの姿で現れる。）  レギンデッツは概して衝動的で怒りっぽく、自分の意見を率直に述べることを恐れないが、その一方で、人を巧みに操る面もある。彼は、ガロポラを征服したアフトクラトルに対して深い恨みを抱いている。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213241-BIn4myU5vIFf.png', NULL, NULL, '村瀬歩', NULL, 213241, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021753', 'AN1948', '林藤匠', '彼はボーダーのタマコマ支部長である。リンドはジンと同様、穏やかで気楽な性格だ。ボーダーのほとんどのメンバーとは異なり、彼はネイバーを憎んでおらず、ネイバーも人間の友人になり得ると固く信じている。喫煙を好み、頻繁にタバコを吸っている。（出典：ワールドトリガーWiki）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b155814-39lREqKmdBr0.jpg', NULL, NULL, '津田健次郎', NULL, 155814, 'SUPPORTING', 27) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021754', 'AN1948', '木崎レイジ', '木崎レイジはA級エージェントであり、タマコマ支部の所属で、チカの指導役を務めている。レイジは非常に冷静で真面目な人物であり、キリエが騙されていることに気づかせてあげる役割を、たいてい担っている。時には非常に厳しい面も見せる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b179752-z8KvVZNIBxR6.jpg', '7月2日', NULL, '前野智昭', NULL, 179752, 'SUPPORTING', 28) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021755', 'AN1948', '那須玲', 'Bランクのエージェントであり、那須小隊の隊長。レイは、ベッドに座っている姿がよく描かれるほど、かなり物静かで病弱な少女だ。 しかし、その華奢な外見とは裏腹に、戦闘時には強い意志を見せ、プレッシャーのかかる状況でも比較的冷静な態度を保つ。不利な状況下にあってもチームに3ポイントを獲得できたことからも、その強さがうかがえる。また、ランク戦においてチームメイトこそが自身の原動力であったことから、彼女はその存在を非常に大切にしている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b179772-B64zYjrfpPiJ.png', '6月16日', NULL, '桑島法子', NULL, 179772, 'SUPPORTING', 27) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021756', 'AN1948', '加古望', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b179745-GC7yamQq2EdT.jpg', NULL, NULL, '渡辺美佐', NULL, 179745, 'SUPPORTING', 15) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021757', 'AN1948', 'コスケロ', 'トリガー：ニコキラ（ニコキラは半透明の粘り気のある液体の姿で現れます。その量はモードによって異なります）', 28, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213242-RZOKthfzvtt9.jpg', '4月5日', NULL, '津田健次郎', NULL, 213242, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021758', 'AN1948', '根付栄蔵', 'ボーダーズのメディア対策責任者。（出典：ワールドトリガー・ウィキア）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b179774-yaOufLgNws10.jpg', '6月2日', NULL, '島田敏', NULL, 179774, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021759', 'AN1948', '宇佐美栞', '彼女はオペレーターであり、ボーダーの玉駒支部に所属している。元々は風間ユニットのメンバーだったが、現在は玉駒ファーストおよび玉駒セカンドのオペレーターを務めており、また、ジン・ユウイチが単独エージェントであるにもかかわらず（あるいはそのために）、彼のオペレーターも兼任している。 また、「ヤシャマルシリーズ」の作者でもある。（出典：ワールドトリガーWiki）', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155806-wLtFPioWvOHP.png', '4月27日', NULL, '中尾衣里', NULL, 155806, 'SUPPORTING', 49) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021760', 'AN1948', '鬼怒田本吉', 'ボーダーズ本社開発責任者。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b179750-A69M1HNWgn0j.jpg', '7月14日', NULL, '塩屋浩三', NULL, 179750, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021761', 'AN1948', '黒江双葉', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b179759-p0OajYatgA9j.jpg', NULL, NULL, 'ゆかな', NULL, 179759, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021762', 'AN1948', 'オルカーン マーダック', 'トリガー：デスピニス（発動すると、デスピニスは両側に8つずつ、計16のスリットを備えたバックパックのような状態になる。各スリットには、中央に球体が入ったリングが収まっており、リングがホルスターから抜けると球体は大きくなる。）  オルカンは目標に集中する人物だ。鋭く現実的な思考を持ち、敵に対しても純粋な賞賛の念を抱くことができる。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213243-Gs1RtGZvV8GL.jpg', NULL, NULL, '豊永利行', NULL, 213243, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021763', 'AN1948', '菊地原士郎', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b179749-juSfuLDhLqax.jpg', '12月14日', NULL, '菅沼久義', NULL, 179749, 'SUPPORTING', 33) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021764', 'AN1948', '嵐山准', '彼はボーダーにおいてAランクのミドルレンジ・オールラウンダーであり、嵐山ユニットのリーダーを務めている。また、迅悠一の「フジン」の候補者11人のうちの1人でもある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155809-lakGl0e04HUg.png', '7月29日', NULL, '岡本信彦', NULL, 155809, 'SUPPORTING', 63) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021765', 'AN1948', '染井華', 'ハナは、どんな状況でも物静かで、自信に満ち、感情を表に出さない。幼い頃でさえ、父親に親友との付き合いを禁じられたときも、家が倒壊したときも、感情を露わにすることはなかった。また、自分の家族ではなく親友を瓦礫の中から救い出したときも、彼女は微動だにしなかった。', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213144-Dej7CXIjxsMu.png', '7月18日', 'AB', '近藤玲奈', NULL, 213144, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021766', 'AN1948', '宇井真登華', 'まどかは人当たりが良く、現実的で、気取らない性格だ。友達を温かく支え、彼らが躊躇しているときは優しく背中を押してくれる。', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213244-OpsvRrfTWZkP.png', '4月26日', 'B', '藤井ゆきよ', NULL, 213244, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021767', 'AN1948', '古寺章平', '古寺章平は「Miwa Unit」のメンバーである。章平はやや内気な性格だ。チームメイト、とりわけ先輩と仰ぐトールを深く尊敬している。 ネイバーズにホースを破壊されたため、彼らを嫌っているが、ミワやトオルほど深刻には考えていないようだ。（出典：ウィキペディア）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b179754-rPkiCVeg8bLl.jpg', NULL, NULL, '高戸靖広', NULL, 179754, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021768', 'AN1948', '小南桐絵', 'キリエはA級エージェントで、タマコマ支部の所属であり、ユウマの指導役でもある。彼女は騙されやすい純真な少女で、そのお人好しさゆえに皆からからかわれることが多く、些細なことで大騒ぎしてしまう傾向がある。 また、彼女は弱者を嫌うため、ユマのメンターになることを選んだのだ。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b159427-T0fg2ZKCA2Gy.png', '7月28日', NULL, '釘宮理恵', NULL, 159427, 'SUPPORTING', 271) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021769', 'AN1948', '木虎藍', '彼女は、Aランクのボーダーチーム「嵐山ユニット」に所属する近距離型のオールラウンダーである。また、迅悠一の「フジン」候補11人のうちの1人でもある。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155812-tvJzyprqJp3r.png', '6月26日', NULL, '花澤香菜', NULL, 155812, 'SUPPORTING', 63) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021770', 'AN1948', '三浦雄太', '物腰が柔らかく、対立を避けることを好む。カトリと若村麓郎が口論になると、彼は二人をなだめようとする（たいていは失敗するが）。決して自分の立場を明かすことはなく、チームメイトがそれを必要としていると気づいた時にはそうすることもあるが、普段は自分の気づいていることをあまり口に出さない。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213145-2YbxKgDBzh6p.png', '9月3日', 'B', '三野雄大', NULL, 213145, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021771', 'AN1948', '若村麓郎', 'トリガー：アステロイド（アサルトライフル）、ホンド（アサルトライフル）、シールド　サブトリガー：カメレオン、シールド、バッグワーム　カトリ小隊の一員。ワカムラは神経質で、競争心が強く、非常に口が悪い。 こうした性格のせいで、対戦相手に侮辱的な言葉を浴びせることもあるが、それ以上に、香取陽子との間で摩擦が生じることが多い。彼の苛立ちの一因は、2年間の厳しい訓練を経てもマスタークラスに到達できなかったことによる自身の不安感にあり、それはスミハルにもかかわらず……', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213245-1aHn4M2e4gUW.jpg', '4月16日', 'B', '赤羽根健治', NULL, 213245, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021772', 'AN1948', '唐沢克己', 'ボーダーズの外交業務マネージャー。（出典：ワールドトリガー・ウィキア）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b179746-lxSzooyirmI3.jpg', NULL, NULL, '竹本英史', NULL, 179746, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021773', 'AN1948', '熊谷友子', 'Bランクのエージェントであり、ナスの部隊を襲撃した犯人。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b179757-BZCJFPxTf1Hy.png', '4月14日', 'O', '庄司宇芽香', 171, 179757, 'SUPPORTING', 21) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021774', 'AN1948', '林藤陽太郎', '林藤陽太郎は、ボーダーの玉駒支部に所属している。陽太郎は人見知りをせず、よくやってはいけないことをしたり、突拍子もない行動をとったりする。しかし、雷神丸を犬だと思っているほど、子供っぽい一面もある。 陽太郎は大量のトリオンを保有しており、その量はサイドエフェクトを引き起こすのに十分な量である。（出典：World Trigger Wikia）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b179780-cbIFkhnHCvPX.jpg', NULL, NULL, '浦和めぐみ', NULL, 179780, 'SUPPORTING', 82) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021775', 'AN1948', 'ガトリン', 'トリガー：ヴァシリッサ（ヴァシリッサはリュックサックのような装置の姿をしており、そこから3本の機械の腕が伸びている。）  ガトリンは、背が高くがっしりとした体格の男で、短い黒髪をし、額には左下に向かって走る傷跡がある。また、無精ひげを生やしている。彼は、可能な限り非暴力的な手段でボーダーを機能不全に陥らせることを決意したことから、慎重かつ狡猾な人物であるようだ。', 35, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213238-kIdKr1W8NmsI.jpg', NULL, NULL, '江川央生', NULL, 213238, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021776', 'AN1948', '香取葉子', 'ランク：B（11位） トリガー：スコーピオン、アステロイド（ハンドガン）、シールド、グラスホッパー サブトリガー： スコーピオン、ホンド（ハンドガン）、シールド、バッグワーム　自らを「天才」と平然と称するカトリは、傲慢で怠惰、そして自分の才能に極めて自己満足しているように見えがちだが、その才能のおかげで、何事にもほとんど努力を要せずに目覚ましい成果を上げることができる。 しかし、ボーダーへの入隊は彼女に自信喪失を引き起こし、その兆候はまず、彼女が繰り返し', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213246-daSwIkBkCpHo.jpg', '10月18日', 'O', '潘めぐみ', NULL, 213246, 'SUPPORTING', 35) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021777', 'AN1948', '三輪秀次', 'ミワは近接型のオールラウンダーであり、ミワ部隊（Aランク #07）のリーダーである。また、迅悠一の「フジン」候補11人のうちの1人でもある。ミワは物静かなタイプで、あまり話さず、常に真剣な表情を浮かべている。 妹の死をきっかけに、彼はネイバーに対して妥協のない憎悪を抱くようになり、ネイバーに関しては攻撃的、時には暴力的な行動さえ見せる。ユウマがネイバーであることを認めた際、ミワは躊躇なく彼を撃った（ただし、その攻撃は', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155813-g4zWrHMpbOyw.png', '10月2日', NULL, '森田成一', NULL, 155813, 'SUPPORTING', 44) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021778', 'AN1948', '緑川駿', '緑川駿は、クサカベ・ユニットのメンバーである。米屋は、緑川の性格を「自分の才能をどうしても見せびらかしたい子犬」に例えた。これは、大勢の観客の前で、緑川がオサムを難なく10回も打ち負かし、彼を辱めた場面にも表れていた。 しかし、ジンに対しては、かつてジンに命を救われたことから、非常に間抜けで元気いっぱいの振る舞いを見せた。（出典：World Trigger Wikia）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b179763-fmfKUGk6mMfP.jpg', NULL, NULL, '森下由樹子', NULL, 179763, 'SUPPORTING', 28) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021779', 'AN1948', '諏訪洸太郎', '諏訪はBランクのエージェントであり、諏訪分隊（Bランク第12分隊）のリーダーである。彼はロッドであり、何事にも大げさに反応する派手な性格の持ち主だ。下品で自己主張が強いが、非常に親しみやすく気取らないため、周囲の人たちともすぐに打ち解ける。 戦闘時には無鉄砲になりがちで、敵をからかったり、挑発して怒らせたりすることを楽しんでいる。トリオン体には、火もつけていないタバコをくわえているが、これは単なる見せびらかしである。諏訪は分隊を効果的に率い、団結させることができる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b179785-vUkqqZJgMWid.png', '8月1日', NULL, '沼田祐介', NULL, 179785, 'SUPPORTING', 27) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021780', 'AN1948', 'ヨミ', '能力：パーフェクト・パラレル・プロセッシング　ヨミは頭にヘルメットをかぶった少年だ。顎までの長さの髪が額の大部分を覆っている。ヨミは普段物静かで、話す姿はあまり見られない。彼はプロフェッショナルで落ち着いた振る舞いをし、非常に分析的な一面を見せている。 彼は極めて知性が高く、トリオン技術の開発に長けていることで知られている。', 14, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213239-a6HSnN06tyoR.jpg', NULL, NULL, '白石涼子', NULL, 213239, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
