INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021783', 'AN1949', '一条蛍', '東京から旭ヶ丘分校に転校してきた小学5年生の女の子。背が高く、年齢の割に大人びているが、内気なところもあり、小丸に片思いをしている。', 11, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b54145-x14HGjjIhdpi.jpg', '5月28日', NULL, '村川梨衣', NULL, 54145, 'MAIN', 550) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021784', 'AN1949', '越谷小鞠', '中学2年生で、夏美の姉。身長がかなり低く、そのことをコンプレックスにしている。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b54149-JsepdZLKa9BP.jpg', '9月14日', NULL, '阿澄佳奈', 140, 54149, 'MAIN', 610) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021785', 'AN1949', '越谷夏海', '中学1年生で、コマリの妹。おっちょこちょいで、成績も悪いおてんば娘。', 13, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b54147-Su4AgvqzRG68.jpg', '1月24日', NULL, '佐倉綾音', NULL, 54147, 'MAIN', 462) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021786', 'AN1949', '宮内れんげ', '小学1年生のレンゲ。いつもリコーダーを手放さず、番組に登場するキャラクター全員にニックネームをつけるのが好きだ。特にカエデにはとても懐いており、彼女を「キャンディショップ」と呼ぶのが好きで、赤ちゃんの頃からずっとカエデを可愛がっている。', 6, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b54151-V8Qh2l2gTxvH.jpg', '12月3日', NULL, '小岩井ことり', NULL, 54151, 'MAIN', 2531) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021787', 'AN1949', '宮内ひかげ', '宮内家の三姉妹のうち真ん中の娘であるヒカゲは、東京の高校に通っており、そのことをレンゲに頻繁に自慢しようとする。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b87833-ZZVjPQn6mGwM.jpg', '12月7日', 'O', '福圓美里', NULL, 87833, 'SUPPORTING', 164) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021788', 'AN1949', '越谷雪子', '夏美、小麻里、そして秀の母親。彼女もまた、旭ヶ丘分校の卒業生である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/87831.jpg', NULL, NULL, '平松晶子', NULL, 87831, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021789', 'AN1949', '篠田あかね', '篠田あかねは、富士宮このみの同級生（3年生）です。あかねもこのみも、学校のウィンドアンサンブル部でフルートを担当しています。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b189967-hg1rfdl9WV0s.png', NULL, NULL, '田中あいみ', NULL, 189967, 'SUPPORTING', 23) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021790', 'AN1949', '石川ほのか', '夏休み中にレンゲと友達になる小学1年生の男の子。', 7, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/87827.jpg', NULL, NULL, '高垣彩陽', NULL, 87827, 'SUPPORTING', 26) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021791', 'AN1949', 'しおり', 'しおりは『ノンノンビヨリ』に登場する脇役です。 父親は地元の警察官です。彼女は宮内れんげより年下で、れんげのことを「お姉ちゃん」と呼んでいます。恥ずかしがり屋ですが、憧れのれんげを「お姉ちゃん」として慕い、一緒に遊ぶことにはとても熱心です。', 5, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b191960-K7ZAAU3fgGn6.png', NULL, NULL, '久野美咲', NULL, 191960, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021792', 'AN1949', 'ほのかの母', 'ほのかのお母さん。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b212966-HhWo80oT0QeP.png', NULL, NULL, '後藤邑子', NULL, 212966, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021793', 'AN1949', '富士宮このみ', '富士宮このみは、『ノンノンビヨリ』シリーズの登場人物です。 彼女は朝日丘分校の卒業生で、越谷家の隣に住んでいる。このみはとても大人びた10代の少女だ。小麻里や夏美、そして蓮華にとってのロールモデルとなっている。とても思いやりがあり、楽しい性格だが、時には真剣な一面も見せる。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b87825-Z7hS7YuSE6hh.jpg', NULL, NULL, '新谷良子', NULL, 87825, 'SUPPORTING', 128) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021794', 'AN1949', '蛍の母親', '一条お母さんは『ノンノンビヨリ』に登場するキャラクターです。彼女は一条蛍の母親です。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b75704-KSgU2bJnl3YW.png', NULL, NULL, '永島由子', NULL, 75704, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021795', 'AN1949', '宮内一穂', '宮内一穂は、朝岡分校で唯一の教員として働いている。彼女は目を閉じているように描かれており、授業中はたいてい地味な服か白衣を着ている。のんびりした性格で、かなり怠け者な一面も見られる。 朝日岡分校には、小学生から中学生まで5人の生徒しか通っておらず、全員が同じクラスで学んでいる。混合クラスであるため、生徒たちは主に各自で勉強しているが、一穂はほとんどの時間を机の上で眠って過ごしている。彼女は…', 24, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/87832.jpg', NULL, NULL, '名塚佳織', NULL, 87832, 'SUPPORTING', 119) ON CONFLICT DO NOTHING;
