INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021797', 'AN1949', '加賀山楓', '地元の菓子屋を経営しており、カズホの後輩である。レンゲがまだ赤ちゃんだった頃、彼女のベビーシッターをしていたことがある。', 20, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b87829-fyEOxI5AsQz4.png', NULL, NULL, '佐藤利奈', NULL, 87829, 'SUPPORTING', 546) ON CONFLICT DO NOTHING;
