INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021799', 'AN1949', '越谷卓', '中学3年生で、夏美と小真里の兄。口数が少なく、存在感もほとんどない。', 14, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/87830-ufdaIjT948vQ.jpg', '4月11日', NULL, NULL, 171, 87830, 'SUPPORTING', 130) ON CONFLICT DO NOTHING;
