INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021801', 'AN1950', 'クロ', '彼は中学生で、ラムネの弟子であり、助手として働いている。優れた判断力と運動能力に加え、理性的な思考の持ち主でもある。 ポーカーフェイスのため、彼の本心を見抜くのは難しく、ラムネが何か言ったりしたりするたびに、いつもツッコミ役を強いられている。クロは、難病の専門家としてのラムネの腕前を完全に信頼している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b187922-MRXvq4xxgWO0.jpg', NULL, NULL, '永塚拓馬', NULL, 187922, 'MAIN', 118) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021802', 'AN1950', 'ラムネ', '彼は、「心弱き者の心に『奇妙なもの』が忍び込む」ことによって引き起こされる「謎の病」の治療を専門とする医師である。彼は、ほとんどの人に対して無礼で、周囲の雰囲気をほとんど理解できない、風変わりな医師だ。 しかし、彼はどんな病気の根本原因も素早く突き止めることができる、非常に腕の良い医師である。ただ、常に患者を第一に考えているため、過度に厳しい治療は避けるよう心がけている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b187923-xtpT0PHLPkaI.jpg', NULL, NULL, '内田雄馬', NULL, 187923, 'MAIN', 157) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021803', 'AN1950', '柏木 琴', 'コトは、調味料を泣きながら食べ始めた子役です。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b210717-Keu8MxtpKYpX.png', NULL, NULL, '鬼頭明里', NULL, 210717, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021804', 'AN1950', '春の母親', '現在入院中のシュンの母親は、どうやらシュンの作品を見るたびに悲しくなってしまうらしい。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b210725-FOj9ypJSzQic.png', NULL, NULL, '髙橋ミナミ', NULL, 210725, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021805', 'AN1950', '勝又健吾', '股間がちくわになってしまった男。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b210718-AgkMAqraImQs.png', NULL, NULL, 'KENN', NULL, 210718, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021806', 'AN1950', '空き巣', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b210726-6T0RQLntOYPu.png', NULL, NULL, '鈴木達央', NULL, 210726, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021807', 'AN1950', '彩芽', '彼女は「ミステリオス・ウェア・ショップ・アカツキ」の元オーナーで、自らミステリオス・ウェアを制作しています。 現在まだ9歳ですが、103歳まで生きた前世の記憶をそのまま持ち続けています。人の世話をするのが得意ですが、機会があれば人を挑発することも好きです。戦いに勝てると分かると、危険なことをしがちです。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b192198-ZqtR1qJUoPNF.png', NULL, NULL, '植田佳奈', NULL, 192198, 'SUPPORTING', 94) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021808', 'AN1950', '健吾の友人', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b210719-JA8KqLxzvBSH.png', NULL, NULL, NULL, NULL, 210719, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021809', 'AN1950', '由美', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b210727-medNGQuHv7nM.png', NULL, NULL, '栗坂南美', NULL, 210727, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021810', 'AN1950', '丹己', '彼は彩芽の前世の曾孫であり、「ミステリオス・ウェアーズ・ショップ・アカツキ」の現在の店主である。 とても温厚で親切、いつも笑顔を絶やさないため、近所の子供たちからは「スマイルマン」と呼ばれ、絶大な人気を誇っている。幼い頃からラムネと知り合いで、二人は兄弟のような関係だ。ある特殊な体質のため、彼は誰よりも周囲の状況を鮮明に捉えることができる。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b192197-TnzY7QeeEb78.png', NULL, NULL, '岡本信彦', NULL, 192197, 'SUPPORTING', 33) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021811', 'AN1950', '琴の母親', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b210720-JwrLH9Ys4bgi.png', NULL, NULL, '小松由佳', NULL, 210720, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021812', 'AN1950', '優', '理央の兄。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b210728-f5Q1CjeCJDz1.png', NULL, NULL, '松本沙羅', NULL, 210728, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021813', 'AN1950', '紅葉', '「謎の病気」の治療を専門とする、ハンサムで一流の医師。 彼はラムネの達人だ。人をいじめるのが趣味の一つで、特にラムネに対しては厳格だ。方向音痴なため、正しい道へ導くために自ら作り出した謎のペット「ピポポ」を常に連れ歩いている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b196734-G3WCLNyg2nmz.png', NULL, NULL, '諏訪部順一', NULL, 196734, 'SUPPORTING', 29) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021814', 'AN1950', '大友 隆晴', 'タカハルは、爪が唐辛子になってしまった高校生だ。親友のタツヤよりも学力や運動能力、そして容姿に優れていることに気づいたタカハルは、あらゆる面でわざと「普通」であるかのように振る舞うようになった。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b210721-WKOlZItURxlU.png', NULL, NULL, '島﨑信長', NULL, 210721, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021815', 'AN1950', '青菜春', 'シュンはクロの同級生で、芸術的な作品を作ることに並外れた才能を持っている。父親はシュンにもの作りをやめるよう求めており、シュンの作品が母親を悲しませているから、母親が病院に入院しているのだとシュンに告げている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b215389-VxFHXMzpfPhm.jpg', NULL, NULL, '村瀬歩', NULL, 215389, 'SUPPORTING', 42) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021816', 'AN1950', '豊後達也', 'スポーツも勉強も得意で、人気者でもあるタカハルの親友。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b210714-GgOH79xdGPGJ.png', NULL, NULL, '松岡禎丞', NULL, 210714, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021817', 'AN1950', '理央', '理央は、この家族の弟です。彼は、母親がまた自分の声を聞けるようになることを願っています。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b210722-qY0cgo9Pkla1.png', NULL, NULL, '伊瀬茉莉也', NULL, 210722, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021818', 'AN1950', '藤田志保子', 'ケンゴがよく通うレストランのウェイトレス。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b210715-uH4xOn1tAqTO.png', NULL, NULL, '咲々木瞳', NULL, 210715, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021819', 'AN1950', '理央の母親', '餃子が耳に詰まってしまい、聴力に問題が生じた母親。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b210723-cNQeHl6LfdLl.png', NULL, NULL, '中原麻衣', NULL, 210723, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021820', 'AN1950', '香織', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/default.jpg', NULL, NULL, '書上春菜', NULL, 210716, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021821', 'AN1950', '春の父親', 'シュンの父親は息子を溺愛しているが、シュンにものづくりを続けてほしくはない。その代わりに、シュンに勉強を強いている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b210724-McF6eVF8K9jE.png', NULL, NULL, '小山力也', NULL, 210724, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021822', 'AN1951', '下田', '下田は「ヘブンズ・デザイン・デパートメント」の新人であり、その経験の浅さが如実に表れている。彼は場の空気を和らげ、問題を未然に防ぎ、物事を円滑に進めるための解決策を模索している。さらに、お菓子作りが大好きだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155657-HLKValqXy3wd.jpg', NULL, NULL, '榎木淳弥', NULL, 155657, 'MAIN', 46) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021823', 'AN1951', '海原', 'デザイナー。彼の代表作は「カンガロ」だ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b155667-LFbr4MwL8IEz.jpg', NULL, NULL, '竹内良太', NULL, 155667, 'MAIN', 67) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021824', 'AN1951', '水島', '水島は、やや無愛想で無表情な性格のように見える。しかし、彼の傑作であるヘビに関しては、たとえ他の動物、とりわけ鳥を犠牲にすることになっても、その能力を誇示するために惜しみなく力を注ぐ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155658-5V5MJe6UKS8z.jpg', NULL, NULL, '諏訪部順一', NULL, 155658, 'MAIN', 26) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021825', 'AN1951', '金森', '「ヴェンちゃん」という愛称で知られるデザイナー。彼女の代表作は「鳥」だ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b155664-UuutEibDC6Xi.png', NULL, NULL, '岸尾だいすけ', NULL, 155664, 'MAIN', 83) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021826', 'AN1951', '土屋', 'デザイナーであり、デザイン部門の責任者。彼の代表作は「馬」である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b155663-s9HoPHQBcMqf.jpg', NULL, NULL, '井上和彦', NULL, 155663, 'MAIN', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021827', 'AN1951', '火口', 'エンジニア。動物の設計が現実の世界で実際に機能するかどうかを検証する。オフィスで一番働き者だ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b155666-sgdikIN8q6HG.jpg', NULL, NULL, '泊明日菜', NULL, 155666, 'MAIN', 44) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021828', 'AN1951', '木村', 'デザイナー。彼の代表作は、牛だ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b155660-rvuvenutbkae.jpg', NULL, NULL, '梅原裕一郎', NULL, 155660, 'MAIN', 42) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021829', 'AN1951', '冥戸', 'デザイナー。彼女の代表作は、ポイゾノス・フロッグだ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b155662-JTpLqa8wBz0k.png', NULL, NULL, '大空直美', NULL, 155662, 'MAIN', 59) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021830', 'AN1951', '上田', '下田の上司。神とデザイン部との間をつなぐ天使のような存在。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b155665-50JHuSbRgxAK.jpg', NULL, NULL, '原由実', NULL, 155665, 'MAIN', 22) ON CONFLICT DO NOTHING;
