INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021832', 'AN1951', '土屋ケンタ', 'サターンさんの孫。ケンタは、おじいちゃんと同じように馬が大好きだ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b155670-iQdQNTaAEgp5.png', NULL, NULL, '木野日菜', NULL, 155670, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
