INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021839', 'AN1952', '夏目アキラ', '夏目アキラは『EX-ARM エクスアーム』の主人公である。アキラはごく普通の内気な高校生だったが、テクノロジーに対する恐怖心を抱きつつも、壊れた機器を簡単に修理する才能を持っていた。 2014年、ある少女を救おうと身を挺した際、不運にもトラックに轢かれてしまった。それから16年後、警察の二人組であるアルマと上ノ園みなみは、EX-ARM エクスアーム No. 00を入手する任務に就いていたが、 しかし、EX-ARM エクスアーム No. 08 を使うグループと対峙することになり、絶体絶命の事態で、彼女たちはEX-ARM エクスアーム No. 00を起動させる。不思議なことに、A', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b177224-rQtGSEylCyMj.jpg', NULL, NULL, '斉藤壮馬', NULL, 177224, 'MAIN', 21) ON CONFLICT DO NOTHING;
