INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021849', 'AN1953', '長瀬琴乃', '長瀬琴乃は、ホシミプロダクション所属のグループ「月のテンペスト」のリーダーであり、メンバーの一人である。ホシミ私立高校に通っており、イメージカラーはダークブルー。長瀬麻奈の妹にあたる。 クールな外見とは裏腹に、琴乃は秘めた情熱を持つ新人アイドルである。 琴乃は、深い後悔を抱えながら戦う孤独なアイドルだ。彼女は人付き合いがあまり得意ではなく、もともと友達が多いタイプではなかったが、数年前の出来事をきっかけに、人との関係を断ち切り始めてしまった。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b153565-d1Bs3f09hsKd.png', '12月25日', NULL, '橘美來', 162, 153565, 'MAIN', 135) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021850', 'AN1953', '白石千紗', '白石千紗は、ホシミプロダクション所属のグループ「サニーピース」のメンバーです。光ヶ崎高校に通っており、イメージカラーはライトピンクです。白石沙季の妹です。  千紗は、いつも姉の沙季の後ろに隠れているような、内気な女の子です。姉に守られて育ったため、姉とは対照的に内向的な性格になりました。その殻を破り、自身のコンプレックスを克服するために、彼女は事務所のドアを叩いたのです。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b153568-Osokub5bi4iR.png', '11月22日', NULL, '高尾奏音', 147, 153568, 'MAIN', 38) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021851', 'AN1953', '川咲さくら', '川咲さくらは、ホシミプロダクション所属のグループ「サニー・ピース」のリーダーであり、メンバーの一人です。光ヶ崎高校に通っており、イメージカラーはオレンジです。  さくらさんは、平凡な日々を大切にする純真な少女です。人を惹きつける魅力があり、直感に従って衝動的に決断を下すこともよくあります。過去の経験から人の心の微妙な変化を察知することができ、誰に対しても優しく寄り添うことができます。また、マナさんと同じ歌声を持っています。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b153566-MYnBXPq4VtaR.png', '4月3日', NULL, '菅野真衣', 156, 153566, 'MAIN', 83) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021852', 'AN1953', '早坂芽衣', '早坂芽衣は、ホシミプロダクション所属のグループ「月のテンペスト」のメンバーです。ホシミ私立高校に通っており、イメージカラーは赤です。  メイは好奇心旺盛な少女で、直感に従って行動し、誰に対しても臆することなく近づいていく。運動神経が良く、パフォーマンスの腕前も抜群だ。その明るく親しみやすい性格で、周囲を和ませることが多い。猫が大好きで、道端の野良猫とよく遊んでいる。', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b153574-OdhxSDoNl0Cs.png', '7月7日', NULL, '日向もか', 157, 153574, 'MAIN', 125) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021853', 'AN1953', '佐伯遙子', '佐伯遙子は、星見プロダクション所属のグループ「サニー・ピース」のメンバーです。西陽私立大学の学生で、イメージカラーは薄紫です。 彼女は、いつも笑顔を絶やさない、自然体で気前の良いお姉さんタイプです。 彼女は常に周囲に気を配り、陰から友人を支え、その場の雰囲気を明るくしています。地味な外見や、10人のメンバーの中で最年長であることにコンプレックスを抱いています。 一見すると、H', 20, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b153573-kCQvcR0pzb9f.png', '1月3日', NULL, '佐々木奈緒', 163, 153573, 'MAIN', 31) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021854', 'AN1953', '成宮すず', '成宮すずは、星見プロダクション所属のグループ「月のテンペスト」のメンバーです。彼女はウルハ女子私立学校の中学校に通っており、イメージカラーは黄色です。すずは自信家でありながら不器用で、からかわれやすい少女です。 生意気で元気いっぱいの態度を見せる一方で、アイドルに対する無邪気な一面もあり、そのドジなところも相まって、憎めない存在として周囲から温かく慕われている。彼女は、自身の悩みから逃れるために星見プロダクションを訪れている。彼女は', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b153572-ScG93EOtYMkt.png', '9月13日', NULL, '相川奏多', 142, 153572, 'MAIN', 36) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021855', 'AN1953', '伊吹渚', '伊吹渚は、星見プロダクション所属のグループ「月のテンペスト」のメンバーです。星見私立高校に通っており、イメージカラーはピンクです。親友の長瀬琴乃を支えるためにアイドルになった、優しい女の子です。明るい笑顔で周囲の人々を温かく包み込みます。 穏やかで献身的な性格で、困っている人をよく支えている。琴乃の正直さに惹かれ、二人は親友になった。琴乃のこととなると、他人に遠慮なく自分の意見を述べることもある。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b153570-UOwZL2Xt6Z16.png', '8月3日', NULL, '夏目ここな', 154, 153570, 'MAIN', 28) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021856', 'AN1953', '兵藤雫', '兵藤雫は、ホシミプロダクション所属のグループ「サニー・ピース」のメンバーです。光ヶ崎高校に通っており、イメージカラーはパステルグリーンです。雫は物静かな女の子で、影からこっそりとアイドルを応援する「陰のファン」です。 しかし、アイドルの話になると、彼女はとてもおしゃべりになる。彼女はアイドルファンの世界では有名人で、年上で経験豊富なファンたちからも注目されている。豊富な知識を活かしてアイドル活動に励んでいるが、一方で……', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b153571-nQT3k6GiCjxX.png', '10月15日', NULL, '首藤志奈', 150, 153571, 'MAIN', 46) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021857', 'AN1953', '長瀬麻奈', '長瀬麻奈は、星見プロダクション所属のソロアイドルです。長瀬琴乃の姉であり、イメージカラーはピンクです。星見市で育ち、星見中学校と星見私立高校を卒業しました。 高校在学中にアイドルデビューし、学生時代には文化祭などでパフォーマンスを披露していた。マナは、ただそこにいるだけで周囲の皆を笑顔にしてくれるアイドルだ。彼女は、手の届かないようなスター性を持つ、稀有な存在の一人だが、', 19, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b164062-Kgq43ebXunWw.png', '10月9日', NULL, '神田沙也加', 158, 164062, 'MAIN', 179) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021858', 'AN1953', '白石沙季', '白石沙季は、ホシミプロダクション所属のグループ「月のテンペスト」のメンバーである。ホシミ私立高校の生徒会長を務めており、イメージカラーはティール色だ。 彼女は白石千紗の姉である。サキは、成績優秀な模範生そのものであり、妹の千紗のことを常に気遣いながら真面目に生きてきた。彼女は学校の生徒会長を務めており、優等生としての生活から抜け出すために、初めてアイドルの世界に飛び込んだ。', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b153569-LmR9ARYCyAx2.png', '9月26日', NULL, '宮沢小春', 160, 153569, 'MAIN', 26) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021859', 'AN1953', '一ノ瀬怜', '一ノ瀬怜は、ホシミプロダクション所属のグループ「サニー・ピース」のメンバーです。ウルハ女子私立学園の高校生で、イメージカラーは水色です。  レイは、ダンスが大好きな高校3年生だ。上達への強い意欲を持ち、誰よりも負けを嫌う。その情熱のあまり、周囲には攻撃的だったり押し付けがましく見えたりすることもあり、他人にも自分と同じレベルの努力を求めるため、しばしば衝突を引き起こしてしまう。', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b153567-20VRsN56CG3u.png', '3月8日', NULL, '結城萌子', 160, 153567, 'MAIN', 131) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021860', 'AN1953', '牧野航平', '牧野航平は、ホシミプロダクションのアイドル担当マネージャーで、長瀬麻奈と同い年である。彼は「ノー」と言えないほどお人好しだ。特段の才能はないが、誠実な働きぶりでアイドルたちを支えている。  彼は長瀬麻奈と同じ高校に通っており、彼女とは親しい友人だった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b195982-jZya97U4HMnf.png', NULL, NULL, '石谷春貴', NULL, 195982, 'MAIN', 32) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021861', 'AN1953', '神崎莉央', '神崎莉央は、IDOLY PRIDEのユニット「LizNoir」のセンターであり、メンバーの一人です。彼女のイメージカラーは紫です。リオは、アグレッシブなスタイルと飽くなき勝利への渇望を持つ、LizNoirの絶対的なセンターです。 活動休止を経て復帰した彼女は、ある人物との縁を断ち切るために戻ってきた。最強の決意を胸に、アイドル業界の頂点に立つことを目指している。', 22, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b202847-kk1VIdId7bE8.png', '8月28日', NULL, '戸松遥', 160, 202847, 'SUPPORTING', 36) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021862', 'AN1953', '赤崎こころ', '赤崎こころは、ユニット「IDOLY PRIDE」の「LizNoir」のリーダーであり、メンバーの一人である。うるは女子私立学校の中学校に通っており、イメージカラーはピーチだ。  こころは、LizNoirの親しみやすく礼儀正しいキャプテンです。時折見せる厳しい物腰のせいで、本心が読み取りにくいところがあります。小美山愛とは互いに受け入れ合っていますが、悪い知らせを察知しがちです。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b202844-G1kW9XYoPvbY.png', '12月6日', NULL, '豊崎愛生', 153, 202844, 'SUPPORTING', 24) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021863', 'AN1953', '奥山すみれ', '奥山すみれは、IDOLY PRIDEのユニット「TRINITYAiLE」のメンバーです。紅花中学校の生徒で、イメージカラーは淡い黄色です。すみれはかつて子役として活躍していましたが、今では中学生として成長したようです。 山形県の実家から通学しているが、これまでの苦労を苦にせず、いつも笑顔を絶やさない。普段は中学生らしい心持ちだが、油断すると子供っぽい口調で話してしまう傾向がある。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b153655-yaNuEzk8RTef.png', '5月5日', NULL, '夏川椎菜', 147, 153655, 'SUPPORTING', 16) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021864', 'AN1953', '井川葵', '井川葵は、ユニット「LizNoir」のメンバーです。月ノ出私立高校に通っており、イメージカラーは青です。  葵は「LizNoir」の頭脳的存在であり、常に冷静で、感情の起伏が少ない。物事を率直に表現するが、クールな態度をとることが多い。神崎莉央のことを誰よりも理解している人物であり、デビュー前から莉央と共に苦難を乗り越えてきた。', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b202845-cpOK0eRQ39b4.png', '6月19日', NULL, '高垣彩陽', 157, 202845, 'SUPPORTING', 36) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021865', 'AN1953', '天動瑠依', '天動瑠依は、ユニット「TRINITYAiLE」のリーダーであり、絶対的なセンターを務めるメンバーです。月ノ出私立高校に通っており、イメージカラーは白です。  ルイは、ダンス、歌唱、パフォーマンスのあらゆる面で卓越した才能を持つ天才アイドルだ。しかし実際には、圧倒的な努力に裏打ちされた確かな実力者である。誰かに認められるために、たとえ困難な状況にあっても、決して前進を止めない。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b153656-9ZsA6YHqpNB0.png', '11月11日', NULL, '雨宮天', 165, 153656, 'SUPPORTING', 31) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021866', 'AN1953', '小美山愛', '小美山愛は、ユニット「IDOLY PRIDE」の「LizNoir」のメンバーです。月ノ出私立高校に通っており、イメージカラーはスカイブルーです。  愛は人を笑顔にすることが大好きで、「LizNoir」のモッド制作担当です。技術力には長けていますが、肝心な場面ではとてつもなく不器用です。冗談の意図が相手に伝わりにくく、自分の直感を信じすぎてしまう傾向があります。', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b202846-vkedlthSFQQ7.png', '2月9日', NULL, '寿美菜子', 164, 202846, 'SUPPORTING', 18) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021867', 'AN1953', '鈴村優', '鈴村優は、IDOLY PRIDEのユニット「TRINITYAiLE」のメンバーです。月ノ出私立高校に通っており、イメージカラーはライムグリーンです。  優は京都出身で、TRINITYAiLEでは常に落ち着いて振る舞っている。父親は大企業の社長で、母親は有名な女優である。彼女は天動瑠依に魅了されている一人であり、常に瑠依の要望を自分のことよりも優先している。', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b153657-uxxG3pvRWFqj.png', '2月27日', NULL, '麻倉もも', 155, 153657, 'SUPPORTING', 23) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021868', 'AN1953', '朝倉恭一', 'ヴァン・プロダクションズの代表。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b205377-ABwqZhWk4atx.png', NULL, NULL, '速水奨', NULL, 205377, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021869', 'AN1953', '三枝信司', '三枝信司は、ホシミ・プロダクションの社長だが、以前は大手企業のヴァン・プロダクションに勤務していた。その後、独立してホシミ市に自身の会社を設立した。彼にはどこかよそよそしい雰囲気があるが、並外れて独特なオーラを放っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b195981-0v3lcjhNE3bD.png', NULL, NULL, '小山力也', NULL, 195981, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
