INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021925', 'AN1956', '味方正嗣', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/default.jpg', NULL, NULL, '土岐隼一', NULL, 399214, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021926', 'AN1957', '秋月ショウ', '知性と運動能力に恵まれ、おとぎ話の王子様にも引けを取らない神々しいルックスに加え、礼儀正しさと穏やかな物腰も兼ね備えている。サーフィンに完全に夢中であり、その腕前も抜群で、いつか国際大会で日本代表として出場することを目指している。家庭環境は複雑だが、美しい母親を深く愛している。  （出典：Anime News Network）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158179-HYlu0RibLOAz.png', '9月24日', NULL, '小笠原仁', NULL, 158179, 'MAIN', 149) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021927', 'AN1957', '松風ユータ', '物事を分析し、視覚化し、そして効率的に改善することに喜びを見出す少年。両親はサーフショップを経営しており、彼も当然のことながら幼い頃からサーフィンを続けてきた。彼は、その厳密な分析力を予測不可能なサーフィンの世界に持ち込めば、このスポーツに革命を起こせると信じている。  （出典：Anime News Network）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158182-S7J6ijBN0zqF.png', '2月7日', NULL, '白井悠介', NULL, 158182, 'MAIN', 27) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021928', 'AN1957', '木戸ナオヤ', '木戸ナオヤは、生粋の田舎っ子であり、生粋のオタクでもある。そのオタクぶりは、深夜アニメが放送される当日に見逃してしまうのではないかと常に心配しているほどだ。   田舎では他にやることがないためサーフィンをしていたが、ある大会に参加した際、大都市に行けば実際にアニメを観られることに気づいて以来、サーフィンに非常に熱心になり、やがてかなりの腕前を身につけた。彼は自身の技法を「中二病」と呼んでいる。（出典：Anime News Network）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158183-AoxkGoIsioA0.png', '4月22日', NULL, '土岐隼一', NULL, 158183, 'MAIN', 110) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021929', 'AN1957', '田中ナル', '父親は地球物理学者兼研究者の日本人、母親は自由奔放なハワイ出身の女性という家庭に育った少年。   彼はヒナオカ家の家族ぐるみの友人であり、幼い頃からマサキと親しい間柄だ。サーフィンもウクレレも大好きで、学校に行く前には必ず波に乗っている。ショウがやってきてマサキがサーフィンを始めて以来、3人は早朝に起きてサーフィンをするようになった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158180-QXUbkI8fg1Ot.png', '7月16日', NULL, '中島ヨシキ', NULL, 158180, 'MAIN', 217) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021930', 'AN1957', '厳名コウスケ', '湘南でサーフィンに夢中になった真面目な青年。元は野球選手だったが、肘の怪我によって野球への夢は断たれてしまった。サーフィンとその奥深さを知った彼は、その魅力にすっかり魅了された。現在はトップサーファーを目指しており、練習を一日も欠かしたことがない。   ユタと知り合って以来、彼は彼を深く信頼している。  （出典：Anime News Network）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158181-BismVGFrmagi.png', '8月1日', NULL, '佐藤拓也', NULL, 158181, 'MAIN', 55) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021931', 'AN1957', 'フケ倫道', '彼は日本最高のサーファーとして知られている。   彼の視線は常に、普通の人には想像もつかない遥か彼方の地平線へと向けられている。彼は驚異的な集中力を持ち、トップクラスのトレーニングと完璧に鍛え上げられた肉体によって生み出されるそのサーフィンの姿は、見る者を圧倒する。 彼は、サーフィン界の王として、独自の美意識に従って人生を歩んでいる。（出典：Anime News Network）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158187-qXMTKQIkKvLQ.png', '11月30日', NULL, '岡本信彦', NULL, 158187, 'MAIN', 108) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021932', 'AN1957', 'ウィリアム・森・聡一郎', '世界有数の富豪一家の出身である。彼は心からサーフィンを愛しており、サーフィンを愛する人々もまた愛している。才能と将来性のあるサーファーたちには、惜しみない支援を惜しまない。彼はフケのサーフィン界での活躍を後押ししており、フケを通じて自らの夢を実現したいと考えている。  （出典：Anime News Network）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158188-frEF0xcJjXbp.png', '6月9日', NULL, '森久保祥太郎', NULL, 158188, 'MAIN', 109) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021933', 'AN1957', '陽岡マサキ', '大洗で生まれ育った、ポテトチップスが大好きな若者。転校生のショウと仲良くなり、彼の趣味に付き合った。その結果、サーフィンを始めることになった。バランス感覚に優れ、上達も著しいが、実は泳ぎはまったくの初心者だ。   泳ごうとすると、水中のコーギーに例えられることが多い。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158178-9P5WPuyxm5UX.png', '5月10日', NULL, '前野智昭', NULL, 158178, 'MAIN', 79) ON CONFLICT DO NOTHING;
