INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021949', 'AN1959', 'オーフェン', '髪色：茶色　瞳の色：茶色　身長：171 cm　体重：61 kg　オーフェンは男性主人公です。 ファンからは、「感情を表に出さないこと」「手掛けたことはできるだけ早く終わらせようとする姿勢（助けなくてもよいと感じる相手への援助をためらう様子）」「見知らぬ人に対する『冷たさ』」などから、「『ワルっぽい』男」という印象を受けると評されている。 彼はシリーズ全体を通して、ある意味でアンチヒーロー的な存在である。彼の態度が変わる唯一の時は、アザリーの話が出たときだけである。', 20, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n1411-dKMaZJPRUXLW.jpg', NULL, 'O', '森久保祥太郎', 171, 1411, 'MAIN', 87) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021950', 'AN1959', 'クリーオウ・エバーラスティン', '彼女は、おてんばで気性の激しいヒロインだ。彼女の父親は「バルタンダースの剣」を相続していたが、オーフェンはその剣を必要としていた。 彼女はオーフェンの旅に同行し、その剣を彼に譲る（彼女にとっては単なる装飾品に過ぎず、その力については何も知らなかったため）、自分は「自分の投資が損なわれないように見張るため」に同行しているだけだと主張する。（出典：ウィキペディア）', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b5758-qqcFHAAlNEQI.png', '9月27日', NULL, '大久保瑠美', NULL, 5758, 'MAIN', 37) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021951', 'AN1959', 'マジク・リン', 'マジク・リンはオーフェンの弟子であり、第二の男性主人公である。マジクは、アザリーを救うための旅の途中、クレオとオーフェンの両方から苦痛を強いられる。彼の父親はオーフェンに報酬を支払ってマジクを指導させているが、当初、父親にとっては金の無駄遣いに思えていた。 しかし、オーフェンが父親の目の前で、魔法を使って落ちてしまったガラスを修復したことで、父親の「金を無駄にしている」という考えは消え去った。（出典：ウィキペディア）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b5656-DgU1N9wT0ury.png', '3月25日', NULL, '小林裕介', NULL, 5656, 'MAIN', 15) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021952', 'AN1959', 'アザリー・ケットシー', '彼女はオーフェンの義理の妹であり、親友であり、「ブラッディ・オーガスト」でもある。二人は同じ孤児院で育ち、魔法の天才と見なされて共に「牙の塔」へとやって来た。彼女はオーフェンに多くのことを教え、特別な配慮を注いでいた。彼女は偉大な魔術師であり、おそらく史上最高の魔術師の一人だった。 しかし、彼女には二面性があった。優しくて愛情深いアザリーと、オーフェンが言うところの「恐ろしい」アザリーだ。ある人物への告白を拒まれた後、彼女は学業にほとんど執着しているかのように見え、彼女は……', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b9685-Vayp0r3pJsBG.png', NULL, NULL, '日笠陽子', NULL, 9685, 'MAIN', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021953', 'AN1959', 'ハーティア・アーレンフォード', 'オーフェンの幼なじみであり、同じく魔術師である。二人はファングの塔で出会った。しかし、彼はオーフェンではなくチャイルドマンの側に立っているため、まるでハルティアがオーフェンの敵であるかのように思われてしまう。 しかし、ハルティアはオーフェンのことを心から気にかけており、二人の友情を決して忘れてはいない。（ウィキペディアより）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/5759.jpg', NULL, NULL, '坂泰斗', NULL, 5759, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021954', 'AN1959', 'チャイルドマン・パウダーフィールド', 'オーフェン、ハルティア、そしてアザリーの師匠。アニメの大部分において、オーフェンにとっての主要な敵役となっている。オーフェンは、チャイルドマンが本当にアザリーを殺そうとしていると信じ込んでいるからだ。ハルティアは、チャイルドマンがオーフェンの敵ではないと説得しようとするが、結局それは失敗に終わる。 実際には、彼はアザリーに降りかかった悲劇に対して個人的な責任を感じていたため、自らアザリーを復活させるために3つの護符を手に入れようとしていたのだ。そしてある時点で事態はさらに悪化し、彼が「ブラッディ・オーガスト」に立ち向かおうとした際、アザリーは……', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/40254.jpg', NULL, NULL, '浪川大輔', NULL, 40254, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021955', 'AN1959', 'フォルテ・ パッキンガム', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b153415-OeJbiw8VQufg.png', NULL, NULL, '前野智昭', NULL, 153415, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021956', 'AN1959', 'メッチェン', 'メッチェンは、盗賊団の一員である女剣士だ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b185454-3dS0kjdMtqCR.png', NULL, NULL, '鬼頭明里', NULL, 185454, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
