INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021959', 'AN1959', 'ボルカン', 'ドーチンとボルカンは、シリーズを通じてしばしばコメディリリーフとして描かれています。ボルカンは計画を立てる側ですが、その計画は――実にひどいものばかりです。 彼はオーフェン（彼を「黒魔道士」と呼んでいる）とその仲間たちを憎んでおり、彼らが企てたことは何でも台無しにする方法を見つけ出す。 また、彼はオーフェンにとって非常に厄介な存在だ。オーフェンが彼ら――つまりボルカンとドーチン――を追い払うために、しばしば魔法を使わざるを得なくなるのは、すべて彼のせいである。ボルカンは権力と金を欲している。彼が企むどんな計画も、その結末は', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/1406.jpg', NULL, NULL, '水野まりえ', NULL, 1406, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021960', 'AN1959', 'イスターシバ', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b229300-s4kpVR1LyJ79.png', NULL, NULL, '井上喜久子', NULL, 229300, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021961', 'AN1959', 'ドーチン', 'ドーチンは、彼とボルカンの冒険において（決して聞き入れられることのない）良識の代弁者である。 彼は親切で知識も豊富だが、少々オタク気質だ。ボルカンが失敗すると、ドーチンはいつもオーフェンに「自分はボルカンの企みには一切関与していない」と説明しようとするが、結局二人ともオーフェンの魔法の爆風を浴びてしまうことになる。（ウィキペディアより）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b1407-T2MBA450E3Zm.png', NULL, NULL, '渕上舞', NULL, 1407, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
