INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021963', 'AN1959', 'レキ', 'レキは『ソーサロス・スタバー オーフェン』に登場する脇役である。ディープドラゴンであるレキは、黒い毛並み（1998年のアニメ版では青色）と緑色の目を持つ、狼のような姿をしている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b214763-j3jVm8oim6gg.png', NULL, NULL, NULL, NULL, 214763, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021964', 'AN1959', 'ネイム・オンリー', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b316612-IlBzC4r2u0Sm.jpg', NULL, NULL, '子安武人', NULL, 316612, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021965', 'AN1960', '滝沢あすか', 'アスカは、正義感が強く、スポーツ万能な中学3年生です。一見すると威圧的で近寄りがたい印象ですが、実は頼りになるお姉さんタイプです。実は、料理をしたり、かわいい動物のゲームをしたりするのが大好きです。キュアフラミンゴはアスカのプリキュアとしての別名で、彼女の魅力は髪にあります。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b201327-c1W2i8WKSHqz.png', '10月15日', NULL, '瀬戸麻沙美', NULL, 201327, 'MAIN', 83) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021966', 'AN1960', '夏海まなつ', 'Manatsu is an extremely energetic and motivated first year middle school student who moved from Minamino Island to Aozora City. She always acts before she thinks, and her motto is "I''ll do what''s important right now!". Her most precious item is the lipstick her mother gave her.  Cure Summer is Manatsu''s Pretty Cure alias. Her catchphrase is "Tropica-Shine!" (トロピカってる～！)', 13, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b201328-80QpVg8YxQ7z.jpg', '8月1日', NULL, 'ファイルーズあい', NULL, 201328, 'MAIN', 121) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021967', 'AN1960', '涼村さんご', 'サンゴは、かわいいものが大好きな、おしゃれな中学1年生です。とても親切で、誰とでも仲良くできます。家族が美容院を経営しているため、メイクや化粧品について詳しいです。キュアコーラルはサンゴのプリキュアとしての別名で、彼女のチャームポイントは頬です。  （出典：プリキュアWiki）', 13, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b201333-TKiQQksecbEO.png', '5月9日', NULL, '花守ゆみり', NULL, 201333, 'MAIN', 101) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021968', 'AN1960', 'くるるん', 'Kururun is a seal-like sea fairy from the Grand Ocean, and is the current Queen''s pet. Their cry is "Kururun!" (くるるん～！). They are calm and prefer to act at their own pace. They love to eat their favorite snack: a shell-shaped cookie!', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b201329-Z1NZ1dTqXBtW.png', '9月6日', NULL, '田中あいみ', NULL, 201329, 'MAIN', 86) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021969', 'AN1960', 'ローラ・アポロドーロス・ヒュギーヌス・ラメール', 'ローラは「グランドオーシャン」出身の人魚で、歌に情熱を注ぎ、次期女王になることを夢見ている。その夢を叶えるため、ローラは伝説の戦士たち「プリキュア」を見つけ集め、故郷を現在の脅威から救い出すことを決意した！ 彼女は青空シティへと旅立ち、そこで同い年の少女・真夏と出会い、真夏やその仲間たちと一緒にこの街で暮らすことを決める。彼女は自信に満ち、物事を論理的に考える人魚で、言いたいことは何でも恐れることなく口にする。', 13, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b201330-SBhmyFpwRV04.png', '6月30日', NULL, '日高里菜', NULL, 201330, 'MAIN', 214) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021970', 'AN1960', '一之瀬みのり', 'ミノリは、読書が大好きな頭の良い中学2年生です。クラスで一番の成績を誇る優等生です。表情が読みにくい性格のため、感情を表に出すのが苦手です。 しかし、彼女には確固たる自己意識がある。幼い頃から童話『人魚姫』が大好きで、人魚に関する物語をたくさん知っている。キュアパパイヤはミノリのプリキュアとしての別名であり、彼女のチャームポイントは目だ。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b201332-j99CCXtJW8ef.jpg', '11月21日', NULL, '石川由依', NULL, 201332, 'MAIN', 55) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021971', 'AN1960', 'メルジーヌ・ミューゼス・ムネモシュネ', '人魚の女王。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b210107-Gj4OBMvNgpja.png', NULL, NULL, '佐々木優子', NULL, 210107, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021972', 'AN1960', '白石きりこ', '夏美の同級生', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b211158-2N74Rjokuaf0.png', NULL, NULL, '弘松芹香', NULL, 211158, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021973', 'AN1960', '桐島秋穂', '青空中学校を卒業。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b216683-NIvGe3fOWwjB.png', NULL, NULL, NULL, NULL, 216683, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021974', 'AN1960', '花咲つぼみ', '彼女は明道学園の2年生の編入生で、エリカと同じクラスに所属している。ツボミのもう一つの姿はキュア・ブロッサムだ。 ツボミは内気で臆病な性格で、普段は一人でいることが多く、自分から話しかけられない限り、積極的に話すことをためらってしまう。些細なことで心配したり、動揺したりすることが多く、特に怖がったり、エリカのような活発な相手と接したりする時はなおさらだ。彼女はこうした自分の一面を脱却したいと強く願っており、物語が進むにつれて、より気楽で前向きな性格になっていく。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b29507-XOob6fAPOzWl.png', NULL, NULL, '水樹奈々', NULL, 29507, 'SUPPORTING', 263) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021975', 'AN1960', '一之瀬なるみ', 'ナルミはミノリの母親です。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b370900-yIxnz7ZdjqAs.png', NULL, NULL, '高橋美佳子', NULL, 370900, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
