INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021977', 'AN1960', 'バトラー', '「遅延の魔女」のためのバトラー。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b210108-CeDVJDKuAY0c.jpg', NULL, NULL, '小松史法', NULL, 210108, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021978', 'AN1960', 'ヤラネーダ', 'ヤラニーダは、憑依した相手の体を持ち、顔の横に魚のようなえらがあり、その表情からはやる気がないように見える。 ターゲットの「モチベーションパワー」を奪うと、その目は赤く輝き、不気味な笑みを浮かべる。誰のモチベーションでも奪う能力を持ち、ターゲットを何もしようという気になれなくさせ、自らの力を増強する。ただし、プリキュアには効果がないようだ。（出典：プリキュアWiki）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b211159-7c9tS5d2NJOU.png', NULL, NULL, '三日尻望', NULL, 211159, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
