INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022005', 'AN1960', '来海えりか', 'エリカはツボミの同級生であり隣人であり、ファッションショップ「フェアリー・ドロップ」のオーナーの娘である。また、ファッション部の部長も務めている。ファッションが大好きで、自分で服をデザインすることも好んでいる。 高校在学中にもかかわらず「カリスマモデル」として活躍する、美しくおしゃれな姉に対して、嫉妬心を抱いている。元気いっぱいの女の子で、思ったことは率直に口にするが、ツボミと出会ったことをきっかけに、少しずつ変わっていき始める。彼女はツボミをファッションクラブに誘い、', 13, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b29699-ypkICccTVFjc.png', '5月26日', NULL, '水沢史絵', NULL, 29699, 'SUPPORTING', 327) ON CONFLICT DO NOTHING;
