INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022011', 'AN1960', '明堂院いつき', '彼女は明道学園の2年生であり、生徒会長も務めている。イツキのもう一つの姿はキュア・サンシャインだ。そのイメージや育ちにもふさわしく、イツキは賢く気品のある若い女性で、他人に対しては常に礼儀正しく接する。 彼女は穏やかで親切な性格で、友人だけでなく見知らぬ人に対しても進んで手を差し伸べるが、必要な時には厳格な一面も見せ、自分より弱い立場の人を守るためなら躊躇なく立ち向かう。勇敢で思いやりのある彼女だが、それゆえに、その力を解き放つことを躊躇することはない。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b32384-z6NY1hYEe2hQ.jpg', NULL, NULL, '桑島法子', NULL, 32384, 'SUPPORTING', 145) ON CONFLICT DO NOTHING;
