INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022039', 'AN1962', '竹崎宏和', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b197276-WegZhIMHeW5r.png', NULL, NULL, '鳥海浩輔', NULL, 197276, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022040', 'AN1963', '湊奏多', '愛らしい雰囲気を持つ少年。幼い頃からCMやドラマに出演してきたため、芸能業界には慣れ親しんでいる。カナタは、「ラビrabi」という名前のウサギのぬいぐるみをいつも持ち歩いていることで知られている。恥ずかしがり屋な一面もあるが、親しい人に対しては親しみやすい。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b165220-By5xl5Qv1ozB.jpg', NULL, NULL, '井口祐一', NULL, 165220, 'MAIN', 26) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022041', 'AN1963', '御剣晃', 'アキラは大人びた外見で、謎めいた印象を与える。そのため、当初はモデルと見なされていた。 アキラは所属ユニットの「お兄ちゃん」として知られている。彼はいつもセイヤの面倒を見ており、カナタには非常に情が厚く、よくカナタを膝の上に座らせたりしているほどだ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b165221-VotM8iI8AH9k.png', NULL, NULL, '豊永利行', NULL, 165221, 'MAIN', 68) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022042', 'AN1963', '愛童星夜', 'いつも未来を見据えている、明るく前向きな少年。アメリカで育ち、小学生の頃に日本へやって来た。日本が大好きで、よく日本の小物を集めている。竜胆椿は彼が憧れる先輩であり、ノアはアメリカ時代の幼なじみだ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b165222-ZMvYzHY5LPSw.png', NULL, NULL, 'KENN', NULL, 165222, 'MAIN', 29) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022043', 'AN1963', 'レオン', 'いつも動き回っていて、じっとしていられない元気な少年。大胆な印象を与えようと、出会った人なら誰とでも仲良くなろうとする。女の子を見かけると、すぐに声をかける。イギリスからの転校生だ。彼とリュカはよく口論になり、そのたびにラビに叱られることになる。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b165228-QwyxRMludmzF.jpg', NULL, NULL, '増田俊樹', NULL, 165228, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022044', 'AN1963', '朝比奈柚希', 'I-Chuのメンバーたちを本格的なアイドルに育てるため、日々懸命に努力しているプロデューサー。プロデューサーとしてだけでなく、アカデミーの講師としても活躍している。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b165241-l6GJfxk5V1Fv.png', NULL, NULL, '豊口めぐみ', NULL, 165241, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022045', 'AN1963', '赤羽根双海', '二見はニートとして怠惰な生活を送っていることで知られている。そのため、高校時代の同級生である轟一誠と三千院鷹通に、芸能界へと引きずり込まれてしまった。 彼の家族は生け花[1]流派の家元であるため、生け花は彼の得意分野だ。しかし、両親は彼に対して非常に厳しい基準を課していた。そのため、彼は家を出てニートとして暮らしていた。二見はプロデューサーと切っても切れない関係にあり、よく彼女に食事をご馳走してもらっている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b197936-U41TWKGRCDAI.png', NULL, NULL, '内田雄馬', NULL, 197936, 'SUPPORTING', 17) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022046', 'AN1963', 'ラビ', 'グループの仲介役。他の誰よりもグループのことを深く気にかけている。元不良だが、優しいお兄さんのような印象を与える。一見普通に見えるが、以前はヘヴィメタルのライブをやっていた。 ロシアからの転校生だ。竜胆椿とは気が合い、よく二人で長々と話している。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b165229-YRncnMm1yEXL.png', NULL, NULL, '中西尚也', NULL, 165229, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022047', 'AN1963', 'クマ校長', '同社のフランス人社長。かつてはすごいアイドルだったらしい。身長は190cmだ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b165242-2rtijmZvuyxY.png', NULL, NULL, '大塚明夫', NULL, 165242, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022048', 'AN1963', '轟一誠', '一成は昔から問題児で、今でも悪党たちとつるむ傾向がある。一人になるのが嫌いなため、高校時代から仲の良い赤羽根双海や三千院鷹通と一緒にいる姿をよく見かける。 ふたりと鷹通と一緒にいるときは普段、警戒心を解いているが、他の人に対してはかなり威圧的な態度をとる。プロデューサーとは切っても切れない関係にあるため、一成は彼女に対してはより優しく、気さくに接している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b197937-uSUpEc5shdM2.png', '5月5日', NULL, '前野智昭', NULL, 197937, 'SUPPORTING', 15) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022049', 'AN1963', '若王子楽', '折原輝の幼なじみ。幼い頃から、よく輝をからかっていた。常に上から目線の男で、興味がないことには関心を示さず、何もしようとしない。 数々の賞を受賞している書家だ。最も風変わりなアイドルだが、本気を出せば何でもこなせる。御剣晃とは、落ち込んだ時に一緒に飲みに行くほど親しい間柄だ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b165234-CDGOVlN84ycM.jpg', NULL, NULL, '平川大輔', NULL, 165234, 'SUPPORTING', 14) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022050', 'AN1963', '華房心', '自分が最高だと信じている、意志の強いアイドル。その驚くべき行動がファンの心を掴んでいる。彼は、男の子としてでも輝いているが、女の子として自分を表現した時には、さらに輝けると思っている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b192610-ljGTpKwmtqF0.png', '9月1日', NULL, '村瀬歩', NULL, 192610, 'SUPPORTING', 65) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022051', 'AN1963', '三千院鷹通', '高道は内気な性格のせいで、普段は厳しい表情を浮かべている。とはいえ、彼はいたずら好きで、おちゃめな一面もある。感情が顔に出やすいため、よくからかわれる。特に一成によくからかわれる。 高道は裕福な家庭の出身であるため、礼儀正しく振る舞い、上品な話し方ができる。彼の家族と十文字蛮の家族は交流があるが、彼には知人があまりおらず、蛮も自分と同じ世代であるため、彼は', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b197938-xRarqUwJedWp.png', NULL, NULL, '白井悠介', NULL, 197938, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022052', 'AN1963', '枢木皐月', 'いたずら好きな少年。兄へのコンプレックスのせいで、いつも兄にべったりとまとわりついている。 正直な性格で、感情を隠さず表に出してしまう傾向がある。プロデューサーにいたずらを仕掛けるが、彼女はいつもそれをかわしてしまうため、彼はイライラしている。鳶倉アキヲの反応が一番面白いので、彼はいつも彼をターゲットにいたずらを仕掛けている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b165223-R2piysgJpDkh.png', '1月1日', NULL, '森久保祥太郎', NULL, 165223, 'SUPPORTING', 17) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022053', 'AN1963', '鳶倉アキヲ', '子供っぽくて陰気な引きこもり。4人の姉に囲まれて育ったため、女性に対して恐怖心を抱くようになった。ガラスエッチングのきらめきが芸術の中で一番のお気に入りであり、ヒカルが作った氷の彫刻のきらめきも大好きだ。京介の不器用さが引き起こすトラブルに、よく巻き込まれてしまう。 最近は、枢木皐月の悪戯に巻き込まれないよう、こっそりと隠れて過ごすようになった。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b165236-xKgjLVnCUzjK.png', NULL, NULL, '田丸篤志', NULL, 165236, 'SUPPORTING', 30) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022054', 'AN1963', '及川桃助', 'ふわふわした見た目の可愛い男の子で、癒しのオーラを漂わせている。ココロに無理やり業界に引きずり込まれてアイドルになったが、まだ女の子の服を着ることに慣れていない。ココロから、彼の特徴としてぬいぐるみを持ち歩くように言われた。 本名の「モモスケ」と呼ばれるのが嫌いで、自己紹介の際は単に「モモ」と名乗ることを好んでいる。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b197931-AiMnVJRXf6DT.png', NULL, NULL, '山本和臣', NULL, 197931, 'SUPPORTING', 18) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022055', 'AN1963', '杜若葵', '普段は爽やかな表情を浮かべているが、仕事となると非常に真剣な表情になる。女性に対しては親切で紳士的だが、男性に対してはかなり冷淡だ。特に辰巳マダラオに対してはそうである。美意識が似ているため、折原輝を注視している。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b197939-EFDDNS1Wl3XF.jpg', NULL, NULL, '木村良平', NULL, 197939, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022056', 'AN1963', 'ノア', '滑らかな肌と絹のような髪を持つ、気品あふれる男性。アメリカ生まれで、幼少期を「愛童星夜」と共に過ごした。羊の皮を被った狼のように、二面性があることで知られている。裕福で社交的な家庭の出身だ。 I♥Bのリーダー。怒らせると非常に恐ろしい。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b165224-gqGzdtbgYVOp.jpg', NULL, NULL, '花江夏樹', NULL, 165224, 'SUPPORTING', 23) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022057', 'AN1963', '桃井恭介', '恭介はアニメやゲームが大好きだ。気に入ったものを何でもイラストに描き、SNSに投稿している。実は、彼はエッセイ漫画家でもある。自分を含む他のアイドルたちをイラストのモデルにしているが、そのことは他のメンバーには知られていない。 一見すると物静かに見えるが、実は陽気な少年だ。デス・クロノスの風変わりな外見は、よく恭介のイラストのモデルに選ばれている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b165238-7OAHZ2bxmglw.png', NULL, NULL, '花倉洸幸', NULL, 165238, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022058', 'AN1963', '神楽坂ルナ', 'さまざまな分野で才能を発揮する、頼もしくてかわいい少年。両親が政界に携わっているため、幼い頃から礼儀作法をしっかりと教えられてきた。実は、アイドルとして活動していることを父親には隠していた。幼なじみのココロに誘われたことがきっかけで、アイドルになった。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b197932-6u6fT7Oj8i8J.png', NULL, NULL, '天崎滉平', NULL, 197932, 'SUPPORTING', 25) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022059', 'AN1963', '斑尾巽', '決意に満ちた少年。とても意志が強い反面、時には落ち込んでしまうタイプでもある。落ち込んだ時は一人でいることを好むが、寂しさを感じやすい性格のため、その状態は長くは続かない。カキツバタ・アオイとは仲が悪く、よく口論になるが、お互いの能力を認め合っている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b197940-bg1lQZbFRWft.png', NULL, NULL, '斉藤壮馬', NULL, 197940, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022060', 'AN1963', '黎朝陽', 'とても内気な少年で、他人と目を合わせて話すのが苦手だ。レオンの親しみやすい振る舞いにはいつも驚かされている。困ったときはいつもラビに助けを求める。中国からの交換留学生だ。ギルティ・クラウンとは意外なほど気が合い、よく一緒に食事に出かける。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b165225-YpVOADbF3Nr3.png', NULL, NULL, '榎木淳弥', NULL, 165225, 'SUPPORTING', 16) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022061', 'AN1963', '日下部虎彦', '自己中心的な独裁者。肖像画の依頼を頻繁に受ける有名な画家だが、実際に描くのは動物や抽象画ばかりだ。意外なことに、彼は児童文学の作家でもある。リュカがそれを知るまでは、それは秘密だった。彼はアウトドア派の芸術家であるため、絵を描くためにさまざまな国を訪れている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b165237-zPLQVWyDXIHx.jpg', NULL, NULL, '生田鷹司', NULL, 165237, 'SUPPORTING', 16) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022062', 'AN1963', '山野辺澪', 'エヴァ・アームストロングの忠実な従者。主人が行うことを崇拝しているため、ライバルに対しては傲慢な態度を取り、敵となった者に対しても冷酷に振る舞う。 「ブラッディ・マスター」の前では、主人はその演技に気づいていないものの、彼は子供のような振る舞いをしている。しかし、同じグループのメンバーである十文字蛮に対しては敵意を抱いており、その時の彼は全く別人のような態度を見せる。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b197933-dUCFoqWzL3TT.png', NULL, NULL, '柿原徹也', NULL, 197933, 'SUPPORTING', 21) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022063', 'AN1963', '竜胆椿', '高慢な兄貴分のような存在で、自分の世界と信念を厳格に貫いている。自身の能力を自覚しているため、何事にも常に自信を持っている。プロデューサーをからかうのを大いに楽しんでいる様子から、どこか「Do-S」的な一面も垣間見える。朴木十夜とは幼なじみである。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b197941-HK0aa0s16cYC.jpg', NULL, NULL, '小野友樹', NULL, 197941, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022064', 'AN1963', 'リュカ', '無口で人付き合いが苦手な男。両親は極めてのんびりとしたフランス流の生活を送っていたため、彼が成長する過程で良い手本とはなり得なかった。そのせいで彼はプレイボーイを嫌っており、その結果、彼とレオンは頻繁に口論になる。 『I♥B』の作曲家であるため、ソロ演奏は抜群に上手い。フランスからの転校生だ。日下部トーラヒコの童話の大ファンであり、時折二人で集まってその執筆について語り合うこともある。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b165227-MX6P7nYGpmOZ.jpg', NULL, NULL, '梅原裕一郎', NULL, 165227, 'SUPPORTING', 16) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022065', 'AN1963', '折原輝', '彼は、自分自身を含め（とりわけ自分自身を）、あらゆる美しいものを愛するナルシストだ。氷彫刻が彼の得意分野だが、美しいブロンズ像も手際よく作り上げることができる。彼はミケランジェロの傑作である彫像『ダビデ像』を崇拝している。 彼の将来の夢は宝塚歌劇団の出演者になることだったが、オーディションで女装していたにもかかわらず、男性であると見なされてしまい、その夢は潰えてしまった。若王子楽は彼の幼なじみであるため、彼はいつも彼を頼りにしている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b165235-hEzbnCiOO64U.png', '5月25日', NULL, '松岡禎丞', NULL, 165235, 'SUPPORTING', 15) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022066', 'AN1963', '十文字蛮', 'エヴァ・アームストロングの忠実な使用人。ある意味で罠にはめられて使用人になったのだが、楽しいので気にしない。 裕福な家庭で育ったため、お金に対する感覚がかなり歪んでしまっている。エヴァ・アームストロングと山野辺澪とは、両親の仕事を通じて知り合った。両親は児童福祉の現場で、二人を担当していたのだ。そのため、三人は幼い頃から家族のように一緒に過ごしてきた。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b197934-2stBQeFLuGNf.png', NULL, NULL, '下妻由幸', NULL, 197934, 'SUPPORTING', 16) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022067', 'AN1963', '朴木十夜', '物腰が柔らかく、誰に対しても親切で、とても礼儀正しい少年。非常に穏やかな性格のせいで、少しおっちょこちょいなところもある。ツバキとは親しく、昔から彼女を支え続けてきた。 また、辰巳マダラオと葵カキツバタが喧嘩をするたびに、仲裁に入っている。一見、お酒を全く飲まないように見えるが、実は酒豪である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b197942-gtOyW2MdSw01.png', NULL, NULL, '峰岸佳', NULL, 197942, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022068', 'AN1963', '枢木睦月', '弟とは正反対の、おっとりした少年。弟の行動を止めようとはせず、いつも見守っている。 寝ることが大好きな少年、ムツキは自分のペースで物事に取り組む。以前は体が弱かったため、サツキ以外に遊ぶ相手がいなかった。そのせいで、彼は自分と関わる人との間に一線を引く癖がある。それでも、フタミのことは気に入っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b165226-KpYuaya27qFQ.jpg', '1月1日', NULL, '近藤隆', NULL, 165226, 'SUPPORTING', 21) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022069', 'AN1963', '海部子規', '軽薄な口先だけの男のような雰囲気を漂わせている。女の子を見かけるたびに、どうしても口説かずにはいられない。有名な陶芸家であり、周囲の人々にこぞって世話を焼かれている姿がよく見られる。 その一方で、友人に対しては思いやりのある一面もあり、男性の友人も多くいる。プロデューサーにアプローチしようとすると、いつも断られてしまう。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b165233-yO34KfS5n0Qp.jpg', NULL, NULL, '谷地克文', NULL, 165233, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022070', 'AN1963', 'エヴァ・アームストロング', 'He is referred to as “Master” by the other two in the group. He may be always talking like a chuunibyou, but he is just a romantically inexperienced, disappointing adult. Though he looks rather young, he is actually 29 years old, and is the oldest in I-Chu. He invited F∞F’s Kanata Minato to join the group as the Crimson Angel (緋色の白兎, Hiiro no Shiro-usagi, lit. Scarlet White Rabbit), but was refused every time.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b197935-1mAYIGsfVcoD.png', NULL, NULL, '下野紘', NULL, 197935, 'SUPPORTING', 30) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022071', 'AN1964', 'スズノ', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b203092-e29Pqn0JePLZ.png', '11月4日', NULL, '宮下早紀', NULL, 203092, 'MAIN', 5) ON CONFLICT DO NOTHING;
