INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022075', 'AN1964', 'キョウカ', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b203096-xtnwmBRwSrj7.png', '12月1日', NULL, '大西沙織', NULL, 203096, 'MAIN', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022076', 'AN1965', 'モア', 'Grop：Plasmagica 担当：ボーカル＆ドラム　研究任務のために遠い銀河からやってきた、生まれつき風変わりでエネルギッシュな「スペース・シープ」の少女。 彼女の音楽的感性はまさに宇宙的であり、グロップのメンバーの中でも比類のないものだ。頭に浮かんだことを何でも口走ってしまう癖があり、それが時折バンドメイトをトラブルに巻き込んでしまう。彼女の特徴的な口癖である、文末に「ピュル」と付けるのは、どうやら故郷の惑星からの通信コードらしい。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/88974-fFGaW4kWLFlP.jpg', '8月7日', NULL, '佐倉綾音', 161, 88974, 'MAIN', 80) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022077', 'AN1965', '聖川詩杏', '担当：ボーカル・ギター　「ストロベリー・ハート」と呼ばれるハート型のギターを大切にしている猫耳少女。このギターは、並外れた力を秘めていると噂される伝説の楽器だ。そのギターの才能がメイプル・アリスガワに認められ、プラズマギカのメンバーとしてスカウトされた。 チュチュ、レトリー、モアと共にバンド活動を続ける中で、彼女は成長し、成熟し続けている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b88976-dEfoyxtZOzBd.png', '5月24日', NULL, '稲川英里', 154, 88976, 'MAIN', 241) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022078', 'AN1965', 'ほわん', 'グループ：マシュマイレシュ！！ 担当：ボーカル・ギター　北の地の小さな村で生まれ育った、淡い狐の部族の少女。いつか大都市へ行き、そこで何か素晴らしいことが待っていることを夢見ている。 好奇心旺盛で、何事にも全力を尽くす彼女だが、数字には苦手意識がある一方で、家事の腕前は抜群だ。性格は穏やかだが、嫌いなことにはきっぱりと「ノー」と言うことを恐れない。優しくてふわふわした雰囲気の持ち主だが、その内面には強い芯を持っている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b152201-jxPpy9KWatc8.png', '5月1日', NULL, '遠野ひかる', 152, 152201, 'MAIN', 95) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022079', 'AN1965', 'チュチュ', 'グループ：プラズマギカ　ポジション：ボーカル・ギター　「愛される学級委員長」という典型を体現するウサギの少女。頼りになり、几帳面な優等生であると同時に、社交的で魅力的な性格の持ち主だ。バンドの事実上のリーダーを務めており、メンバーから厚い信頼を寄せられている。 しかし、彼女には野心的な一面もあり、他のメンバーには内緒で、密かにソロデビューを目指している。彼女は毎日欠かさずギターの練習に励み、', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/88975-IMO6uHt7dmuA.jpg', '6月18日', NULL, '上坂すみれ', 159, 88975, 'MAIN', 59) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022080', 'AN1965', 'レトリー', 'Grop：Plasmagica 担当：ボーカル・ベース  ドッグ・トライブ出身の女の子で、生粋のネットオタクかつスマホ中毒。普段はクールなふりをしているが、心の奥底では信じられないほど内気だ。自分が情熱を注ぐ話題が出ると、興奮のあまり、矢継ぎ早に話し始めてしまう。 しかし、ネット上ではかなりおしゃべりな一面を見せる。「ノーマルな人」（社交的な生活を送っている人）や衣料品店の店員を苦手としている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/88973-zfhUWnHIQBfw.jpg', '11月7日', NULL, '沼倉愛美', 150, 88973, 'MAIN', 89) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022081', 'AN1965', 'ルフユ', 'グループ：マシュマイレシュ！！ 担当：ボーカル、ドラム  「狼娘族」出身の少女。明るく、エネルギッシュで、並外れて健康体、そして模範的な生徒である。献身的で思いやりに溢れ、周囲の人々から深い信頼を寄せられている。 しかし、彼女は両親が自分のために用意した道――これまで忠実に歩んできたその道――に疑問を抱き始めている。彼女自身の言葉によれば、時折、周囲のすべてを破壊したいという衝動に駆られることがあり、その衝動に抗うために必死に奮闘している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b152203-6qWlpvok9piR.png', '12月22日', NULL, '山根綺', 157, 152203, 'MAIN', 34) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022082', 'AN1965', 'マシマヒメコ', 'グループ：マシュマイレシュ！！ 担当：ボーカル・ギター  「縞猫一族」出身の少女。縞模様のツインテールがトレードマークで、スタイルも抜群だ。人との関わりを避ける傾向がある。音楽が大好きで、幼い頃から誰よりも熱心に楽器の練習に励んできた。 意志が強く、頑固で短気な一面もあるが、心の奥底では臆病で繊細、孤独を感じやすい。成績は平均的だ。 誰にも言えない秘密の趣味があるという噂が流れているが……', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b152202-mhqtwPqdFFA6.png', '7月22日', NULL, '夏吉ゆうこ', 158, 152202, 'MAIN', 87) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022083', 'AN1965', 'クロウ', '種族：ハリネズミ　グループ：ShinganCrimsonZ　担当：ボーカル・ギター　恐れを知らず、自分が「世界で一番クールで人気のある男」であることを、疑いの余地なく確信している。 彼の代名詞とも言えるスタイルは、荒削りでありながら鋭利な歌声で、聴く者の背筋をゾクッとさせる。酪農家の出身で、牛乳が大好きだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89367-gxUZtndyxZaC.png', '9月6日', NULL, '谷山紀章', 165, 89367, 'SUPPORTING', 96) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022084', 'AN1965', 'カイ', 'グループ：トリクロニカ　ポジション：ドラム　カイは、大手アイドルレーベル「ジュダス」に所属するアーティスト・ツインデュオの兄である。エネルギッシュで、どこか無鉄砲な性格の持ち主であるカイは、いつも弟のリクを、少し見下したような目線で気にかけている。 彼はシュウ☆ゾーを非常に高く評価している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b153401-XKLETGX5Jw40.png', '10月9日', NULL, '逢坂良太', 171, 153401, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022085', 'AN1965', 'ララリン', 'グループ：REIJINGSIGN　役職：ボーカル兼ギター　「フィアース・カラカル族」出身の、活気にあふれ美しい若い女性。グループの誠実で正義感あふれる支柱的存在である。生粋の食通であり、彼女の座右の銘は「満腹の腹にこそ、明晰な頭脳あり」だ。 トップクラスのアーティストになることを目指し、幼少期から数え切れないほどのコンテストに出場し、「オーディションの旋風」としてその名を知られている。以前は別のユニット名で活動していたが、商業的な成功を収めることはできなかった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154131-jOMphffHWJo0.png', '9月15日', NULL, 'Lynn', 162, 154131, 'SUPPORTING', 14) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022086', 'AN1965', 'ジョウ', 'グループ：DOKONJOFINGER　ポジション：ベース　フェニックス一族出身の、体格の華奢な若者。体は弱々しいが、戦闘能力と精神力は並外れて強い。度重なる入院と退院のため、学校では何度も留年を余儀なくされ、実際には数年前にすでに成人している。 おめでとう！　彼は、他の男性たちからも称賛されるような、荒削りでワイルドな魅力と、揺るぎない忠誠心を兼ね備えており、決して仲間を裏切ることはない。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154136-b0ZrHsNwBuo6.png', '10月10日', NULL, '小野友樹', 184, 154136, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022087', 'AN1965', 'ヤイバ', 'グループ：ShinganCrimsonZ　ポジション：ベース　彼はロックの精神と侍の道を重んじている。彼自身、自身のベーステクニックは最高レベルだと自負している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89369-DRfN3I7dS4Kz.png', '8月18日', NULL, '柿原徹也', 174, 89369, 'SUPPORTING', 27) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022088', 'AN1965', '阿', 'グループ：ツレズレ・ナル・アヤツリ・ムゲナン　担当：ボーカル、ギター　極東のある国の武士一族の中で生まれ育った。吽の幼なじみである。真面目で堅実な性格のため、師匠であるダル太夫によくからかわれている。 彼女は、独自の「極東サウンド」をMIDICITY全土に広めることを目指し、バンド活動を行っている。現在、厳しい修行の真っ最中であるため、普段は伝統的な円錐形の帽子で顔を隠している。噂によると、', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b153397-bj9JGiZrPvHV.png', '8月25日', NULL, '早見沙織', 160, 153397, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022089', 'AN1965', 'ハッチン', 'グループ：DOKONJOFINGER 担当：ボーカル・ギター　ブンブン・ビー・トライブ出身の、スタイリッシュで不良風の男性。細身で素早い動きが特徴で、まず刺してから考えるタイプだ。せっかちで短気だが、心の奥底は純粋である。 親への反抗心から、ナイトライフ地区を闊歩し、強がりを装っている。ヤスを「絶対に負けるわけにはいかない宿命のライバル」と見なし、誰よりも強く敵視している。彼の代名詞となる必殺技は「超音速ブンブン・ニードル」だ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154135-gexUmSMblNhv.png', '4月4日', NULL, '小松昌平', 173, 154135, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022090', 'AN1965', '吽', 'グループ：ツレズレ・ナル・アヤツリ・ムゲナン　ポジション：ベース　彼女は極東のある国の楽器職人の家で生まれ育った。 阿の幼なじみである。陽気な性格で、手先が器用なため、楽器のメンテナンスも難なくこなす。MIDICITY全体に、極東特有のサウンドを広めることを目指し、バンド活動に精力的に取り組んでいる。現在は修行中であるため、普段は顔を隠している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b153398-AHRX4uioe6PW.png', '6月8日', NULL, '松井恵理子', 152, 153398, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022091', 'AN1965', 'スモモネ', 'Grop：REIJINGSIGN 阿L 担当：ボーカル・ギター　美しく、豊満なムササビの少女。「セクシー・ヒーリング」はスモモネの得意技だ。母親は元女優であり、幼い頃から芸能界の世界に触れてきたため、異性を惹きつけるのが得意だ。  相手をからかったり、いたずらっぽい振る舞いをよく見せる。自分の魅力を武器にして他人を操るのが好きだ。現在、彼女は「真実の愛」の意味を理解していない。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154132-6Uo93H7VB3Xn.png', '6月2日', NULL, '芹澤優', 160, 154132, 'SUPPORTING', 14) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022092', 'AN1965', 'アイオーン', 'グループ：ShinganCrimsonZ　ポジション：ギター　不審な雰囲気を漂わせており、特定のポーズをとらない限りは明瞭に話すことができない――しかし、その容姿は驚くほどハンサムだ。ライブパフォーマンスで披露する天才的なギターテクニックで、女性ファンを魅了していると噂されている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89368-Bj6vLGChw4sC.png', '2月10日', NULL, '内山昂輝', 192, 89368, 'SUPPORTING', 41) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022093', 'AN1965', 'リク', 'グループ：トリクロニカ　ポジション：ベース　リクは、大手アイドルレーベル「ジュダス」に所属する新人アーティストの双子コンビの弟である。 スタジオ通いが好きで真面目な若者であるリクは、兄のカイののんきでだらしない性格や、先輩のシュウ☆ゾーのワイルドで風変わりな性格に、いつも振り回されている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b153400-HCZMGuEuUBba.png', '10月9日', NULL, '村瀬歩', 169, 153400, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022094', 'AN1965', '双循', 'グループ：DOKONJOFINGER 担当：ドラム　「鬱憤」一族に属する、とてつもなく傲慢な若者。金色のきつくカールした髪と、エメラルドのようにきらめく瞳は、彼を見る者すべてを魅了する。 その圧倒的な破壊力で、彼はたった1日で学園の完全な支配権を掌握した。並外れた強さを持ちながらも、その戦闘スタイルは極めて冷酷無比だ。背が高くすらりとした体つきでありながら、しなやかで強靭な肉体を持っており――そして、その香りは実に素晴らしい。勝利を確実にするためなら手段を選ばず、', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154137-Cg9uhVb4ISQ5.png', '11月23日', NULL, '白井悠介', 189, 154137, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022095', 'AN1965', 'ロム', 'グループ：ShinganCrimsonZ　ポジション：ドラム　バンドのリーダーであり、言葉よりも先に拳が飛び出しがちな熱血漢で、メンバーを一つにまとめる原動力となっている。会社員としての仕事とバンド活動を両立させている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89371-QXCj1t7owGUX.png', '6月6日', NULL, '細谷佳正', 186, 89371, 'SUPPORTING', 47) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022096', 'AN1965', 'ういうい', 'グループ：REIJINGSIGN　阿L　ポジション：ボーカル兼ベース（左利き）　アイス・ラビット族出身の金髪の美女。グループにおいて、冷徹で計算高く、野心あふれる戦略家としての役割を担っている。北の遥か彼方にある氷の地で育ち、スケートに明け暮れる日々を送っていた。 娯楽がほとんどなかったその地で、彼女は人生で初めて目にしたバンドのライブ演奏をきっかけに、音楽への深い憧れを抱くようになった。透き通るような白い肌を持ち、氷のように完璧な顔立ちをしており、', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154133-9CQtCq1jDuMw.png', '2月1日', NULL, '鈴木みのり', 155, 154133, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022097', 'AN1965', 'リカオ', 'Grop：ヨカゼノホライズン  「アーネスト・ライカオン・トライブ」のボーカル兼ベーシスト。本職は弁護士。   鋭い眼差しと近寄りがたい物腰から威圧的なオーラを放っているが、実はかなり内気な性格で、褒められると必ず顔を赤らめてしまう。 彼は物静かで、ついクスクスと笑ってしまう性格の持ち主だ。法廷で最も予期せぬ瞬間に笑いをこらえきれなくなることが多いため、この癖を直したいと切望している。かつて、バンドの仲間を弁護して救ったこともある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b203501-2oPU3BJVNYlR.png', '10月4日', NULL, '古川慎', 177, 203501, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022098', 'AN1965', 'ヤス', '種族：ヤタガラスの一族　グループ：DOKONJOFINGER　担当：ボーカル・ギター　お弁当好きのヤタガラスの一族のメンバー。お弁当屋の店主の息子として生まれ、文字通りお弁当と共に育った。 無愛想で、威圧的な眼差しを放ち、身長は小柄な方だ。不良たちに頻繁にいじめられるが、彼の必殺技「デス・クロス・カウンター」で彼らをすべて撃退する。気がつけば、彼は「ヤタガラス」という異名で知られる地元の伝説となっていた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154134-YShDrq3l8cie.png', '8月4日', NULL, '伊東健人', 167, 154134, 'SUPPORTING', 22) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022099', 'AN1965', 'ペイペイン', 'Grop: BUD VIRGIN LOGIC　希少な「ダーク・キリン」一族に属する女性ベーシスト。幼少期に謎めいた財団に引き取られ、現在はアイルーンのメイドとして仕えている。 彼女は常に無表情で女主人を見守っている。穏やかで動じない性格の持ち主であり、何事にも動じず、常に他人のニーズに気を配る、非常に頼りになる人物だ。スカートの下には膨大な数の武器を隠している。噂によると、彼女は恐ろしいほど……', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b153432-IQJ0ey1KhpSN.png', '2月22日', NULL, '田中あいみ', 161, 153432, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022100', 'AN1965', 'セレン', '種族：リフレッシュ・ラム　グループ：阿RC阿RE阿F阿CT　担当：ベース　彼は、宇宙規模の巨大レコードレーベル・コングロマリットの会長の息子である。 幼少期のほとんどを、実家の私設図書館で過ごすかのように過ごしたため、音楽に関する深い知識を持ち、特に無名であまり知られていないバンドに関するゴシップやトリビアを好んでいる。少年のような外見とは裏腹に、時折驚くほど大人びた発言をしたり、遊び心のあるからかい混じりの冗談を飛ばしたりすることもある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b219685-61o1l8GTOPud.png', '4月23日', NULL, '筆村栄心', 160, 219685, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022101', 'AN1965', 'ダル太夫', '種族：吽　所属グループ：ツレズレ・ナル・アヤツリ・ムゲナン　阿　ダルマ人形に扮した謎めいたドラマーで、放浪の旅を続けている。 噂によると、そのダルマは単なる変装に過ぎず、彼女の真の姿は人形の中に隠されているという……。旅の途中で出会った「阿」と「吽」の音楽を通じて不思議な絆を感じ取り、彼らとバンドを結成する。彼女は旅が大好きだ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b153396-vrhmJCSCa7ZW.png', '7月26日', NULL, '潘めぐみ', 140, 153396, 'SUPPORTING', 36) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022102', 'AN1965', 'シュウ☆ゾー', 'グループ：トリクロニカ　担当：ボーカル・ギター　大手アイドルレーベル「ジュダス」のナンバーワン・タレント。「銀河のプリンス」にふさわしい甘い歌声とルックスで、ファンの心を掴んで離さない。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b153399-COnNJxTR9Yej.png', '7月7日', NULL, '宮野真守', 176, 153399, 'SUPPORTING', 26) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022103', 'AN1965', 'ラメカ・パシャリコワ', 'カメラが大好きなチンチラの女の子。彼女はプロのカメラマンになるためにMIDICITYにやって来た。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b235013-QkjkI2flIGwl.jpg', NULL, NULL, '高橋花林', NULL, 235013, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022104', 'AN1965', 'アイレーン', 'Grop：BUDVIRGINLOGIC 担当：ボーカル・ギター　すべての人を見下ろす威風堂々としたライオンの少女。王のオーラを纏い、言葉の力（コトダマ）に長けたカリスマ的な美女。身長は小柄。 幼い頃から音楽と神皇帝としての在り方を教え込まれてきた。しかし、そのせいで彼女は運動神経に乏しく、何事にも面倒くさがり屋になってしまった。さらに、よく転んだり物を落としたりする不器用な一面もある。高い場所が好きで、細いものを好む。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126852-Nbd0N65dkdcu.png', '12月22日', NULL, '野口瑠璃子', 142, 126852, 'SUPPORTING', 38) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022105', 'AN1965', 'ハンドレッコ', 'Grop：BUD VIRGIN LOGIC 担当：ドラム　「ホワイト・タイガー」系統のムオモロイドの少女で、謎めいたファウンデーションの施設内で密かに開発された。アイレーンに遊び相手として連れてこられたことをきっかけにBVLに加入した。高周波ブレードを装備した一対のドラムスティックを自在に操って演奏を行う。   普段は物静かだが、時折、どこか懐かしさを感じさせるほのかな微笑みを浮かべることがある。充電は彼女の日常のルーティンの一部である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b153431-oHgaw4rqWy5I.png', '6月26日', NULL, '木戸衣吹', 159, 153431, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
