INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022144', 'AN1969', 'ダン・クーソー', 'ダンは「ヒーローズ」の「タレント」担当だ。この子にカメラを向け、何か課題を与えれば、間違いなく「いいね！」が欲しくなるようなパフォーマンスを見せてくれる。ダンは運動神経が良く、社交的で、誰にでも門戸を開き、仲間を力強く支える――本人はそう自覚していないものの、生まれながらのリーダーだ。 短くも輝かしい人生の中で、ダンは多くの友人を作ってきたが、親友であるウィントン・スタイルズとリア・ベネガスに対しては並々ならぬ忠誠心を示している。彼らは共に多くの困難を乗り越えてきた。意見が対立した時でさえ、誰も決して……', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b138975-7tIui7jXKoN8.jpg', NULL, NULL, '高橋李依', NULL, 138975, 'MAIN', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022145', 'AN1969', 'リア・ヴェネガス', 'リア・ヴェネガスは、ファッションセンスが際立つ服装を好む一方で、芸術的なセンスも持ち合わせており、自分の見た目を一切気にしていない。 彼女は視覚的に自己表現を行い、それが彼女のスタイルに反映されている――自作の「アップサイクル」ドレスにコンバットブーツを合わせたり、笑顔の猫がプリントされたTシャツの上にグランジ風のトップスを羽織ったりしている。 リア・ヴェネガスは、まさに唯一無二の存在だ。ダンとウィントンが、そのばかげたスタントを成功した動画に仕上げられなかった時、たまたま通りかかったリア・ヴェネガスが、自ら進んでいくつかの提案を行い、', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b138977-GcQhNxGferjY.jpg', NULL, NULL, '赤﨑千夏', NULL, 138977, 'MAIN', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022146', 'AN1969', 'マグナス・ブラック', '強力な「ニリオス」を操る仮面の少年は、ダンの最大のライバルとなる。マグナスは名声には全く関心がなく、その正体を謎に包んでいる。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b140002-1QYDNyfOqb2n.jpg', NULL, NULL, NULL, NULL, 140002, 'MAIN', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022147', 'AN1969', 'ウィントン・スタイルズ', 'ウィントンは、まるで何もないところから次々と生み出しているかのような、数え切れないほどのギアやガジェットを自在に使いこなす、のんびりとした「スラッカー・ハッカー」スタイルの持ち主だ。肩に掛けた多目的の「ハックパック」が、そのスタイルを完璧に引き立てている。 ウィントンとダンは小学1年生の頃から親友だ。二人が知り合ったのは、ダンが昼食用のテーブルからバックフリップをしようとして、持っていた携帯ゲーム機が壁にぶつかって飛んでしまった時のことだった。ウィントンはペーパークリップとガムを使ってそれを直した。　そう、ウィントンは頭がいい。本当に頭がいい。そして、多くの賢い子供たちと同じように、彼は自分の', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b138978-rC4DR1Rl4AjM.jpg', NULL, NULL, '福島潤', NULL, 138978, 'MAIN', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022148', 'AN1969', 'シュン・カザミ', 'シュンはまるで大人のような振る舞いをする。その真面目な態度は、服装の選び方にも表れている。すっきりとしたシルエットの青いスーツ。アインシュタインのように、彼は曜日ごとに1着ずつ持っている。ヒーローたちにファンが1人いることを覚えているだろうか？　そう、それが彼だ。 彼の名前はシュン・カザミ。バクガンバトルでダンのチームに加わるため、地球の半分を旅してきた。年齢の割に大人びていて、早熟で謎めいたシュンは、ドラゴの発見を目撃した後、ダンの町に現れる。実は、シュンこそが', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b138976-eliOsqhOhzRM.jpg', NULL, NULL, '内山夕実', NULL, 138976, 'MAIN', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022149', 'AN1969', 'ライトニング', '（犬の年齢換算で）フレンチ・ブルドッグの「ライトニング」は、自分のバクガンを持ち運び、発射できる首輪を身につけている。 いたずら動画を撮影する子供たちには「相棒」が必要だが、ヒーローたちにとってその相棒こそがライトニングだ。ダンの家の裏路地でふらふらと過ごしていた野良犬だったライトニングは、今では彼らの非公式のマスコットとなっている。 陽気でずんぐりした、眠たそうなフレンチ・ブルドッグのライトニングは、よくダンと共演している。その名前が示すほど速くはないが、トラブルが迫ってくると「ワン！」と吠えるのが得意だ。ライトニングはまさに……', 18, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b138974-fn5o3PKyAf4m.jpg', NULL, NULL, '金田アキ', NULL, 138974, 'MAIN', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022150', 'AN1969', 'ドラゴノイド', 'ドラゴノイドは、『爆丸バトルプラネット』、『爆丸アーマードアライアンス』、『爆丸ジオガンライジング』に登場するドラゴンタイプの爆丸である。ダン・クーソーの守護爆丸である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b210056-gZ6KuWaObyvk.jpg', NULL, NULL, '武内駿輔', NULL, 210056, 'MAIN', 2) ON CONFLICT DO NOTHING;
