INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022153', 'AN1969', 'ストラタ', '35歳――かつては世界で最も危険な野生動物を狩っていたが……「バクガン」と呼ばれる異世界の生物の存在を知るまでは。それ以来、ストラタは最先端の狩猟技術を駆使し、娯楽としてバクガンを追跡し、無力化している。 彼はこれまでに数体を捕獲し、それらを無力化されたトロフィーとして自身の邸宅に保管している。特殊なエネルギー吸収兵器を用いることで、ストラタはバクガンの力を吸い取り、休眠状態にすることができる。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b141233-sZ5Orz9LxajC.png', NULL, NULL, NULL, NULL, 141233, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
