INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022156', 'AN1969', 'イー', 'イーは『爆丸バトルプラネット』に登場する「イーxitチーム」のメンバーです。現時点では、彼女がパイラス・ブロウラーであること以外、彼女に関する情報はあまり明らかになっていません。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b228733-I1iyyq8cLba2.png', NULL, NULL, NULL, NULL, 228733, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022157', 'AN1969', 'エミリー・ブラック', 'エミリーはマグナス・ブラックの妹です。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b234770-94znCdvWgOJy.png', NULL, NULL, NULL, NULL, 234770, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022158', 'AN1969', 'ピラビオン', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b161209-zOqMQ9us5a0B.png', NULL, NULL, NULL, NULL, 161209, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022159', 'AN1969', 'ベントン・ダスク', 'ベントン・ダスクは、バクガンが悪意や私利私欲のために利用されるのを防ぐことを使命としている。一方、姉のフィロメナ・ダスクはそれとは正反対の行動を取り、自身の会社「AAAnimus Inc.」を通じてバクガンから利益を得ようとしている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b141528-DYLo3QbaGaIw.jpg', NULL, NULL, NULL, NULL, 141528, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022160', 'AN1969', 'ディー', 'ディーは『バクガン・バトル・プラネット』に登場するキャラクターです。彼女は「イーxitチーム」の中で、ランクが2番目に低いメンバーです。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b228734-ZERN8G4n0G1X.jpg', NULL, NULL, NULL, NULL, 228734, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022161', 'AN1969', 'エベレットレイ', 'エヴェレット・レイは『バクガン・バトル・プラネット』に登場するキャラクターで、ピンポイント・パークを救うために「ザ・オーサム・ワンズ」が資金を集められるよう、バクガン・バトル・リーグの開催を推進している。  彼は『The Lost and the Cost』で初登場し、リアたちに対し、公園を救うための資金を稼ぐためにバクガンリーグを立ち上げるというアイデアを提示する。「アメージング・ワンズ」は、バクガンを金儲けの手段にするという考えを快く思っていないが、それでもメッセージを発信するためにそれを実行する。 リーグ戦では、ダンがチャイナ・ライオットと対戦する。ライオットはやりすぎてしまい、その結果……', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b210058-SBH1nUVIpXlk.jpg', NULL, NULL, NULL, NULL, 210058, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022162', 'AN1969', '工ーイ', '「The イーxit Team」のメンバー。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b141526-ZePvqNfMHNAA.jpg', NULL, NULL, NULL, NULL, 141526, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022163', 'AN1969', 'Duran Dane', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b188813-iPK3tUDd87c5.png', NULL, NULL, NULL, NULL, 188813, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022164', 'AN1969', 'クラビッツ', 'クラビッツはAAAnimus社の潜入工作員として活動しており、ロス・ヴォルモスに潜入し、「オーサム・ワンズ」を無力化するという任務を負っている。彼女は、訓練中の事故で市民の家の窓が割れたことをきっかけに、ダン・クーソーとライトニングをスパイする。 彼女は、コゾ家の新しい隣人であると同時に、「アンチ・バクガン活動家」として変装する。ダン君の両親が、彼女のバクガンに対する批判に対して慎重な反応を示した際、クラビッツはアーニマス社の技術を用いてドラゴをボール形態から強制的に解放し、破壊する。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b210061-liacVoGg9ZTx.jpg', NULL, NULL, NULL, NULL, 210061, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022165', 'AN1969', 'ヴェロニカ・ヴェネガス', 'ヴェロニカはリア・ヴェネガスの母親で、アメージング・ワンズが住む町でニュース記者として働いている。彼女はよくバクガンに関する出来事を報道している。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b142095-JIgEJnjpv2gu.png', NULL, NULL, NULL, NULL, 142095, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022166', 'AN1969', 'マルコ・チェザネッロ', 'マルコは自己中心的ないじめっ子で、かつてロス・ヴォルモスで最大級のいじめっ子として知られていた。彼は、正しいことをしたいと願っていたピルス・シンデオスを利用して、ロウディ・レッズを彼らの公園から追い出した。 彼はコステロ・カニャーダにある公園を「ロウディ・レッズ」から奪い取り、その圧倒的な力に畏敬の念を抱いたマックスの注目を集める。マルコは公園を統治するための巨大なステージや、自身の記念碑をいくつも建設し、マックスを専属の召使いとして使いこなす。彼は', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b210060-iNlNU3h90BGg.jpg', NULL, NULL, NULL, NULL, 210060, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022167', 'AN1969', 'クリスタル・ブルー', 'クリスタル・ブルーは、グレゴリウス・リードのエージェントであり、超能力者でもある。彼女のガーディアン・バクガンはノビリオスとマクソタウルス、そしてジオガン・スタードックスだ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b215202-kXdmcdqag71X.png', NULL, NULL, '加隈亜衣', NULL, 215202, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022168', 'AN1969', 'マサト・カザミ', 'マサト・カザミはシュンの従兄である。彼はAAANIMUS社に雇われ、シュンをヒーローの座から引きずり下ろす任務を負っている。マサトは、シュンを家族の元へ連れ戻すか、あるいは自分の家族のように彼を永遠に追放することで、自らの価値を証明しようとしている。  マサトは狡猾で、意地悪で、冷酷な人物だ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b141529-Efxt41EybJdu.jpg', NULL, NULL, NULL, NULL, 141529, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022169', 'AN1969', 'Cee', '「The イーxit Team」のメンバー。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b188811-DFzjoZ9MqDLA.png', NULL, NULL, NULL, NULL, 188811, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022170', 'AN1970', '場地圭介', '第1部隊の隊長であり、東京マンジギャングの創設者の一人。バジは荒々しい性格の持ち主だ。アドレナリンが湧き上がるスリルをこよなく愛しており、マイキー自身も「バジは特に理由もなく、ただ気分で通りすがりの人を殴り飛ばすような男だ」と語っている。戦闘中も、彼のトレードマークであるニヤリとした笑みを絶やさない。', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b145343-vRrkdWEUXwYM.jpg', '11月3日', 'AB', '水中雅章', 175, 145343, 'SUPPORTING', 4675) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022171', 'AN1970', '稀咲鉄太', 'キサキは『東京リベンジャーズ』の主要な敵役である。特に、トマンの頂点へと猛烈な勢いで上り詰めたことで知られている。   木崎は冷酷で狡猾、野心家であり、目標を達成するためなら手段を選ばない。体格は平均的だが、恐怖によって支配するその力は、自分より強い者さえも従わせる。物語全体を通じた彼の行動は、すべて東京で最も強力かつ影響力のある犯罪者になることを軸に展開している。', 14, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b170483-mXcSRDNqVwCP.png', '1月20日', 'A', '森久保祥太郎', NULL, 170483, 'SUPPORTING', 290) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022172', 'AN1970', '長内信高', 'オサナイは、メビウス組の元組長である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b171923-7ledIbSoL5Jq.jpg', NULL, NULL, '竹内栄治', NULL, 171923, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
