INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022176', 'AN1970', '小島', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b296197-KWxI42IyXi7M.png', NULL, NULL, '阿部大樹', NULL, 296197, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022177', 'AN1970', '羽宮一虎', '東京マンジギャングの創設者の一人であり、かつてヴァルハラのナンバー3を務めていた。カズトラは心に深い傷を負っている。幼い頃、家庭内暴力の渦中で、母親と父親のどちらかを選ばざるを得なかったのだ。家族としての生活が事実上存在しなかったため、彼は他の幸せな家族を軽蔑するようになった。 子供たちが親と仲睦まじく過ごす姿を見るといった些細なことさえ、カズトラの心の傷を刺激し、彼を深く苛立たせた。', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b167846-k6G44c97MOug.jpg', '9月16日', 'AB', '土岐隼一', 174, 167846, 'SUPPORTING', 1927) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022178', 'AN1970', '立花亮子', 'ヒナタとナオトの母親。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b233328-Z26XQKetvtl6.png', NULL, NULL, '沼倉愛美', NULL, 233328, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022179', 'AN1970', '清水将貴', '清正は、渋谷第三中学校の3年生のリーダーであり、かつて「トマン」のメンバーだった。', 26, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b171921-XYszdVg9q8TU.jpg', '1月18日', NULL, '日野聡', NULL, 171921, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022180', 'AN1970', '阪泉', '阪泉は、池袋の犯罪組織「ブラック・メンバーズ」に所属するキャラクターである。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b243572-dsKMewNZaXns.jpg', NULL, NULL, '三宅健太', NULL, 243572, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
