INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022183', 'AN1970', 'ガリ男', 'ガリ男は、上野の縄張りを支配する東京屈指のギャング組織「ナイト・ダスト」のリーダーである。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b243575-K4dGGogvZzub.jpg', NULL, NULL, '矢野龍太', NULL, 243575, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022184', 'AN1970', '亜波根チョウジ', 'チョウジはヴァルハラの隊長の一人であり、キサキの取り巻きの一人である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b264909-v6gJeUHkt9q7.jpg', NULL, NULL, '柳田淳一', NULL, 264909, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
