INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022186', 'AN1970', 'マサル', '武道のいとこで、渋谷中学校の3年生。学校の不良グループのリーダーを自称していたが、実は清正とその仲間たちの手先であることが露見した。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b296193-StXZbyztLqlK.png', NULL, NULL, '浜添伸也', NULL, 296193, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022187', 'AN1971', '青山優雅', '個性：へそレーザー　U.A.高校1年A組の生徒。ユガは、特に自分の個性に関しては、クラスメートより自分が優れていると思い込み、虚栄心が強く、傲慢な印象を与える。 彼は派手な仕草を見せ、ポーズを取るのが好きで、周囲の注目を集めようとするが、同級生からは頻繁に無視されている。また、自身のフランス系の血筋を強調し、時折会話にフランス語を織り交ぜる。ユガのクィークは、強力な火花を発射することを可能にする。', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b127042-a6dlcC3ZYSDx.png', '5月30日', NULL, '桑野晃輔', 168, 127042, 'SUPPORTING', 713) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022188', 'AN1971', '庄田連撃', 'ニレンゲキは、自分の力では成し遂げられなかったことについては、その功績を自分のものとはしないという、非常に謙虚な姿勢の持ち主である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b208143-w6rQrczIATRG.jpg', '2月2日', NULL, '大隈健太', NULL, 208143, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022189', 'AN1971', '修善寺治与', 'クィーク：ヒール　職業：プロヒーロー、看護師　チヨはとても親切で思いやりのある性格で、誰に対しても優しく接しますが、愚かなことをした相手に対しては厳しく叱責する態度を見せます。 特に、イヅクにクィークの正しい使い方を教えないオールマイトや、クィークを無謀に使うイヅクに対しては、こうした態度を見せることが多い。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b157655-OOLn8kPUegMw.jpg', '4月4日', NULL, '小桜エツコ', NULL, 157655, 'SUPPORTING', 59) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022190', 'AN1971', 'エンディング', '「エンデバー・エージェンシー編」で敵役として登場する悪役。物語の開始から7年前、エンディングはエンデバーが「タカミ」という名の泥棒を捕まえるのを目撃した。それ以来、エンディングはエンデバーに執着し、彼に自分を殺してほしいと願うようになった。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b242582-u0WJxxFcTN6Z.png', NULL, NULL, '谷山紀章', NULL, 242582, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022191', 'AN1971', 'クラスト', '特技：シールド　職業：プロヒーロー（No.6）　戦闘スタイル：近接戦闘', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b289314-BBr8wZSw4nQI.jpg', NULL, NULL, NULL, NULL, 289314, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022192', 'AN1971', '尾白猿夫', '個性：テール　U.A.高校1年A組の生徒。マシラオは極めて穏やかで高潔な態度と、深い自尊心を持っており、自分の実力では得られなかったと感じる結果を受け入れることができない。また、努力家としても知られている。 強い自尊心を持つ一方で、マシラオは内気で恥ずかしがり屋な一面もあり、人前に出ることをあまり好まず、すぐに照れてしまう。周囲から「地味」だと言われることが度々あり、それが彼を深く動揺させている。', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89896-3QzT5nSEPjcr.png', '5月28日', 'O', '晃祐三好', 169, 89896, 'SUPPORTING', 375) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022193', 'AN1971', '宍田獣郎太', 'ジュロタは、かなり言葉遣いが丁寧で、よく「サー」や「ミス」といった敬称を使って他人に話しかけることから、知的な人物のようだ。これは、彼が非常に礼儀正しく、溺愛する家庭で育ったためである。 しかし、変身中はジュロタはかなり騒がしく、エネルギッシュになるが、これはおそらく彼の「クィーク」による副作用だろう。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b208142-4KB3VlunJwmx.jpg', '3月26日', NULL, '諏訪部順一', NULL, 208142, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022194', 'AN1971', '角取ポニー', '特技：ホーンキャノン　ポニーは臆病な女の子だ。 外国人であるため、日本の言葉についてはあまり詳しくありません。性格はかなり純真で無邪気な面があり、ネイト・モノマから1-A組に伝えるよう言われた意地悪な言葉を、その意味を理解せずにそのまま受け入れてしまう様子が見られます。 ポニーは思慮深く、勤勉な人物だ。彼女の戦略と粘り強さのおかげで、チームは1-A組に負けずに済んだ。彼女は観察力が鋭く、', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b145387-S2EtnFw4OCje.png', '4月21日', NULL, '悠木碧', NULL, 145387, 'SUPPORTING', 113) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022195', 'AN1971', '塩崎茨', 'Quirk: Vine  Student in Class 1-B at U.A. High School.  Ibara is a very modest and courteous person. Although graceful and soft-spoken, she is not afraid to make her pure intentions known. She seems highly religious due to her talking about heaven and divine beings in passing on multiple occasions, and her ultimate moves having somewhat religious names such as "Faith''s Shield" and "Crucifixion".  Ibara''s Quirk "Vine (ツル, Tsuru) gives her hair-like vines that grow on her head. She can lengthen an', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b127426-Amaf70JKHWyn.png', '9月8日', 'AB', '真坂美帆', 167, 127426, 'SUPPORTING', 132) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022196', 'AN1971', '円場硬成', '所属：U.A.高校　クィーク：固体化空気　コセイは、非常に熱意にあふれ、競争心旺盛な人物であり、ライバルたちと同じレベルにまで落ちないよう、常に高い基準を自らに課して努力している。', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b208145-rhjugCBvoHTy.png', '5月19日', NULL, '福山潤', 170, 208145, 'SUPPORTING', 16) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022197', 'AN1971', '凡戸固次郎', '気さくな人で、「優しい巨人」と評されている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b208150-YjTVkA257Eva.jpg', NULL, NULL, '沖野晃司', NULL, 208150, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022198', 'AN1971', '回原旋', 'クィーク：「ジャイレート」　海原センは1年B組の生徒だ。彼のクィーク「ジャイレート」により、海原は体のどの部分でも回転させることができる。', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b164355-FbMi2hXpy7uz.png', '6月12日', NULL, '前野智昭', 172, 164355, 'SUPPORTING', 36) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022199', 'AN1971', '泡瀬洋雪', 'ヨセツは他の人ほど社交的ではないが、普段は無口で緊張気味だ。ただし、深刻な状況や生死にかかわる事態になると、非常に驚きやすくなり、口数もぐっと増える。とはいえ、そのきつい口調は変わらない。', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b208147-FyOhOQmU1bNs.jpg', NULL, NULL, '松岡禎丞', NULL, 208147, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022200', 'AN1971', '鱗飛竜', '個性：スケール  彼はU.A.高校の1-B組の生徒で、プロヒーローを目指して訓練に励んでいる。   飛龍は、自身の能力を実際に発揮する場面では、非常に真剣な態度を見せる点が特徴的だ。学業面でも、個性の活用においても、かなり勤勉である。 飛龍は、自身のクィークの活用法を熟知しており、非常に有能な戦闘員であることが示されている。「鱗」というクィークの汎用性の高さのおかげで、飛龍は近距離戦と遠距離戦の両方で優れた能力を発揮し、効果的に', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b208148-arAF2trr3C2J.png', '7月14日', 'A', '桑野晃輔', 170, 208148, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022201', 'AN1971', '柳レイ子', 'レイコは、物静かで感情を表に出さない10代の少女で、しばしば奇妙な姿勢をとることがある。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b208149-QVPxOrT9CjDR.jpg', '2月11日', NULL, '佐倉綾音', NULL, 208149, 'SUPPORTING', 56) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022202', 'AN1971', '天喰環', '個性：マニフェスト　U.A.高校3年A組の生徒であり、「ビッグ3」（日本一のヒーロー学生トップ3）の一人。　玉木は極めて内気で、人付き合いが苦手で、落ち込みやすく、「威圧的」で、内向的であり、特に大勢の人の前ではその傾向が顕著になる。 他人と話すときはすぐに緊張してしまう。不安に押しつぶされそうになると、玉木はしばしば背を向け、壁にもたれかかって顔を隠そうとする。身体能力や個性は抜群だが、玉木は社交的ではなく', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125934-luh5LqQ6NnJF.png', '3月4日', 'AB', '上村祐翔', 177, 125934, 'SUPPORTING', 4389) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022203', 'AN1971', 'コンプレス', 'コンプレス氏のクィークは、球状の範囲内にあるあらゆるものを、実際に損傷を与えることなく小さなビー玉のように「圧縮」することができる。 対象の重量も同時に軽減されるため、持ち運びが非常に容易になる。人物に使用した場合、事実上その人物を閉じ込めることになり、戦闘を即座に終結させ、コンプレス氏は難なくその人物を拉致することができる。また、このクィークは特定の身体部位にのみ使用し、対象に重傷を負わせることも可能である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b141748-ZlmszNufZ2me.png', '10月8日', NULL, '最上嗣生', NULL, 141748, 'SUPPORTING', 220) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022204', 'AN1971', '分倍河原仁', '特徴：ドブレ　「ヴィランズ・リーグ」に所属する悪役であり、その「ヴァンガード・アクション・スクワッド」の一員である。ジンは極めてユニークな性格の持ち主で、爆発的で活気にあふれ、非常にコミカルな振る舞いをする。ドラマチックなポーズや風変わりな表情を好んで見せる。 ジンは常に自分自身と矛盾しており、ある声で何かを言い放ったかと思えば、すぐに別の声で正反対のことを口にする。この対比は、ジンが悪役として自ら受け入れている精神的な不安定さの一端である。彼は、自分自身を理解することこそが', 31, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89589-0ICQRy2iXj2l.png', '5月10日', NULL, '遠藤大智', 178, 89589, 'SUPPORTING', 2167) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022205', 'AN1971', '常滑達行', 'プロヒーロー。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b149185-SwzuLpFzI1pI.png', NULL, NULL, '宮園拓夢', NULL, 149185, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022206', 'AN1971', '泡田薫子', 'Quirk: Bubble (バブル Baburu)   With this Quirk, Kaoruko can make bubbles filled with an aroma that she had smelled at least once before. She can make both sweet-smelling bubbles and foul-smelling ones. When she’s too nervous, she produces very unpleasant-smelling bubbles that are self-destructing   She is a dedicated hero as well as Sir Nighteyes sidekick', 21, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b141893-e29UnLY9LLsz.png', '4月23日', NULL, '村川梨衣', NULL, 141893, 'SUPPORTING', 74) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022207', 'AN1971', '百足従造', 'クィーク：ムカデ：ジュゾーのクィークは、ムカデのような長い手足を彼に与え、それを使って遠距離から敵を攻撃したり拘束したりすることができる。モアシは、サー・ナイトアイのヒーロー事務所に所属する相棒である。ジュゾーは紳士であり、非常に礼儀正しい人物だ。', 35, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b145290-f8YmIdnxCW3i.png', '6月4日', NULL, '大隈健太', NULL, 145290, 'SUPPORTING', 16) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022208', 'AN1971', '近属友保', '近属友保（通称「スケプティック」）は、メタ解放軍のメンバーである。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b160444-JvwnbYlLDYYI.png', NULL, NULL, '杉田智和', NULL, 160444, 'SUPPORTING', 18) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022209', 'AN1971', '外典', '外典は解放軍の忠実な戦士であり、その理念を深く信奉している。彼は、より大きな力を与えてくれたリ・デストロに対して多大な恩義と感謝の念を抱いており、最強の超能力者たちが階層の頂点に立つ世界を築きたいと願っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b160441-qN1xlkLJoQ26.jpg', NULL, NULL, '山下誠一郎', NULL, 160441, 'SUPPORTING', 32) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022210', 'AN1971', '気月置歳', '気月置歳（通称：キュリオス）は、ジャーナリストであり、メタ解放軍のメンバーである。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b160440-YNv7rS6h3wjl.png', NULL, NULL, '本田貴子', NULL, 160440, 'SUPPORTING', 35) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022211', 'AN1971', '花畑孔腔', '花畑孔腔（通称：トランペット）は、メタ解放軍のメンバーであり、超常解放戦線の副官であると同時に、「ハーツ・アンド・マインド」党の党首でもある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b160443-4ORO2GCwynKc.png', NULL, NULL, '間島淳司', NULL, 160443, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022212', 'AN1971', 'セルキー', '斑点アザラシができることのほとんどすべてができる。ソナーのような音波を発し、その反響を利用して相手の位置を特定することさえできる。また、自分ではとてもかわいいアザラシの顔を作れていると信じている（ほとんどの人はそうは思わないが）にもかかわらず、非常に力強い。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b210090-9LDPxejKK82l.jpg', NULL, NULL, '関智一', NULL, 210090, 'SUPPORTING', 23) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022213', 'AN1971', '绿谷引子', '緑谷出久の母親。彼女のクィックは、小さな物体を自分の方へ引き寄せることができる。', 41, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b136897-PGSMkwM1Nh4r.png', '7月4日', NULL, NULL, 160, 136897, 'SUPPORTING', 163) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022214', 'AN1971', 'サイダーハウスリーダー', '主にホリデーシーズンに活動していたスリ団のリーダーで、特定の通りにおけるヒーローや一般市民の行動パターンや動線を丸1ヶ月かけて綿密に調査し、抵抗を最小限に抑えつつ、盗んだ品物から得られる利益を最大化することを狙っていた。  彼は炭酸水を操るクィークを持っている。また、闇市場とのつながりもあり、デトネラットから提供された一対のガントレットを手にしており、それにより放出する水を冷気へと変換することができる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b242725-GKTUEP5OJRWG.png', NULL, NULL, NULL, NULL, 242725, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022215', 'AN1971', '日河原砂塵', 'クィーク：サンドストーム（日河原砂塵）、別名「サンド・ヒーロー：スナッチ」は、プロヒーローであり、警察のボディーガードでもあった。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b158616-HfRQpRl3Yobl.jpg', NULL, NULL, NULL, NULL, 158616, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022216', 'AN1971', '志村直', 'ナオは志村弧太朗の妻であり、二人の子供、天子と花の母親だった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b290002-rjvuYKreflYq.jpg', NULL, NULL, '湯屋敦子', NULL, 290002, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022217', 'AN1972', 'シンエイ・ノウゼン', 'シンエイ・ノウゼンは、スピアヘッド戦隊の現場指揮官である。彼のパーソナルネームは「アンダーテイカー」。東部戦線と特別偵察任務で5年間生き延びた経験を持ち、現存するプロセッサーの中でも最も精鋭の一人と見なされている。 「エイトシックス」の間では、「東部戦線の死神」として知られている。レギオンの声を聞き分ける能力により、レーダーなどの探知システムを使わなくてもレギオンの位置を特定することができる。共和国暦351年5月19日に生まれたシンは、家族と共に暮らしていた。', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b141060-ZJFvHqBBSvhN.png', '5月19日', NULL, '千葉翔也', 175, 141060, 'MAIN', 7934) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022218', 'AN1972', 'ヴラディレーナ・ミリーゼ', 'ヴラディレーナ・ミリーゼは、友人からは「レナ」、部下からは「ハンドラー・ワン」として親しまれている、わずか16歳という若さで少佐の階級に昇進した共和国精鋭の将校である。 彼女は「シンエイ・ノウゼン」および「スピアヘッド飛行隊」の指揮官であり、パラ・RAIDと呼ばれる長距離通信装置を通じて部隊と連絡を取り合っている。', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b141061-jqIhB9jmClQ3.png', '7月12日', NULL, '長谷川育美', 160, 141061, 'MAIN', 10159) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022219', 'AN1972', 'チセ・オーセン', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b210915-YJF4DmvjrBFW.png', NULL, NULL, '小野将夢', NULL, 210915, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022220', 'AN1972', 'ジェローム・カールシュタール', '彼は共和国軍においてレナの上司だった。レナの父親と親しい関係にあったため、レナは彼を叔父のように思っていた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b210920-oFo6r2yemLUb.jpg', NULL, NULL, '三上哲', NULL, 210920, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022221', 'AN1972', 'ハルト・キーツ', 'ハルトは飛行隊のムードメーカーで、いつも陽気で冗談を言うことが多い。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b210912-zBfDz63uEAAT.png', NULL, NULL, '山下大輝', NULL, 210912, 'SUPPORTING', 54) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022222', 'AN1972', 'レフ・アルドレヒト', 'スピアヘッド飛行隊の主任整備士。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b210921-xyo41JTWoBeB.png', NULL, NULL, '楠大典', NULL, 210921, 'SUPPORTING', 33) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022223', 'AN1972', 'ライデン・シュガ', 'ライデン・シュガは、スピアヘッド飛行隊の副隊長である。中尉として、シンが指揮を執るのに不適格とみなされた場合、第86ストライク・パッケージおよびその第1機甲師団の作戦指揮官を務める。彼の個人名はヴェールヴォルフである。 東部戦線や特殊偵察任務で長年にわたり生き延びてきた彼は、現存するプロセッサーの中でも最も精鋭の一人と見なされている。スピアヘッド飛行隊に加入する前に3年間、シンと共に過ごしたレイデンは、シンにとって最も親しい存在である。', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b174872-HrQxhw9BbfyI.jpg', '8月25日', NULL, '山下誠一郎', 185, 174872, 'SUPPORTING', 863) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022224', 'AN1972', 'ダイヤ・イルマ', 'ダイヤは第5小隊の隊長である。東部戦線で4年間従軍した精鋭として、「ブラック・ドッグ」というあだ名で知られている。彼とアンジュは徴兵されて以来、同じ中隊に所属しており、親しい友人同士である。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b210911-YtxQQzl8DBug.png', NULL, NULL, '石谷春貴', NULL, 210911, 'SUPPORTING', 82) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022225', 'AN1972', 'マイナ・ヤトミカ', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b210922-hKvw63IJ5F41.png', NULL, NULL, '風間万裕子', NULL, 210922, 'SUPPORTING', 57) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022226', 'AN1972', 'クレナ・ククミラ', 'クレナ・ククミラは、第86ストライク・パッケージのスピアヘッド飛行隊のプラトン・リーダーである。同飛行隊の長距離専門担当を務めている。彼女のパーソナルネームは「ガンスリンガー」である。 東部戦線や特殊偵察任務で長年にわたり生き延びてきた彼女は、現存するプロセッサーの中でも最も精鋭の一人と見なされている。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b174873-FNf08aPYTVXY.jpg', '5月6日', NULL, '鈴代紗弓', 160, 174873, 'SUPPORTING', 10064) ON CONFLICT DO NOTHING;
