INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022228', 'AN1972', 'アンリエッタ・ペンローズ', '共和国軍、後に第86ストライク・パッケージに所属した隊員。研究部門に配属され、父親が開発に携わったパラ・レイド・システムの研究を専門としている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b210923-q3ND01Sd08RP.png', NULL, NULL, '杉山里穂', NULL, 210923, 'SUPPORTING', 161) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022229', 'AN1972', 'セオト・リッカ', 'セオト・リッカは、第86ストライク・パッケージのスピアヘッド飛行隊のプラトン長であり、同飛行隊員のパーソナルマークの作者でもある。 彼のパーソナルネームは「ラフィング・フォックス」である。東部戦線や特殊偵察任務で長年にわたり生き延びてきた彼は、現存するプロセッサーの中でも最も精鋭の一人と見なされている。', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b174874-19TPZgyNwDtj.jpg', '4月20日', NULL, '藤原夏海', 165, 174874, 'SUPPORTING', 695) ON CONFLICT DO NOTHING;
