INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022234', 'AN1972', 'アンジュ・エマ', 'アンジュ・エマは、第86ストライク・パッケージのスピアヘッド飛行隊に所属するプラトンメンバーであり、後に同飛行隊のプラトンリーダーとなった。彼女は同飛行隊の支援射撃および砲撃を担当している。彼女の個人名は「スノー・ウィッチ」である。 東部戦線や特殊偵察任務で長年にわたり生き延びてきた彼女は、現存するプロセッサーの中でも最も精鋭の一人と見なされている。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b174875-PvSTadcuATtH.png', '10月2日', NULL, '早見沙織', 170, 174875, 'SUPPORTING', 1204) ON CONFLICT DO NOTHING;
