INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022236', 'AN1972', 'ヴァーツラフ・ミリーゼ', 'ヴァーツラフ・ミリゼは、ヴラディレーナ・ミリゼの父親であり、ジェローム・カールシュタールの友人でもあった。彼は共和国軍の隊員であった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b236363-uaCzhp8WZBqL.png', NULL, NULL, 'てらそままさき', NULL, 236363, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
