INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022239', 'AN1972', 'ファイド', 'ファイドは、スピアヘッド・スクワドロン所属のM101バレット・スカベンジャードローンである。 スカベンジャーとして、ファイドは弾薬の補給やエネルギーパックの充電を行うほか、放棄されたり破壊されたりしたユニットから資材を探し出し回収することで、飛行隊を支援している。彼はシンエイ・ノウゼンと共に東部戦線やその先での戦いを経てきたため、シンにとって現存する最古参の仲間となっている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b237557-uBOohJFKv5h9.jpg', NULL, NULL, NULL, NULL, 237557, 'SUPPORTING', 393) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022240', 'AN1973', '酒爺', 'グーグーを救った老人であり、ピオランの恋人でもある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b136555-q0JF1MY0Mo9r.jpg', NULL, NULL, '利根健太朗', NULL, 136555, 'SUPPORTING', 44) ON CONFLICT DO NOTHING;
