INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022244', 'AN1973', 'エラン・ジー・ダルトン', 'トナリの父親。妻を殺害した容疑をかけられ、ジャナンダ島に送られた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b202670-W00FnDtypJMi.png', NULL, NULL, NULL, NULL, 202670, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022245', 'AN1973', 'ハヤセ', '居住地：ヤノメ　所属：ガーディアンフォース（元）  親族：ヒサメ（孫娘）、オミ（曾孫娘）、ウシオ（子孫）、チスイ（子孫）、カハク（子孫）、ミズハ（子孫（18代目））　身分：　ヤノメの政府高官である。 彼女は、スピリット・ベアのための「ニナンナ」の生贄の儀式を監督する役割に選ばれた。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b136545-KsqBpXbhEUCd.png', NULL, NULL, '斎賀みつき', NULL, 136545, 'SUPPORTING', 193) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022246', 'AN1973', 'イゴス・クロップ', 'イゴス・クロップは、タクナハの裕福な家庭の出身であり、リーン・クロップの父親である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b244762-tx24xVAHVw9g.png', NULL, NULL, '堀総士郎', NULL, 244762, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022247', 'AN1973', '少年', 'これは、主人公が初めて出会う人間、あるいは主人公が初めて変身できる人間の姿である。主人公が変身したこの少年の姿は「フシ」と呼ばれる。少年の本名は一度も明かされていない。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b201555-goJeA6E0Xuww.jpg', NULL, NULL, '川島零士', NULL, 201555, 'SUPPORTING', 470) ON CONFLICT DO NOTHING;
