INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022250', 'AN1974', '長瀞早瀬', 'いつでもどこでも突然現れる女子高生。先輩のことにはいつも夢中だ。水泳部の部員らしい。長瀧は、元気でスポーツ万能、人気者で、少々サディスティックな一面もあるが、心の奥底はとても優しい女の子で、よく「サドデレ」と呼ばれる。 彼女は、友人の蒲生ちゃん、ヨッシー、桜と共に「クールな子たち」のグループに属しており、水泳部の部員でもあるが、ムエタイ、ボクシング、カポエイラなどの格闘技にも興味を持っている。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b124696-du2Kszxelh1S.png', '4月1日', NULL, '上坂すみれ', 150, 124696, 'MAIN', 5347) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022251', 'AN1974', '八王子直人', '高校生であり美術部の部員でもある彼は、自作の漫画を描いたり、後輩の長門と出会ってからは彼女の静止画を描いたりすることを楽しんでいる。放課後は、ほとんど毎日、長門と一緒に美術部で過ごし、そこでとんでもない騒動が繰り広げられる。 彼は内向的で、神経質、一匹狼、オタクで、内気な志望アーティストであり、他人との交流を避けようとしており、友達はいないようだ。また、長門からは「隠れ変態」と呼ばれている。', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b124697-JDDbhuzV6HXN.jpg', '5月10日', NULL, '山下大輝', 176, 124697, 'MAIN', 962) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022252', 'AN1974', '蒲生', '中くらいの長さの髪をしたキャラクター。人をからかうのが好きだ。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b145715-G5GLMaYmUHyo.jpg', '6月15日', NULL, '小松未可子', 168, 145715, 'SUPPORTING', 494) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022253', 'AN1974', 'オタク', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b230395-WyhHQjnN2nSx.png', NULL, NULL, '柳田淳一', NULL, 230395, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022254', 'AN1974', '桜', '日焼けした肌と柔らかなウェーブのかかった髪をした少女。実は「ハラグロ」な性格だ。（ハラグロ：外見は親切で友好的だが、その性格を他人を操る手段として利用しているキャラクターのこと。）', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b145716-HQmY6lFKez9s.jpg', '9月4日', NULL, '井澤詩織', 157, 145716, 'SUPPORTING', 332) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022255', 'AN1974', 'ヨッシー', '生まれつきの天然でツインテールの女の子。蒲生ちゃんを好きで、よく彼女の言ったことを繰り返したり、その直後に同じことを言ったりするおバカさんだ。 ヨッシーは、ゴリラのTシャツを着ている姿が見られたり、飼い犬を飼っていたりするなど、動物も好きなようだ。また、あるコンテストで、先輩と引き換えにナガトロから「スクイディ」のぬいぐるみを受け取ったこともあることから、かわいいものも好きなようだ。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b145718-IKqQxlLIoohE.jpg', '11月23日', NULL, '鈴木愛奈', 160, 145718, 'SUPPORTING', 465) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022256', 'AN1974', '須ノ宮さな', '美術部の部長。長い髪が顔を縁取り、瞳は濃い茶色をしている。先輩とのやり取りを見る限り、性格は厳格で真面目だが、長瀧とは異なり、先輩に対しては敬意を持って接している。また、先輩が執筆したある漫画の女性キャラクターに似ている。   そのみやは彼女の年下のいとこである。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b145717-xWPkoY8gFYuy.jpg', '6月19日', NULL, '水樹奈々', 171, 145717, 'SUPPORTING', 545) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022257', 'AN1975', '荻原沙優', '荻原沙優は、『ひげを剃る。そして女子高生を拾う。』のヒロインである。彼女は北海道から家出をして東京にたどり着いた女子高生で、そこで「吉田」という名の見知らぬ男性と運命的な出会いを果たした。  明確な理由もなく故郷や家族から家出した沙優は、家出少女としての新しい生活に適応し、生きていくことを余儀なくされた。食料や住居といった基本的な生活費すら持たない彼女は、覚悟を決めて男性を誘惑することに頼るようになった。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b127925-i0JAx5K81uDQ.png', NULL, NULL, '市ノ瀬加那', NULL, 127925, 'MAIN', 2097) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022258', 'AN1975', '吉田', '吉田は、『ひげを剃る。そして女子高生を拾う。』シリーズの主人公である。東京で一人暮らしの会社員だ。 ある夜、上司の後藤愛依梨に振られた後、彼はサユという家出中の女子高生と運命的な出会いを果たした。 人生の大半を一人暮らしで過ごしてきた吉田は、非常に自立した人間に成長していた。 彼は、常に仕事に献身的な、並外れて頼りになる社員であり、毎日残業をこなすだけでなく、', 26, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b127924-UcmUep3PZq6G.jpg', NULL, NULL, '興津和幸', NULL, 127924, 'MAIN', 807) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022259', 'AN1975', '結城あさみ', '東京のコンビニで同じアルバイトをしている、ギャルな先輩で、サユの親友。（出典：ヒゲヒロWiki）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b135016-c2HF3BN3RERD.jpg', NULL, NULL, '川井田夏海', NULL, 135016, 'SUPPORTING', 218) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022260', 'AN1975', '荻原一茶', 'オギワラ・フーズ社のCEOであり、荻原沙優の兄。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b184100-8JD5pDzFfQXU.jpg', NULL, NULL, '鳥海浩輔', NULL, 184100, 'SUPPORTING', 39) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022261', 'AN1975', '三鳥柚葉', '吉田が指導を担当している新入社員。よくミスを犯すが、その愛嬌のある笑顔のおかげで、いつも何とかトラブルを乗り切っている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b127928-LkYiVsW1I9zF.jpg', NULL, NULL, '石原夏織', NULL, 127928, 'SUPPORTING', 240) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022262', 'AN1975', '沙優の母', '冷淡で無関心な人物として描かれており、家族経営の事業におけるサユの兄の功績しか気にかけていない。サユに対しては冷たく、彼女をあまり気にかけていない。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b233186-IL7MGnkKzODA.jpg', NULL, NULL, '柚木涼香', NULL, 233186, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022263', 'AN1975', '後藤愛依梨', '吉田の上司。その上品な物腰と他者への気遣いから、社内で憧れの的となっている人物。吉田が5年間片思いし続けている相手である。', 28, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b127927-t90fVl4yUM1k.png', NULL, NULL, '金元寿子', NULL, 127927, 'SUPPORTING', 590) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022264', 'AN1975', '橋本', '吉田の同僚であり、親しい友人。（出典：『ひげを剃る。そして女子高生を拾う。』Wiki）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b184775-eSOS9MLrC81T.jpg', NULL, NULL, '小林裕介', NULL, 184775, 'SUPPORTING', 15) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022265', 'AN1975', '矢口恭弥', '彼はユキやサユと同じ店で働いており、サユの過去に関わる人物だ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b184770-KX7FluEQhol6.jpg', NULL, NULL, '逢坂良太', NULL, 184770, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022266', 'AN1975', '遠藤', '彼は吉田さんの同僚です。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b184006-mfg6PvHvLpfv.jpg', NULL, NULL, '河西健吾', NULL, 184006, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022267', 'AN1976', 'マツモト', 'マツモトは、100年先の未来からヴィヴィのもとへやってきたAIです。AIとしてのその使命は、「AIと人類の戦争を防ぐこと」です。 そのために、ヴィヴィと共にAIを破壊することを目標としている。おしゃべりで自信過剰、AIらしからぬ性格の持ち主だ。（出典：公式サイト、翻訳）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b209902-Ty8ihQLkX7EN.png', NULL, NULL, '福山潤', NULL, 209902, 'MAIN', 548) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022268', 'AN1976', 'ヴィヴィ', 'ヴィヴィは、史上初の自律型ヒューマノイドAIです。AIとしての彼女の使命は、歌を通じてすべての人を幸せにすることであり、そのため、心を込めて歌うことを目指しています。彼女は約束や感情を非常に大切にし、人類に奉仕するAI「ディーバ」です。（出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b209903-ue6AE5qBvMgI.png', '6月19日', NULL, '種﨑敦美', NULL, 209903, 'MAIN', 3568) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022269', 'AN1976', 'ナビ', 'ニアランドの従業員が使用しているナビゲーションシステム。蛾のキャラクターがいて、ヴィヴィにきつい口調で話しかける。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b216426-rbkCds1QCWNy.jpg', NULL, NULL, '泊明日菜', NULL, 216426, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022270', 'AN1976', 'M-00205', '無人海洋施設「メタル・フロート」で稼働する土木工学用AI。AIとしての使命は、「人類の利益のためにメタル・フロートの開発に貢献すること」である。このAIは、島内に存在する他のいくつかのAIと同じ構成となっている。（公式サイト、翻訳）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b220599-VJO8UJrkNiui.jpg', NULL, NULL, '福島潤', NULL, 220599, 'SUPPORTING', 29) ON CONFLICT DO NOTHING;
