INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022273', 'AN1976', 'オフィーリア', 'オフィーリアは、世界中の小劇場で活躍するディーバAIです。AIとしての彼女の使命は、ヴィヴィと同じように「歌でみんなを幸せにすること」です。普段は少し内気でだらしがないところもありますが、ステージでは最高のパフォーマンスを披露します。（出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b215278-t60BQZFE3cFG.jpg', NULL, NULL, '日高里菜', NULL, 215278, 'SUPPORTING', 90) ON CONFLICT DO NOTHING;
