INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022276', 'AN1976', 'エステラ', 'エステラは、大気圏外の宇宙ホテル「サンライズ」で働くAIスタッフです。AIとしての彼女の使命は、「ライフキーパーとして人間を世話すること」です。彼女は礼儀正しく、寛容で、親しみやすい性格です。（出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b215276-n3AoeL09uMiH.jpg', NULL, NULL, '日笠陽子', NULL, 215276, 'SUPPORTING', 107) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022277', 'AN1976', '垣谷ユウゴ', '反AIテロ組織「トアク」のメンバー。幼い頃から、トアクの活動を積極的に世間に広めてきた。ヴィヴィは任務中に彼と遭遇する。（出典：公式サイト、翻訳）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b216437-bSzmoCQW57pi.jpg', NULL, NULL, '新垣樽助', NULL, 216437, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
