INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022279', 'AN1976', 'グレイス', 'グレイスは、病院や研究機関で働くAI看護師です。AIとしての彼女の使命は、「AI看護師として人命を救うこと」です。彼女は、患者に安心感を与えるため、常に笑顔を絶やさず、丁寧な口調で話す、白衣の天使です。（出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b215277-oVp9PmhAc12E.png', NULL, NULL, '明坂聡美', NULL, 215277, 'SUPPORTING', 65) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022280', 'AN1976', 'ルクレール', '宇宙ホテル「サンライズ」で働くAI。エステラの古くからの同僚で、おしゃべりな性格だ。（公式サイトより、翻訳）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b217728-StkAWMpSvP0h.jpg', NULL, NULL, '山根綺', NULL, 217728, 'SUPPORTING', 18) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022281', 'AN1976', 'アントニオ', 'オフィーリアのパートナーAI。その使命は、サウンドマスターAIとしてオフィーリアをサポートすることだ。口調はきついこともあるが、オフィーリアの歌手としての才能を認めている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b225837-yZmBdvZogkTR.jpg', NULL, NULL, '小山力也', NULL, 225837, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022282', 'AN1976', '霧島モモカ', 'Momoka was helped by Diva once when she got lost in NiaLand, since then she has grown attached to her and deeply cares about her she gave her nickname Vivy (ヴィヴィ).', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b216423-LqLmJ7KJ5fjT.jpg', NULL, NULL, '富田美憂', NULL, 216423, 'SUPPORTING', 22) ON CONFLICT DO NOTHING;
