INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022284', 'AN1976', '垣谷ユイ', '垣谷ユウゴの孫娘であり、トアックのメンバー。AIとの共存を目指す穏健派グループのリーダーである。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b231664-NA1x71XvXXf7.jpg', NULL, NULL, '朝井彩加', NULL, 231664, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022285', 'AN1976', '松本オサム', '「マツモト」を100年前に送り込み、歴史を変えるAI研究者。彼はマツモト用のAIを開発した人物であり、この分野における世界屈指の専門家の一人である。（出典：公式サイト、翻訳）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b216424-WPce9wRsYH87.jpg', NULL, NULL, '子安武人', NULL, 216424, 'SUPPORTING', 79) ON CONFLICT DO NOTHING;
