INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022287', 'AN1976', '相川ヨウイチ', 'AIに人権を認める「AI命名法」の成立に向けて取り組んでいる州議会議員。人当たりは良いが、特筆すべき実績はない。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b216425-x180DPnFLTci.jpg', NULL, NULL, '加藤将之 ', NULL, 216425, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022288', 'AN1976', 'エリザベス', 'エステラの双子の妹。エステラと同時に生み出されたが、実験の末に廃棄された。その後、反AI組織「トアク」に保護され、そこで戦闘能力を身につけた。エステラに比べ、性格は非常に攻撃的である。（出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b218484-RimHPK0rmery.jpg', NULL, NULL, '内山夕実', NULL, 218484, 'SUPPORTING', 92) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022289', 'AN1977', '草摩慊人', 'アキトは相馬一族の当主だが、非常に虚弱である。頻繁に高熱を出し、外の世界に住むユキやシグレといった十二支のメンバーに挨拶をする時を除いて、本邸の外に出ることはめったにない。 アキトには紛れもない冷酷な一面があり、相馬家の多くの者に肉体的・精神的な傷を負わせてきたが、相馬一族におけるアキトの支配は絶対的であり、誰も彼に逆らうことはできない。アキトの呪いの一因として、彼が30歳までしか生きられないという説もある。ある時点で', 19, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b374-8BT4gMd8xyl5.png', NULL, NULL, '坂本真綾', NULL, 374, 'MAIN', 766) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022290', 'AN1977', '草摩紅葉', '干支：兎　明るく幸せそうに見える10代の少年だが、その陽気な態度の裏には、悲しい家庭環境が隠されている。 彼の絶え間ない愚痴や泣き言は、しばしば京を苛立たせる。彼は見た目より年上で、透を驚かせたことに、由紀よりわずか1歳年下であり、京とは初春と同じ年齢である。 モミジは十二支の「兎」であり、相馬家の比較的裕福な一族の息子である。父親は日本人で、母親はドイツ人だ。トーリは知らず知らずのうちに、モミジの父親の車を掃除してしまう。', 15, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b367-Jc6wMVpL76Ib.png', NULL, NULL, '潘めぐみ', NULL, 367, 'SUPPORTING', 2654) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022291', 'AN1977', '藤堂公', '彼女は生徒会に所属していて、「悪魔のような女性」として知られている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b6572-QnQqn3nrVMV9.png', NULL, NULL, '大久保瑠美', NULL, 6572, 'SUPPORTING', 53) ON CONFLICT DO NOTHING;
