INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022293', 'AN1977', '草摩潑春', '学年／学校：海原高校1年生　干支：丑　丑年生まれのハルは、丑の性格に由来する陰と陽の両面を併せ持つような性格だ。 普段は穏やかで物静か、何と言っても好青年だが、煽られると「暴走」状態になり、その時は神経質で意地悪になり、性欲がやや高ぶってしまう。ホワイト・ハルは「ブラック」に変身している間も意識はあるが、それを止めることはできない。 彼はただ謝るか、あるいは気にも留めないかのどちらかだ。さらに、ハルのセ', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b369-NDFi2A2BzqO6.png', NULL, 'O', '古川慎', NULL, 369, 'SUPPORTING', 4113) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022294', 'AN1977', '桜木直人', 'ユキをライバルと見なし、モトコに想いを寄せている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b6573-SDj1s63gWr9I.jpg', NULL, NULL, '市川蒼', NULL, 6573, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022295', 'AN1977', '倉前美音', '倉前美音は、草摩綾目の服飾店でデザイナー兼裁縫師として働き、店の上にあるアパートで彼と同居している。情熱的で陽気な性格で、綾目のためなら何でもする覚悟がある。綾目が熱意のあまり見落としがちな細かいこと、例えば由紀のクラスへの訪問許可を得るといったことも、彼女がしっかりと引き受けてくれる。 高屋夏樹によれば、綾目のペースについていける彼女は「素晴らしい人」だという。彼女は、自分の作った服で女の子たちを着飾らせることに特に情熱を注いでいる様子が描かれている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b13956-qRFyJI2pS9GS.png', NULL, NULL, '井口裕香', NULL, 13956, 'SUPPORTING', 48) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022296', 'AN1977', '草摩五月', '草摩さつきは、ヒロと草摩日向の母親である。  （出典：フルーツバスケット・ファンダム）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b243718-qI4POBMuf17s.png', NULL, NULL, '高橋美佳子', NULL, 243718, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022297', 'AN1977', '白木繭子', 'Mayuko Shiraki (白木 繭子, Shiraki Mayuko) is Tohru, Kyo, Yuki, Saki, and Arisa''s homeroom teacher; what subject she teaches is never given, though in an author''s note, Natsuki Takaya said she thinks Shiraki fits the image of a literature teacher. Shiraki is depicted as generally good-humored but sometimes aggressive—when Kyo attempts to leave class on Valentine''s Day, she stops him at the door with a folder in his face and threatens to dye his hair black instead of orange, and once breaks up a figh', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b27831-kQaWdyJjdO7H.png', NULL, NULL, '生天目仁美', NULL, 27831, 'SUPPORTING', 102) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022298', 'AN1977', '草摩綾女', '干支：蛇　干支の「蛇」であり、ユキの兄であるアヤメは、活発でおしゃべりで、ユキやキョウを怒らせるのが得意だ。彼は婦人服の製造・販売業を営んでおり、その服は男性も着ているらしい。彼自身もよく婦人服を着ている。 彼は自分の名前を店名にし、後にアヤメの恋人であり、店の仕立て屋であることが明らかになるミネと共に店を経営している。アヤメはドレスのデザインを担当しており、その中にはエロティックなものもいくつか、あるいはすべて含まれているかもしれない。虚栄心が強く、やや自己中心的な', 27, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b370-cdEW33vBsXBL.png', NULL, NULL, '櫻井孝宏', NULL, 370, 'SUPPORTING', 1570) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022299', 'AN1977', '真鍋翔', '漫画の第49話（第9巻）で初登場した真鍋は、当初は少々怠け者だが、社交的で陽気な青年として描かれており、それ以来その性格は変わっていない。 海原高校の生徒会副会長を務めるカケルは、「学校防衛隊の副隊長」であり、自身が「スーパー戦隊」のような仕事だと考えているその役割に情熱を注いでいる。彼はよく、自分は「ブラック」 （ゴレンジャーの「黒」のように）とよく口にする一方、ユキは「赤」だ（', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b4957-fNOpYP6mIeWu.png', NULL, NULL, '江口拓也', NULL, 4957, 'SUPPORTING', 457) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022300', 'AN1977', '本田今日子', '透の母親：京子は若い頃、トラブルを起こしたり学校をサボったりしており、暴力団同士の抗争をきっかけに両親から勘当された。父親は「この世に京子など必要ない」と考えており、母親は家族の体面ばかりを気にかけていたため、彼女は家族を憎んでいた。 また、彼女は女子だけの自殺ギャングのリーダーでもあった。そこでは「赤い蝶」と呼ばれていたが、この名前は、夜間にバイクを走らせると、テールライトが鮮やかな赤い蝶のように舞うという伝説に由来している。', 33, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b9754-PGxNeo2JwGx9.jpg', NULL, NULL, '沢城みゆき', NULL, 9754, 'SUPPORTING', 753) ON CONFLICT DO NOTHING;